local config = {
  ui_story_5081_50810100_1_dialog_content = "(No vento soprando e nas areias escaldantes, meus companheiros restantes e eu fazemos uma tentativa desesperada de escapar...)",
  ui_story_5081_50810100_2_dialog_content = "(Atrás de nós surge um mar de Eclipsitas...)",
  ui_story_5081_50810100_3_dialog_content = "(E à nossa frente está um enorme castelo, um símbolo de esperança e desespero...)",
  ui_story_5081_50810100_4_dialog_content = "(Mas agora parece uma miragem distante, uma bolha etérea que nunca deveria ser tocada.)",
  ui_story_5081_50810100_5_dialog_content = "Isso é realmente o fim?",
  ui_story_5081_50810100_6_dialog_content = "Droga... Parece que não vou conseguir chegar em casa desta vez! Argh!",
  ui_story_5081_50810100_7_dialog_content = "Chilro! Sork, não!",
  ui_story_5081_50810100_8_dialog_content = "Estou indo com você! Somos parceiros até o fim amargo, piu...",
  ui_story_5081_50810100_9_dialog_content = "Sork! Bekk!",
  ui_story_5081_50810100_10_dialog_content = "Agora não é a hora de lamentar pelos seus camaradas caídos...",
  ui_story_5081_50810100_11_dialog_content = "Odeio admitir, mas agora... você é nossa última esperança de sobrevivência!",
  ui_story_5081_50810100_12_dialog_content = "Não pare! Continue não importa o que aconteça!",
  ui_story_5081_50810100_13_dialog_content = "Odi!",
  ui_story_5081_50810100_14_dialog_content = "E-Eu vou continuar com a sua vontade! Juro que vou chegar ao castelo e encontrá-la...",
  ui_story_5081_50810100_15_dialog_content = "Não, espera, eu estava prestes a dizer algo legal...",
  ui_story_5081_50810100_16_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5081_50810100_17_dialog_content = "Acabou...",
  ui_story_5081_50810100_18_dialog_content = "Desculpe a todos, mas eu... não fui capaz de...",
  ui_story_5081_50810100_19_dialog_content = "...",
  ui_story_5081_50810100_20_dialog_content = "<color=#e8d9bb>Bip, bip!</color>",
  ui_story_5081_50810100_21_dialog_content = "Perdemos novamente!",
  ui_story_5081_50810100_22_dialog_content = "Acho que realmente não podemos vencer este nível sem o \"B\", muito menos atingir aquele ranking alto.",
  ui_story_5081_50810100_23_dialog_content = "Mas \"B\" já deixou sua posição perfeitamente clara...",
  ui_story_5081_50810100_24_dialog_content = "Você... não gosta de jogar, gosta?",
  ui_story_5081_50810100_25_dialog_content = "Peço desculpas... Eu nunca deveria ter incomodado você!",
  ui_story_5081_50810100_26_dialog_content = "Agora que o \"B\" não me suporta, realmente não há nada que possamos fazer?",
  ui_story_5081_50810100_27_dialog_content = "<color=#e8d9bb>Tudo começou há alguns dias quando apareceu um pedido urgente da Federação Illumina.</color>",
  ui_story_5081_50810100_28_dialog_content = "Realmente, eu não queria vir para a Illumina nessa época.",
  ui_story_5081_50810100_29_dialog_content = "Todo mundo está tão ocupado... Parece que uma tempestade enorme está se formando.",
  ui_story_5081_50810100_30_dialog_content = "!",
  ui_story_5081_50810100_31_dialog_content = "Hã? Não é aquele Oficial de Inteligência Yingel?",
  ui_story_5081_50810100_32_dialog_content = "...",
  ui_story_5081_50810100_33_dialog_content = "Sh-Ela me ignorou completamente!",
  ui_story_5081_50810100_34_dialog_content = "Ela parecia muito estressada, embora... Ela não está no meio de outra missão secreta, está?",
  ui_story_5081_50810100_35_dialog_content = "Você apareceu bem na hora, PlayerName.",
  ui_story_5081_50810100_36_dialog_content = "Ah, na verdade, acabei de chegar.",
  ui_story_5081_50810100_37_dialog_content = "Vamos dispensar a conversa fiada. Você deveria saber que essa não é a razão pela qual pedi para me encontrar com você desta vez.",
  ui_story_5081_50810100_38_dialog_content = "O Comitê está fazendo muitos ajustes novos em sua estrutura. Naturalmente, isso colocou uma tensão considerável em todos os nossos laboratórios de pesquisa e desenvolvimento...",
  ui_story_5081_50810100_39_dialog_content = "Dizer que todo projeto está uma bagunça total agora seria um eufemismo.",
  ui_story_5081_50810100_40_dialog_content = "Então... você está me pedindo ajuda?",
  ui_story_5081_50810100_41_dialog_content = "Embora você possa não ser capaz de ajudar com os próprios projetos...",
  ui_story_5081_50810100_42_dialog_content = "Eu tenho uma tarefa que é perfeitamente adequada às suas habilidades.",
  ui_story_5081_50810100_43_dialog_content = "Qual é a tarefa?",
  ui_story_5081_50810100_44_dialog_content = "Gostaria que você investigasse o paradeiro da Oficial de Tecnologia Gronru. Ela desapareceu repentinamente de seu posto há alguns dias e não foi vista desde então.",
  ui_story_5081_50810100_45_dialog_content = "Gronru? Ela desapareceu?",
  ui_story_5081_50810100_46_dialog_content = "Isso mesmo. Nossas fontes indicam que ela já deixou Illumina, mas seu paradeiro atual é desconhecido.",
  ui_story_5081_50810100_47_dialog_content = "Estamos no meio dos tempos conturbados da Federação Illumina. Se essa notícia se espalhar...",
  ui_story_5081_50810100_48_dialog_content = "\"Ela desertou da Illumina? Ela poderia estar trabalhando com o inimigo? Ou talvez ela tenha sido uma espiã para os Fantasmas o tempo todo?\"",
  ui_story_5081_50810100_49_dialog_content = "... É possível que qualquer um desses rumores se espalhe como fogo selvagem.",
  ui_story_5081_50810100_50_dialog_content = "Isso é um pouco demais!",
  ui_story_5081_50810100_51_dialog_content = "(De qualquer forma, eu deveria tentar entrar em contato com a Gronru no terminal dela...)",
  ui_story_5081_50810100_52_dialog_content = "Temo que seja a verdade. Dadas as circunstâncias atuais, evitar esse tipo de especulação pública é nossa principal prioridade.",
  ui_story_5081_50810100_53_dialog_content = "Um número de nossas próprias pessoas já foi designado para tratar deste assunto através dos canais oficiais.",
  ui_story_5081_50810100_54_dialog_content = "Na verdade, ouvi dizer que a Federação Illumina está preparada para mobilizar toda a sua rede de inteligência continental para caçá-la.",
  ui_story_5081_50810100_55_dialog_content = "Uh-oh—",
  ui_story_5081_50810100_56_dialog_content = "Então... O que eles vão fazer com Gronru quando a encontrarem? Eles não vão puni-la, vão?",
  ui_story_5081_50810100_57_dialog_content = "Quem sabe? Afinal, essa não é minha área de especialização.",
  ui_story_5081_50810100_58_dialog_content = "Por precaução, ou talvez por medo de criar um conflito ainda maior, o Comitê me perguntou se eu tinha outras soluções.",
  ui_story_5081_50810100_59_dialog_content = "Foi quando decidi te procurar com essa missão.",
  ui_story_5081_50810100_60_dialog_content = "Precisamos que você encontre nossa colega desaparecida e a traga de volta antes que medidas oficiais sejam tomadas.",
  ui_story_5081_50810100_61_dialog_content = "Eu entendo, mas eu tenho que perguntar...",
  ui_story_5081_50810100_62_dialog_content = "Será que Gronru saiu por causa de como está ocupado em Illumina agora?",
  ui_story_5081_50810100_63_dialog_content = "Talvez o estresse tenha afetado ela, então ela precisou se afastar do trabalho por um tempo?",
  ui_story_5081_50810100_64_dialog_content = "Quem pode dizer que ela não aparecerá em Illumina assim que eu sair?",
  ui_story_5081_50810100_65_dialog_content = "Infelizmente, isso não é possível.",
  ui_story_5081_50810100_66_dialog_content = "Pessoas comuns nunca poderiam entender Gronru quando se trata de estresse.",
  ui_story_5081_50810100_67_dialog_content = "Aquela garota sempre teve um fraco senso de moralidade, então algo assim nunca a faria se sentir estressada.",
  ui_story_5081_50810100_68_dialog_content = "Na verdade, essa é precisamente a razão pela qual a colocamos no comando dos projetos de desenvolvimento mais importantes de Illumina.",
  ui_story_5081_50810100_69_dialog_content = "Você está certo. Gronru é um gênio... mas ela ainda precisa de um descanso do trabalho de vez em quando.",
  ui_story_5081_50810100_70_dialog_content = "De qualquer forma, estamos contando com você. Você não quer que Gronru caia nas mãos enrugadas e velhas do Comitê, quer?",
  ui_story_5081_50810100_71_dialog_content = "Você não precisa colocar dessa maneira. Estou disposto a ajudar de qualquer forma!",
  ui_story_5081_50810100_72_dialog_content = "É só que Gronru tem um monte de hobbies, o que significa que ela poderia estar em quase qualquer lugar do mundo.",
  ui_story_5081_50810100_73_dialog_content = "Ela pode estar alimentando os pombos em Lumopolis durante o dia e depois assistindo a uma peça na Baía dos Pavilhões Gêmeos à noite.",
  ui_story_5081_50810100_74_dialog_content = "Viajar para todos esses lugares não será barato, especialmente para mim...",
  ui_story_5081_50810100_75_dialog_content = "Não se preocupe com os custos. Vou conversar com o Comitê e garantir que você seja devidamente compensado.",
  ui_story_5081_50810100_76_dialog_content = "Afinal, encontrar o Oficial de Tecnologia mais cedo minimizará o dano à Illumina. Tenho certeza de que eles entenderão.",
  ui_story_5081_50810100_77_dialog_content = "Eu agradeço! Ah, tem mais uma coisa...",
  ui_story_5081_50810100_78_dialog_content = "Encontrei a Oficial de Inteligência Yingel agora mesmo, e ela parecia realmente preocupada. Ela nem sequer me cumprimentou ou algo assim.",
  ui_story_5081_50810100_79_dialog_content = "Ela está bem?",
  ui_story_5081_50810100_80_dialog_content = "Yingel, é... Com tudo que tem acontecido ultimamente, a posição dela foi ainda mais afetada do que a dos outros.",
  ui_story_5081_50810100_81_dialog_content = "É possível que ela esteja se jogando em seu trabalho para evitar pensar em outros assuntos.",
  ui_story_5081_50810100_82_dialog_content = "... Tem certeza de que vocês não estão apenas forçando ela a fazer hora extra?",
  ui_story_5081_50810100_83_dialog_content = "Ao contrário, todos aqui desejam que ela pare de se esforçar tanto.",
  ui_story_5081_50810100_84_dialog_content = "Não importa como você olhe, ela é uma membro importante e talentosa da Federação Illumina. Horas extras excessivas são tão inaceitáveis quanto abandonar o posto sem permissão.",
  ui_story_5081_50810100_85_dialog_content = "Se você diz... Acho que todos em Illumina estão passando por momentos difíceis agora.",
  ui_story_5081_50810100_86_dialog_content = "Deixe a busca por Gronru comigo.",
  ui_story_5081_50810100_87_dialog_content = "Somos amigos há muito tempo, então tenho algumas ideias de onde ela poderia estar.",
  ui_story_5081_50810100_88_dialog_content = "Vou mantê-lo atualizado!",
  ui_story_5081_50810100_89_dialog_content = "(Vamos listar os lugares onde Gronru pode estar—)",
  ui_story_5081_50810100_90_dialog_content = "(O lugar mais provável é Umbraton, a capital do entretenimento de Astra!)",
  ui_story_5081_50810100_91_dialog_content = "Técnicas de ponta para impressionar o mundo inteiro! O trabalho magistral do mais novo diretor do Teatro Bons Sonhos será revelado esta noite!",
  ui_story_5081_50810100_92_dialog_content = "Apresentações que abalam o palco! Um banquete suntuoso para os sentidos! O encontro anual de músicos lendários começa hoje!",
  ui_story_5081_50810100_93_dialog_content = "... Apenas olhe para essas multidões!",
  ui_story_5081_50810100_94_dialog_content = "Todos os locais estão lotados de visitantes. Encontrar Gronru nessa bagunça será como encontrar uma agulha no palheiro...",
  ui_story_5081_50810100_95_dialog_content = "Não há resposta no terminal também... Parece que este jogo de esconde-esconde não vai acabar tão cedo.",
  ui_story_5081_50810100_96_dialog_content = "O que devo fazer... Ahn? É isso—",
  ui_story_5081_50810100_97_dialog_content = "...",
  ui_story_5081_50810100_98_dialog_content = "O que a Rediesel Wrench está fazendo aqui?",
  ui_story_5081_50810100_99_dialog_content = "E por que eles estão se movendo sorrateiramente assim? Eles não estão aqui para causar problemas, estão?",
  ui_story_5081_50810100_100_dialog_content = "Se eles começarem uma briga com as gangues locais agora, as coisas só vão ficar mais difíceis para mim.",
  ui_story_5081_50810100_101_dialog_content = "Eu deveria ir avisá-los.",
  ui_story_5081_50810201_1_dialog_content = "Pressa! Vamos alcançar!",
  ui_story_5081_50810201_2_dialog_content = "Heheh, alvo bloqueado!",
  ui_story_5081_50810201_3_dialog_content = "Aham—",
  ui_story_5081_50810201_4_dialog_content = "?",
  ui_story_5081_50810201_5_dialog_content = "Com licença, mas o que exatamente vocês dois pensam que estão fazendo?",
  ui_story_5081_50810201_6_dialog_content = "Tsk, então você também está aqui, PlayerName...",
  ui_story_5081_50810201_7_dialog_content = "Não me diga que você está competindo contra nós!",
  ui_story_5081_50810201_8_dialog_content = "Bem, se não é o chefe! Talvez possamos fazer um acordo?",
  ui_story_5081_50810201_9_dialog_content = "Com o seu nome ilustre, talvez possamos garantir prioridade para nós mesmos.",
  ui_story_5081_50810201_10_dialog_content = "Desculpe, mas eu não tenho ideia do que você está falando.",
  ui_story_5081_50810201_11_dialog_content = "Vocês estavam seguindo alguém agora mesmo?",
  ui_story_5081_50810201_12_dialog_content = "Oh não, estávamos apenas fazendo uma pequena verificação de antecedentes em nossos oponentes.",
  ui_story_5081_50810201_13_dialog_content = "Para simplificar, viemos para avaliar a força de combate de nossos inimigos e identificar quaisquer possíveis vantagens que eles possam ter...",
  ui_story_5081_50810201_14_dialog_content = "Afinal, é limitado. Apenas aqueles com habilidades podem tirá-lo dos outros.",
  ui_story_5081_50810201_15_dialog_content = "S-Swipe algo?",
  ui_story_5081_50810201_16_dialog_content = "Claro! Basta olhar para todas essas pessoas!",
  ui_story_5081_50810201_17_dialog_content = "De jeito nenhum! Absolutamente não! Eu não permito isso—",
  ui_story_5081_50810201_18_dialog_content = "Por que não podemos—",
  ui_story_5081_50810201_19_dialog_content = "Roube de Umbraton!",
  ui_story_5081_50810201_20_dialog_content = "Compre esse jogo!",
  ui_story_5081_50810201_21_dialog_content = "Hã?",
  ui_story_5081_50810201_22_dialog_content = "Então, deixe-me entender direito...",
  ui_story_5081_50810201_23_dialog_content = "Um novo jogo de fantasia recém escavado está prestes a ser restaurado em breve, e agora está em pré-venda em Umbraton.",
  ui_story_5081_50810201_24_dialog_content = "Mas eles só têm cópias limitadas, e só estão permitindo que os jogadores comprem se passarem no teste deles.",
  ui_story_5081_50810201_25_dialog_content = "Então você veio de tão longe, do Deserto Rediesel, apenas para passar neste teste e garantir uma cópia do jogo.",
  ui_story_5081_50810201_26_dialog_content = "E agora você está perseguindo outros jogadores de mentalidade semelhante para obter uma melhor compreensão do teste...",
  ui_story_5081_50810201_27_dialog_content = "Vocês realmente estão indo longe demais só para comprar um videogame, haha...",
  ui_story_5081_50810201_28_dialog_content = "Ah... Quando você desenvolveu uma visão tão crua da Rediesel Wrench, chefe?",
  ui_story_5081_50810201_29_dialog_content = "Imaginei que, após anos de amizade e luta contra inimigos, poderíamos ter tido um entendimento muito melhor um do outro.",
  ui_story_5081_50810201_30_dialog_content = "Hã... Desculpe?",
  ui_story_5081_50810201_31_dialog_content = "Acho que você realmente não entende a Chave Rediesel... ou o valor de um jogo de fantasia como este!",
  ui_story_5081_50810201_32_dialog_content = "... Esse é realmente o ponto aqui?",
  ui_story_5081_50810201_33_dialog_content = "Para os Aurorians desenterrarem um videogame das ruínas e restaurá-lo ao funcionamento...",
  ui_story_5081_50810201_34_dialog_content = "Você tem ideia de quanto trabalho é investido nisso?",
  ui_story_5081_50810201_35_dialog_content = "H-Quanto?",
  ui_story_5081_50810201_36_dialog_content = "Consertar máquinas de jogo é a parte mais fácil do processo!",
  ui_story_5081_50810201_37_dialog_content = "Entender a codificação original e o conteúdo de um jogo, e depois complementar quaisquer partes danificadas ou ausentes - isso é incrivelmente difícil!",
  ui_story_5081_50810201_38_dialog_content = "E não me faça começar sobre os desafios de traduzir a antiga linguagem de um jogo para o Auroriano!",
  ui_story_5081_50810201_39_dialog_content = "Esse tipo de trabalho é um dos maiores empreendimentos de nosso tempo!",
  ui_story_5081_50810201_40_dialog_content = "E-Eu acho que entendi agora... Acho que lançar um jogo não é tão simples quanto eu pensava...",
  ui_story_5081_50810201_41_dialog_content = "Exatamente. Além disso, a tecnologia e a expertise da Illumina geralmente são necessárias para trabalhos de escavação e restauração em grande escala como este.",
  ui_story_5081_50810201_42_dialog_content = "É isso que torna ainda mais chocante que um jogo como este esteja sendo vendido primeiro em Umbraton!",
  ui_story_5081_50810201_43_dialog_content = "É também por isso que temos que colocar as mãos em uma cópia da edição especial. Mesmo que dupliquem o preço do jogo, ou até mesmo o tripliquem, pagaremos o que custar!",
  ui_story_5081_50810201_44_dialog_content = "Parece que será realmente caro então... Você está bem com isso, Jomu?",
  ui_story_5081_50810201_45_dialog_content = "Claro! Quanto mais caro é agora, mais valioso será no futuro!",
  ui_story_5081_50810201_46_dialog_content = "Se eu tivesse que escolher um tipo favorito de jogo, seria aquele que faz as pessoas desembolsarem dinheiro a rodo.",
  ui_story_5081_50810201_47_dialog_content = "Então você está disposto a comprar este jogo de fantasia mesmo <color=#FFB400>a um preço premium</color>... Eu quase não consigo acreditar, Jomu.",
  ui_story_5081_50810201_48_dialog_content = "Vocês juntaram sucata e outras peças para reconstruir um Colossus, mas de alguma forma estão dispostos a pagar um bom dinheiro por um videogame.",
  ui_story_5081_50810201_49_dialog_content = "Você simplesmente não entende, PlayerName.",
  ui_story_5081_50810201_50_dialog_content = "Eu já te disse quanto tempo e esforço leva para descobrir, desenterrar, restaurar e lançar jogos como este...",
  ui_story_5081_50810201_51_dialog_content = "Você acha que esse tipo de trabalho pode ser feito por qualquer estúdio meia-boca com recursos mínimos?",
  ui_story_5081_50810201_52_dialog_content = "Acho que não.",
  ui_story_5081_50810201_53_dialog_content = "Diga-me, qual você acha que é o aspecto mais importante de um videogame?",
  ui_story_5081_50810201_54_dialog_content = "Sua... jogabilidade?",
  ui_story_5081_50810201_55_dialog_content = "Errado! São os jogadores!",
  ui_story_5081_50810201_56_dialog_content = "Se você fizer algo desprezível, como forçar profissionais a desenvolver seus jogos ou roubar versões de edição limitada...",
  ui_story_5081_50810201_57_dialog_content = "Você será ostracizado por toda a comunidade de jogos!",
  ui_story_5081_50810201_58_dialog_content = "Não importa o quão maravilhoso seja o jogo que você tem, ninguém estará por perto para compartilhar sua alegria.",
  ui_story_5081_50810201_59_dialog_content = "É o resultado mais trágico imaginável para qualquer jogador! Você não entende?",
  ui_story_5081_50810201_60_dialog_content = "Isso mesmo! Até um jogo como Tetrablox é mais divertido quando duas pessoas participam!",
  ui_story_5081_50810201_61_dialog_content = "Além disso, existem muitas pessoas notáveis dentro da comunidade de jogos - pessoas que você definitivamente não quer ofender.",
  ui_story_5081_50810201_62_dialog_content = "Especialmente porque eles podem estar no mercado para muitos novos periféricos de jogos... Heheheh.",
  ui_story_5081_50810201_63_dialog_content = "Jogadores, huh...",
  ui_story_5081_50810201_64_dialog_content = "Tenho certeza de que existem muitos desses na Rediesel Wrench, certo?",
  ui_story_5081_50810201_65_dialog_content = "Vocês devem estar sem jogos para jogar se estão dispostos a vir até Umbraton por eles...",
  ui_story_5081_50810201_66_dialog_content = "Ei! Vamos deixar algo claro aqui: somos perfeitamente capazes de desenterrar máquinas de jogos e cartuchos todos por nós mesmos!",
  ui_story_5081_50810201_67_dialog_content = "Mas esses idiotas desajeitados não têm ideia de como cuidar adequadamente das coisas, então nossas coisas ficam danificadas o tempo todo!",
  ui_story_5081_50810201_68_dialog_content = "Você acha que eu posso consertar esse tipo de bagunça sozinho? Não, absolutamente não...",
  ui_story_5081_50810201_69_dialog_content = "Se eu pudesse levar alguns cientistas Illuminan comigo, aposto que poderia criar um jogo que conquistaria o mundo inteiro!",
  ui_story_5081_50810201_70_dialog_content = "Espere, acho que eu posso conhecer justamente o cientista de Illumina para o trabalho...",
  ui_story_5081_50810201_71_dialog_content = "Ah! Eu me envolvi conversando com vocês e quase esqueci!",
  ui_story_5081_50810201_72_dialog_content = "(Eu me pergunto se o desaparecimento de Gronru tem algo a ver com a pré-venda deste jogo de fantasia?)",
  ui_story_5081_50810201_73_dialog_content = "(O momento não poderia ser mais perfeito...)",
  ui_story_5081_50810201_74_dialog_content = "(Começar minha busca com este jogo não é uma má escolha. Agora então...)",
  ui_story_5081_50810201_75_dialog_content = "Hmm... Você poderia me dizer onde eles estão vendendo este jogo?",
  ui_story_5081_50810201_76_dialog_content = "Mas claro, meu querido amigo! Eu até te darei um desconto de vinte por cento por essa informação—",
  ui_story_5081_50810201_77_dialog_content = "Presas Ocultas.",
  ui_story_5081_50810201_78_dialog_content = "Bom...",
  ui_story_5081_50810201_79_dialog_content = "Sim, isso mesmo—Presas Ocultas!",
  ui_story_5081_50810201_80_dialog_content = "Um paraíso para todos os jogadores em Astra! O único e supremo fliperama de Umbraton!",
  ui_story_5081_50810201_81_dialog_content = "Ainda não vou te pagar por essa informação, sabe...",
  ui_story_5081_50810201_82_dialog_content = "Também é um ponto de encontro para jogadores de alto nível. A maioria, senão todos, os recordes de videogame de Astra foram estabelecidos lá.",
  ui_story_5081_50810201_83_dialog_content = "... Parece um verdadeiro salão da fama, eu acho.",
  ui_story_5081_50810201_84_dialog_content = "(Eu me pergunto se alguma das altas pontuações de Gronru estão registradas lá?)",
  ui_story_5081_50810201_85_dialog_content = "(Você está definitivamente no caminho certo agora, Celestita! Continue assim!)",
  ui_story_5081_50810201_86_dialog_content = "Infelizmente, você provavelmente não conseguirá garantir uma cópia mesmo que adicione seu nome à lista agora.",
  ui_story_5081_50810201_87_dialog_content = "Huh? Mas eu pensei que isso era uma pré-venda! Eu deveria ter reservado um lugar na lista de espera?",
  ui_story_5081_50810201_88_dialog_content = "Não tem nada a ver com a lista de espera...",
  ui_story_5081_50810201_89_dialog_content = "Os cartuchos de videogame são extremamente valiosos, então o fliperama está realizando uma revisão rigorosa de qualquer comprador em potencial.",
  ui_story_5081_50810201_90_dialog_content = "É tudo para evitar que cambistas e outros atores mal-intencionados se envolvam, para que os verdadeiros jogadores tenham a oportunidade de aproveitar o jogo.",
  ui_story_5081_50810201_91_dialog_content = "Não é de se admirar que Jomu pareça tão nervoso com isso.",
  ui_story_5081_50810201_92_dialog_content = "Haha, muito engraçado, chefe. Marque minhas palavras: vou ganhar o direito de comprar uma cópia de \"B\" de forma justa e honesta!",
  ui_story_5081_50810201_93_dialog_content = "\"B\"?",
  ui_story_5081_50810201_94_dialog_content = "Isso mesmo. O passo mais crucial para garantir uma cópia deste jogo é jogar contra \"B.\"",
  ui_story_5081_50810201_95_dialog_content = "Como proprietária do Hidden Fangs, ela também é uma das maiores jogadoras de Astra...",
  ui_story_5081_50810201_96_dialog_content = "É assim que o \"B\" testa você para ver se o seu amor por videogames é real ou não.",
  ui_story_5081_50810201_97_dialog_content = "Não acho que um novato como você possa lidar com isso.",
  ui_story_5081_50810201_98_dialog_content = "O-O quê? Do que você está falando? Eu também joguei muitos jogos!",
  ui_story_5081_50810201_99_dialog_content = "Heheheh. Eu só vou ter que te contar um pouco mais sobre o \"B\", para que você possa chafurdar em desespero...",
  ui_story_5081_50810301_1_dialog_content = "<color=#e8d9bb>Um corpo feito inteiramente de jogos.</color>",
  ui_story_5081_50810301_2_dialog_content = "<color=#e8d9bb>Com um computador por um coração, e dados por sangue.</color>",
  ui_story_5081_50810301_3_dialog_content = "<color=#e8d9bb>Ela jogou milhares de jogos sem perder uma única vez.</color>",
  ui_story_5081_50810301_4_dialog_content = "<color=#e8d9bb>Sua existência é um mistério tanto para Aurorianos quanto para Eclipsitas.</color>",
  ui_story_5081_50810301_5_dialog_content = "<color=#e8d9bb>Na maioria dos dias, ela se esconde nos cantos mais escuros do fliperama, murmurando para si mesma sobre ser inútil.</color>",
  ui_story_5081_50810301_6_dialog_content = "<color=#e8d9bb>Ela tem apenas um desejo na vida: uma quantidade infinita de jogos para jogar!</color>",
  ui_story_5081_50810301_7_dialog_content = "...",
  ui_story_5081_50810301_8_dialog_content = "Pare já! A história só fica cada vez mais e mais louca!",
  ui_story_5081_50810301_9_dialog_content = "Então, para simplificar... \"B\" é um jogador que jogou inúmeros jogos e não perdeu uma única vez?",
  ui_story_5081_50810301_10_dialog_content = "Para ser mais preciso—",
  ui_story_5081_50810301_11_dialog_content = "Ela tem alguns dos recordes de liberação mais rápidos e as pontuações mais altas em todo o Astra, e ela também é a jogadora de Tetrablox mais famosa de todos os tempos.",
  ui_story_5081_50810301_12_dialog_content = "Ela continua batendo recordes no modo infinito do Tetrablox também. Alguns até dizem que ela chegou ao último nível do jogo...",
  ui_story_5081_50810301_13_dialog_content = "Um jogo como esse realmente pode ter um nível final?",
  ui_story_5081_50810301_14_dialog_content = "Pelo que ouvi, o jogo congela assim que você limpa um certo número de níveis...",
  ui_story_5081_50810301_15_dialog_content = "De qualquer maneira, não é algo que um Aurorian comum poderia fazer.",
  ui_story_5081_50810301_16_dialog_content = "Ela é algum tipo de monstro de jogo gerado das profundezas mais profundas das ruínas antigas? Ela muito bem poderia ser!",
  ui_story_5081_50810301_17_dialog_content = "Acalme-se, eu já entendi. Ela é realmente boa em videogames...",
  ui_story_5081_50810301_18_dialog_content = "De qualquer forma, muitos desafiadores foram até Hidden Fangs em busca de \"B\", apenas para sair mancando em derrota!",
  ui_story_5081_50810301_19_dialog_content = "Na verdade, eu só quero perguntar por algumas informações. Não estou interessado em desafiar o \"B\" de jeito nenhum!",
  ui_story_5081_50810301_20_dialog_content = "Essa pessoa também não parece muito acessível...",
  ui_story_5081_50810301_21_dialog_content = "Não se preocupe, chefe! Ficarei mais do que feliz em perguntar em seu nome, e por um desconto de cinco por cento—",
  ui_story_5081_50810301_22_dialog_content = "Você ficará bem, então apenas vá lá e veja por si mesmo! Existem todos os tipos de jogadores lá, você verá.",
  ui_story_5081_50810301_23_dialog_content = "Obrigado, pessoal. Mostre o caminho!",
  ui_story_5081_50810301_24_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5081_50810301_25_dialog_content = "... Este é realmente o lugar?",
  ui_story_5081_50810301_26_dialog_content = "É muito mais confortável do que eu pensava que seria!",
  ui_story_5081_50810301_27_dialog_content = "Estou até sentindo uma sensação de nostalgia, como se estivesse prestes a sentar e jogar um dos meus jogos favoritos.",
  ui_story_5081_50810301_28_dialog_content = "É apenas um fliperama, sabe. Como você pensava que seria?",
  ui_story_5081_50810301_29_dialog_content = "Você está realmente me perguntando isso depois daquela descrição louca que você me deu?",
  ui_story_5081_50810301_30_dialog_content = "Pelo menos, eu pensei que estaria cheio de gangsters de Umbraton ou algo assim...",
  ui_story_5081_50810301_31_dialog_content = "Aposto que o dono desta pequena e aconchegante loja deve ser alguém que realmente ama a vida!",
  ui_story_5081_50810301_32_dialog_content = "...",
  ui_story_5081_50810301_33_dialog_content = "Hã?",
  ui_story_5081_50810301_34_dialog_content = "!",
  ui_story_5081_50810301_35_dialog_content = "Eu não sei sobre a vida, mas ela definitivamente adora jogos...",
  ui_story_5081_50810301_36_dialog_content = "Hum? Qual o problema, PlayerName? Parece que algo está te incomodando.",
  ui_story_5081_50810301_37_dialog_content = "Por algum motivo... parece que alguém está me observando.",
  ui_story_5081_50810301_38_dialog_content = "Você está apenas imaginando coisas. A iluminação aqui não é muito clara, afinal.",
  ui_story_5081_50810301_39_dialog_content = "Além disso, todos estão ocupados demais jogando para notar você...",
  ui_story_5081_50810301_40_dialog_content = "Você está certo, acho que estou apenas me preocupando à toa.",
  ui_story_5081_50810301_41_dialog_content = "Então, onde está o dono do fliperama? Para algo tão importante quanto a pré-venda de um jogo, mal há qualquer publicidade sobre isso.",
  ui_story_5081_50810301_42_dialog_content = "Ela poderia estar testando alguém para ver se são dignos de comprar o jogo?",
  ui_story_5081_50810301_43_dialog_content = "Não se preocupe, chefe. A proprietária é uma pessoa muito apaixonada, e tenho certeza de que ela responderá se você chamar por ela - alto, é claro.",
  ui_story_5081_50810301_44_dialog_content = "Ok, ah... Com licença! Posso falar com o \"B\", por favor?",
  ui_story_5081_50810301_45_dialog_content = "?",
  ui_story_5081_50810301_46_dialog_content = "É esse um novo desafiante?",
  ui_story_5081_50810301_47_dialog_content = "Espere, acho que já vi essa roupa antes... Ele não é uma pessoa famosa?",
  ui_story_5081_50810301_48_dialog_content = "Sim! Isso será incrível!",
  ui_story_5081_50810301_49_dialog_content = "Você me armou uma, Jomu!",
  ui_story_5081_50810301_50_dialog_content = "Desculpe, chefe, mas como você não pagou pela minha informação, tive que pensar em outra maneira de coletar minha compensação. Boa sorte!",
  ui_story_5081_50810301_51_dialog_content = "...",
  ui_story_5081_50810301_52_dialog_content = "Você é muito corajoso, chamando o \"B\" assim...",
  ui_story_5081_50810301_53_dialog_content = "Bem-vindo ao Presas Ocultas! Espero que esteja pronto para um desafio!",
  ui_story_5081_50810301_54_dialog_content = "...Hã?",
  ui_story_5081_50810301_55_dialog_content = "Oh? Bem, se não é PlayerName!",
  ui_story_5081_50810301_56_dialog_content = "É PlayerName, piu!",
  ui_story_5081_50810301_57_dialog_content = "Sork? Bekk?",
  ui_story_5081_50810301_58_dialog_content = "O que vocês dois estão fazendo aqui?",
  ui_story_5081_50810301_59_dialog_content = "Essa é a minha fala, amigo! O que você... Ei! Jomu também está aqui!",
  ui_story_5081_50810301_60_dialog_content = "Pare de se esconder atrás de PlayerName, seu vagabundo! Me devolva o dinheiro que você me deve, ou então...",
  ui_story_5081_50810301_61_dialog_content = "Me salve, chefe!",
  ui_story_5081_50810301_62_dialog_content = "Sem chance, especialmente depois de você ter me armado uma dessas...",
  ui_story_5081_50810301_63_dialog_content = "Bem... Infelizmente, eu só trouxe dinheiro suficiente para comprar este jogo hoje, entende.",
  ui_story_5081_50810301_64_dialog_content = "Como funcionário desta loja, certamente você não gostaria que eu saísse de mãos vazias, certo?",
  ui_story_5081_50810301_65_dialog_content = "Sork trabalha aqui?",
  ui_story_5081_50810301_66_dialog_content = "Ele acabou de te receber como um funcionário, não foi?",
  ui_story_5081_50810301_67_dialog_content = "Bom... É uma longa história.",
  ui_story_5081_50810301_68_dialog_content = "Originalmente, Bekk e eu fomos contratados para comprar alguns jogos novos para um cliente aqui em Umbraton.",
  ui_story_5081_50810301_69_dialog_content = "Mas no final, fomos enganados por um vendedor suspeito e acabamos com um monte de cartuchos de lixo.",
  ui_story_5081_50810301_70_dialog_content = "Sem dinheiro e negócios para concluir, decidimos passar a noite neste fliperama...",
  ui_story_5081_50810301_71_dialog_content = "Então o dono foi gentil o suficiente para oferecer empregos a vocês enquanto estão aqui?",
  ui_story_5081_50810301_72_dialog_content = "Gentil? Hehe, mais como curioso.",
  ui_story_5081_50810301_73_dialog_content = "A proprietária queria ver como Bekk e eu trabalhávamos juntos, então ela nos convidou para jogar um jogo.",
  ui_story_5081_50810301_74_dialog_content = "Se ganhássemos, ela cobriria todas as nossas perdas. Se perdêssemos, teríamos que trabalhar para ela.",
  ui_story_5081_50810301_75_dialog_content = "Droga! Estávamos tão perto de ganhar também...",
  ui_story_5081_50810301_76_dialog_content = "Perdemos por um triz, piu!",
  ui_story_5081_50810301_77_dialog_content = "Vocês dois \"perderam por um triz\"? Ha, não me faça rir!",
  ui_story_5081_50810301_78_dialog_content = "Se estamos falando da \"B\" aqui, ela provavelmente pisoteou vocês no chão!",
  ui_story_5081_50810301_79_dialog_content = "Quê? Como você sabia que ela usava os pés? Foi assim que ela conseguiu usar dois controles ao mesmo tempo...",
  ui_story_5081_50810301_80_dialog_content = "Ela nos venceu usando as mãos e os pés ao mesmo tempo!",
  ui_story_5081_50810301_81_dialog_content = "E-Ela fez?",
  ui_story_5081_50810301_82_dialog_content = "De qualquer forma, uma coisa levou a outra, e agora estamos ambos trabalhando aqui...",
  ui_story_5081_50810301_83_dialog_content = "Quando não está movimentado, até conseguimos jogar jogos de tabuleiro com nossos clientes.",
  ui_story_5081_50810301_84_dialog_content = "As pessoas podem se imergir completamente em jogos de estratégia aqui - isso não é algo que você pode encontrar na maioria dos lugares...",
  ui_story_5081_50810301_85_dialog_content = "Mesmo que os jogos de negociação sejam muito melhores, chilro!",
  ui_story_5081_50810301_86_dialog_content = "Então vocês dois também se envolvem nos jogos aqui, hein?",
  ui_story_5081_50810301_87_dialog_content = "Realmente há algo especial neste lugar... mas por que eu não vi o dono da loja em lugar nenhum?",
  ui_story_5081_50810301_88_dialog_content = "\"B\" tem uma rara ascendência semi-humana, assim como nós. Não é fácil para ela sair durante o dia.",
  ui_story_5081_50810301_89_dialog_content = "Ela também teve muitos problemas no passado por causa de sua ascendência. Então, por favor...",
  ui_story_5081_50810301_90_dialog_content = "Apenas tente entender.",
  ui_story_5081_50810301_91_dialog_content = "E-Eu te entendo totalmente!",
  ui_story_5081_50810301_92_dialog_content = "Eu só tenho algo para perguntar a ela, só isso. Gostaria de passar uma mensagem para ela?",
  ui_story_5081_50810301_93_dialog_content = "Claro, PlayerName.",
  ui_story_5081_50810301_94_dialog_content = "Deixe-me terminar este jogo... Quer dizer, lidar com esses clientes, e eu vou começar imediatamente.",
  ui_story_5081_50810301_95_dialog_content = "Claro.",
  ui_story_5081_50810301_96_dialog_content = "Huh? Eu me pergunto para onde Odi e Jomu foram...",
  ui_story_5081_50810301_97_dialog_content = "Está brincando comigo? Eu inventei toneladas de novas estratégias só para poder ganhar minha cópia do jogo!",
  ui_story_5081_50810301_98_dialog_content = "Veja, eu até modifiquei meu próprio controle... Dê uma olhada se quiser!",
  ui_story_5081_50810301_99_dialog_content = "Isto é tão legal!",
  ui_story_5081_50810301_100_dialog_content = "Desculpe-me amigo, mas gostaria de jogar algumas rodadas de Rediesel Hold 'em comigo? Acho que podemos ser bastante equilibrados!",
  ui_story_5081_50810301_101_dialog_content = "Mas de onde eu venho, o perdedor geralmente cobre as despesas do vencedor pelo resto do dia. Interessado?",
  ui_story_5081_50810301_102_dialog_content = "Claro, tô dentro!",
  ui_story_5081_50810301_103_dialog_content = "Todos parecem estar se divertindo muito.",
  ui_story_5081_50810301_104_dialog_content = "Eu deveria tocar algo também, para não me destacar tanto...",
  ui_story_5081_50810301_105_dialog_content = "Hmm, o que escolher...",
  ui_story_5081_50810301_106_dialog_content = "Este parece bastante divertido. Aurora All-Star Racing - Eu deveria ser bastante bom em jogos de corrida, certo?",
  ui_story_5081_50810301_107_dialog_content = "Acho que é melhor eu colocar um token e descobrir!",
  ui_story_5081_50810301_108_dialog_content = "Uau, olhe todas essas opções de veículos! Eu posso até escolher armas também!",
  ui_story_5081_50810301_109_dialog_content = "Tudo bem, acho que peguei o jeito agora. Vamos nessa!",
  ui_story_5081_50810301_110_dialog_content = "<color=#e8d9bb>Embora os gráficos do jogo sejam bastante simples, os jogadores ainda sentem como se tivessem sido transportados para um novo mundo.</color>",
  ui_story_5081_50810301_111_dialog_content = "<color=#e8d9bb>As imagens detalhadas, juntamente com sua apresentação exagerada e efeitos sonoros especiais, criam uma experiência imersiva.</color>",
  ui_story_5081_50810301_112_dialog_content = "É assim que eu deveria fazer as curvas? Eu entendi totalmente agora!",
  ui_story_5081_50810301_113_dialog_content = "Eu colecto Lumina sempre que derrapo numa curva, então eu deveria dispará-lo nos Eclipsitas? Acho que é melhor eu tentar!",
  ui_story_5081_50810301_114_dialog_content = "Espere... Esse Eclipsita é um pouco forte demais, não é?",
  ui_story_5081_50810301_115_dialog_content = "Uh-oh... Por que não consigo ver os rastros de Lumina?",
  ui_story_5081_50810301_116_dialog_content = "Ah, cara... Este jogo não inclui a habilidade mais forte dos Celestitas! É totalmente injusto!",
  ui_story_5081_50810301_117_dialog_content = "Na verdade, este é o aspecto mais <color=#FFB400>justo</color> do jogo.",
  ui_story_5081_50810301_118_dialog_content = "Hã?",
  ui_story_5081_50810301_119_dialog_content = "<color=#e8d9bb>O Jogador 2 entrou no jogo!</color>",
  ui_story_5081_50810301_120_dialog_content = "Outro jogador... entrou no meu jogo?",
  ui_story_5081_50810301_121_dialog_content = "... D-Não olhe para mim!",
  ui_story_5081_50810301_122_dialog_content = "Apenas mantenha os olhos na sua tela, ou você vai bater.",
  ui_story_5081_50810301_123_dialog_content = "Foi mal!",
  ui_story_5081_50810301_124_dialog_content = "É a minha primeira vez jogando, então peço desculpas se eu atrapalhar...",
  ui_story_5081_50810301_125_dialog_content = "Não se preocupe, vou mostrar como jogar.",
  ui_story_5081_50810301_126_dialog_content = "Você tem muito potencial. Concentre sua atenção, e isso não deve ser um problema.",
  ui_story_5081_50810301_127_dialog_content = "T-Tá então...",
  ui_story_5081_50810301_128_dialog_content = "<color=#e8d9bb>Aviso! Aviso! Uma grande onda de Eclipsitas está a caminho!</color>",
  ui_story_5081_50810301_129_dialog_content = "Prepare-se, vamos fazer isso juntos.",
  ui_story_5081_50810301_130_dialog_content = "Entendido!",
  ui_story_5081_50810302_1_dialog_content = "?",
  ui_story_5081_50810302_2_dialog_content = "E-Eu ainda estou vivo?",
  ui_story_5081_50810302_3_dialog_content = "Não acredito que conseguimos sair daquela horda de Eclipsitas!",
  ui_story_5081_50810302_4_dialog_content = "Isso significa que estou perto de concluir o estágio?",
  ui_story_5081_50810302_5_dialog_content = "... Você se divertiu?",
  ui_story_5081_50810302_6_dialog_content = "Diversão? Claro que foi divertido! Eu só acho que não poderia ter jogado por tanto tempo sem a sua ajuda.",
  ui_story_5081_50810302_7_dialog_content = "Isso não é necessariamente verdade. Você terá que confiar em si mesmo para a próxima parte... mas tenho certeza de que vai ficar bem.",
  ui_story_5081_50810302_8_dialog_content = "Hã?",
  ui_story_5081_50810302_9_dialog_content = "<color=#e8d9bb>Jogador 2 saiu do jogo!</color>",
  ui_story_5081_50810302_10_dialog_content = "Você vai embora assim mesmo?",
  ui_story_5081_50810302_11_dialog_content = "... Eu te disse para não olhar para mim! Olhos na tela!",
  ui_story_5081_50810302_12_dialog_content = "Certo! Eu não posso me dar ao luxo de perder o foco agora...",
  ui_story_5081_50810302_13_dialog_content = "Você já me ajudou a superar a parte mais difícil, então agora cabe a mim terminar o resto!",
  ui_story_5081_50810302_14_dialog_content = "Eu posso lidar com o que esse jogo me lança! Curvas acentuadas, Eclipsitas, você nomeia!",
  ui_story_5081_50810302_15_dialog_content = "Oh? Eu não percebi que você também estava jogando, PlayerName... e você parece bastante animado!",
  ui_story_5081_50810302_16_dialog_content = "Espere, este é o estágio do Desfiladeiro Tempestuoso, não é? Sei que você está totalmente inconsciente de quão difícil é esta corrida, mas tente não perder imediatamente...",
  ui_story_5081_50810302_17_dialog_content = "Uau! Venha dar uma olhada, Odi. Ele já limpou as cinco curvas fechadas consecutivas em Tempest Gorge!",
  ui_story_5081_50810302_18_dialog_content = "Impossível! Nem eu consegui passar por essa onda de Eclipsitas... Eu me recuso a aceitar isso!",
  ui_story_5081_50810302_19_dialog_content = "Uau! Olha só isso, todos!",
  ui_story_5081_50810302_20_dialog_content = "Huh? Por que todos estão se reunindo ao meu redor de repente?",
  ui_story_5081_50810302_21_dialog_content = "<color=#e8d9bb>Sob o olhar ansioso de todos, limpar o palco de repente se torna ainda mais difícil.</color>",
  ui_story_5081_50810302_22_dialog_content = "<color=#e8d9bb>Mas no final, o fliperama explode em aplausos quando a corrida chega a uma conclusão emocionante e bem-sucedida.</color>",
  ui_story_5081_50810302_23_dialog_content = "Uau!",
  ui_story_5081_50810302_24_dialog_content = "Um novato limpou o Tempest Gorge em sua primeira tentativa? Como isso é possível?",
  ui_story_5081_50810302_25_dialog_content = "Aposto que esse cara é realmente um jogador profissional!",
  ui_story_5081_50810302_26_dialog_content = "De onde você veio, cara novo? Você está aqui para mostrar suas habilidades?",
  ui_story_5081_50810302_27_dialog_content = "I-É este estágio realmente tão difícil?",
  ui_story_5081_50810302_28_dialog_content = "Não entendam mal, pessoal! Eu não sou nada especial, e esta é a minha primeira vez aqui. Além disso, tive muita ajuda de outro jogador...",
  ui_story_5081_50810302_29_dialog_content = "Quando estava lutando meu caminho através dessas curvas fechadas, ela estava sentada bem ao lado... Hã?",
  ui_story_5081_50810302_30_dialog_content = "Sério? Porque eu não vejo ninguém.",
  ui_story_5081_50810302_31_dialog_content = "Ela estava aqui agora mesmo!",
  ui_story_5081_50810302_32_dialog_content = "Um pequeno Aurorian... que parecia não estar totalmente acordado...",
  ui_story_5081_50810302_33_dialog_content = "Acho que ela pode ser uma semi-humana morcego, e o cabelo dela parecia meio que as luzes do fliperama...",
  ui_story_5081_50810302_34_dialog_content = "Hehe... Você tem alguma ideia de quem acabou de descrever?",
  ui_story_5081_50810302_35_dialog_content = "Chilro! Um pequeno morcego semi-humano!",
  ui_story_5081_50810302_36_dialog_content = "Isso soa muito como Batia, a dona do fliperama!",
  ui_story_5081_50810401_1_dialog_content = "...",
  ui_story_5081_50810401_2_dialog_content = "Parece que estou esperando para ser entrevistado...",
  ui_story_5081_50810401_3_dialog_content = "Não fique tão agitado. Se a \"B\" estava disposta a brincar com você, definitivamente significa que você chamou a atenção dela.",
  ui_story_5081_50810401_4_dialog_content = "Eu poderia chamá-la se você quiser.",
  ui_story_5081_50810401_5_dialog_content = "Não vamos receber mais pré-encomendas hoje se não tivermos novos desafiantes.",
  ui_story_5081_50810401_6_dialog_content = "Isso significa que teremos que continuar trabalhando aqui, piu!",
  ui_story_5081_50810401_7_dialog_content = "Eu entendo. Vamos fazer isso!",
  ui_story_5081_50810401_8_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5081_50810401_9_dialog_content = "... Oh.",
  ui_story_5081_50810401_10_dialog_content = "... Hum.",
  ui_story_5081_50810401_11_dialog_content = "... Ufa.",
  ui_story_5081_50810401_12_dialog_content = "Com licença...",
  ui_story_5081_50810401_13_dialog_content = "Uh... Sim!",
  ui_story_5081_50810401_14_dialog_content = "... Teve algo de errado com o meu cumprimento agora há pouco?",
  ui_story_5081_50810401_15_dialog_content = "<size=30>(... Ou talvez eu deva me comunicar com ela em termos de arcade?)</size>",
  ui_story_5081_50810401_16_dialog_content = "Não... Hum...",
  ui_story_5081_50810401_17_dialog_content = "!",
  ui_story_5081_50810401_18_dialog_content = "D-Você... precisava de algo de mim?",
  ui_story_5081_50810401_19_dialog_content = "Não é nada especial, realmente.",
  ui_story_5081_50810401_20_dialog_content = "Sou um celestita, e meu nome é o mesmo que eu usava no jogo.",
  ui_story_5081_50810401_21_dialog_content = "Eu vim aqui procurando por alguém. Você poderia me dizer se viu...",
  ui_story_5081_50810401_22_dialog_content = "E-Eu não fiz isso! Definitivamente não acolho crianças quando fogem de casa e as deixo jogar videogames aqui!",
  ui_story_5081_50810401_23_dialog_content = "V-V-Você está no lugar errado... Eu juro!",
  ui_story_5081_50810401_24_dialog_content = "Huh? Eu realmente pareço um pai descontente para você?",
  ui_story_5081_50810401_25_dialog_content = "Ah, acho que não...",
  ui_story_5081_50810401_26_dialog_content = "É porque eu não sou! Eu vim procurando por alguém que parece muito jovem, mas na verdade é muito mais velha do que parece! Ela é uma das maiores cientistas de Illumina!",
  ui_story_5081_50810401_27_dialog_content = "Ela abandonou todas as suas importantes funções de laboratório e desapareceu sem qualquer explicação recentemente.",
  ui_story_5081_50810401_28_dialog_content = "Ela realmente gosta de videogames, então pensei que este seria um bom lugar para começar a procurar...",
  ui_story_5081_50810401_29_dialog_content = "O nome dela é Gronru. Você sabe algo sobre ela?",
  ui_story_5081_50810401_30_dialog_content = "Não.",
  ui_story_5081_50810401_31_dialog_content = "I-É mesmo...",
  ui_story_5081_50810401_32_dialog_content = "(Essa foi uma resposta tão rápida... um pouco rápida demais, se você me perguntar.)",
  ui_story_5081_50810401_33_dialog_content = "(Ela está tentando evitar causar uma cena? Faz sentido, considerando que isso é suposto ser um paraíso para todos os jogadores... Espere, jogadores...)",
  ui_story_5081_50810401_34_dialog_content = "Desculpe! Acho que fiz a pergunta errada.",
  ui_story_5081_50810401_35_dialog_content = "As pessoas aqui provavelmente usam seus nomes de jogador, não é?",
  ui_story_5081_50810401_36_dialog_content = "Agora, qual era o nome do jogador de Gronru mesmo? Isso mesmo! Ela é conhecida como Gronkenstein Ruu! Você já ouviu falar dela?",
  ui_story_5081_50810401_37_dialog_content = "Gronken o quê?",
  ui_story_5081_50810401_38_dialog_content = "Gronkenstein Ruu!",
  ui_story_5081_50810401_39_dialog_content = "Grompen... Stein?",
  ui_story_5081_50810401_40_dialog_content = "Não, Gronkenst—ai! Eu mordi a minha língua!",
  ui_story_5081_50810401_41_dialog_content = "De qualquer forma... Eu não conheço nenhum cientista famoso.",
  ui_story_5081_50810401_42_dialog_content = "Tive muitos jogadores vindo à minha loja recentemente... É meio impossível... lembrar todos os seus nomes.",
  ui_story_5081_50810401_43_dialog_content = "Desculpe, mas... Acho que não posso ser de muita ajuda.",
  ui_story_5081_50810401_44_dialog_content = "Espere, deixe-me pensar. Pode haver outra pista que eu possa usar aqui...",
  ui_story_5081_50810401_45_dialog_content = "Você... não gosta de jogar, gosta?",
  ui_story_5081_50810401_46_dialog_content = "Hã?",
  ui_story_5081_50810401_47_dialog_content = "Você não veio aqui para jogar... Você veio procurar alguém.",
  ui_story_5081_50810401_48_dialog_content = "Quando nos unimos no Aurora All-Star Racing e limpamos o Desfiladeiro Tempestade...",
  ui_story_5081_50810401_49_dialog_content = "Não era diferente de agora. Você não queria se destacar, então sentiu que tinha que jogar, certo?",
  ui_story_5081_50810401_50_dialog_content = "Peço desculpas... Eu nunca deveria ter incomodado você!",
  ui_story_5081_50810401_51_dialog_content = "E-Ei! Não diga isso.",
  ui_story_5081_50810401_52_dialog_content = "Eu estava me divertindo muito quando estávamos jogando juntos agora mesmo! Foi super emocionante!",
  ui_story_5081_50810401_53_dialog_content = "Mas uma vez que eu me acalmo, eu lembro o quão importante é a minha missão, e eu tenho que voltar para a tarefa em mãos. É por isso que...",
  ui_story_5081_50810401_54_dialog_content = "...",
  ui_story_5081_50810401_55_dialog_content = "Assustei ela por estar muito focado na minha missão?",
  ui_story_5081_50810401_56_dialog_content = "Você deveria tentar falar com ela novamente. Ficar se lamentando não vai te fazer bem algum.",
  ui_story_5081_50810401_57_dialog_content = "Você já deveria saber como se aproximar dela agora. Afinal, o hobby dela é bastante óbvio.",
  ui_story_5081_50810401_58_dialog_content = "Você quer dizer videogames...",
  ui_story_5081_50810401_59_dialog_content = "E mesmo que não seja para se aproximar dela novamente, você acabou de mencionar o nome do jogador de Gronru, não foi?",
  ui_story_5081_50810401_60_dialog_content = "Por que você não joga algumas partidas e vê se o nome dela aparece na tabela de classificação?",
  ui_story_5081_50810401_61_dialog_content = "Isso deve te dizer se ela esteve aqui recentemente ou não.",
  ui_story_5081_50810401_62_dialog_content = "Entendi! Essa é uma ótima ideia, Odi!",
  ui_story_5081_50810401_63_dialog_content = "Além disso, já que você acabou de passar pelo Desfiladeiro da Tempestade, quero ver se suas habilidades são o verdadeiro negócio.",
  ui_story_5081_50810401_64_dialog_content = "Eu vou cobrir as fichas, então venha jogar algumas partidas comigo!",
  ui_story_5081_50810401_65_dialog_content = "Claro, já tô indo aí.",
  ui_story_5081_50810401_66_dialog_content = "O que é isso? Odi está pagando hoje? Bem, conte comigo!",
  ui_story_5081_50810401_67_dialog_content = "Também não posso perder isso...",
  ui_story_5081_50810401_68_dialog_content = "Conte conosco também! Chilro!",
  ui_story_5081_50810401_69_dialog_content = "Pessoal...",
  ui_story_5081_50810401_70_dialog_content = "Vamos lá pessoal, vamos procurar sinais de Gronru nas pontuações altas!",
  ui_story_5081_50810402_1_dialog_content = "<color=#e8d9bb>FIM DE JOGO!</color>",
  ui_story_5081_50810402_2_dialog_content = "Perdemos novamente? Urgh, que se dane! Coloque mais fichas!",
  ui_story_5081_50810402_3_dialog_content = "Na verdade, estamos todos sem fichas...",
  ui_story_5081_50810402_4_dialog_content = "O quê? Jomu, vá buscar mais para nós!",
  ui_story_5081_50810402_5_dialog_content = "Eh? Eu? Você deve estar brincando... Sork, por que você não vai comprar mais alguns?",
  ui_story_5081_50810402_6_dialog_content = "Eu? Mas eu sou um funcionário aqui!",
  ui_story_5081_50810402_7_dialog_content = "Seria um pouco estranho, não seria? Além disso, você estava jogando como um lixo agora, Jomu! Pelo menos se torne útil de alguma forma!",
  ui_story_5081_50810402_8_dialog_content = "Jomu joga como lixo, chilro!",
  ui_story_5081_50810402_9_dialog_content = "E-Eu simplesmente não sou tão bom nesse tipo de jogo! Você não me culpa, não é? Chefe?",
  ui_story_5081_50810402_10_dialog_content = "Nah, especialmente porque eu também não sou tão bom nisso. Odi teve que me carregar o tempo todo.",
  ui_story_5081_50810402_11_dialog_content = "O verdadeiro problema é que mesmo com nossas habilidades combinadas, eu não acho que veremos a pontuação alta de Gronru...",
  ui_story_5081_50810402_12_dialog_content = "Porque nem conseguimos entrar na tabela de classificação!",
  ui_story_5081_50810402_13_dialog_content = "Eu sabia... Precisamos da ajuda da Batia para conseguir isso, mas...",
  ui_story_5081_50810402_14_dialog_content = "...",
  ui_story_5081_50810402_15_dialog_content = "Parece que ela não quer mais nada comigo agora!",
  ui_story_5081_50810402_16_dialog_content = "Heheh, eu não teria tanta certeza, PlayerName.",
  ui_story_5081_50810402_17_dialog_content = "Depois de trabalhar na loja por alguns dias, posso dizer que ela raramente se aproxima dos clientes para brincar com eles.",
  ui_story_5081_50810402_18_dialog_content = "Ela estava disposta a se associar a você no momento em que entrou neste lugar, o que significa que ela deve realmente gostar de você.",
  ui_story_5081_50810402_19_dialog_content = "Chilro! PlayerName tem potencial oculto!",
  ui_story_5081_50810402_20_dialog_content = "Mas ela parecia tão decepcionada comigo antes...",
  ui_story_5081_50810402_21_dialog_content = "Tenho certeza de que é apenas este evento de pré-venda afetando os nervos dela.",
  ui_story_5081_50810402_22_dialog_content = "Ela tem avaliado jogadores sem parar e aceitando desafios o tempo todo, além de suas funções habituais como proprietária do fliperama...",
  ui_story_5081_50810402_23_dialog_content = "Ela provavelmente está apenas muito cansada para prestar muita atenção em suas palavras agora.",
  ui_story_5081_50810402_24_dialog_content = "Não é sua culpa, PlayerName!",
  ui_story_5081_50810402_25_dialog_content = "... Você realmente acha isso?",
  ui_story_5081_50810402_26_dialog_content = "Você pode ser realmente lento às vezes, sabia disso? Você ainda não descobriu?",
  ui_story_5081_50810402_27_dialog_content = "Descobriu o quê?",
  ui_story_5081_50810402_28_dialog_content = "\"B\" é uma reclusa! Ela tem ansiedade social!",
  ui_story_5081_50810402_29_dialog_content = "Assumir uma loja como esta já é difícil o suficiente para alguém como ela.",
  ui_story_5081_50810402_30_dialog_content = "Mas para dar aos jogadores como nós um lugar para se reunir e jogar...",
  ui_story_5081_50810402_31_dialog_content = "Ela tem feito o seu melhor para superar sua ansiedade social e manter este lugar funcionando!",
  ui_story_5081_50810402_32_dialog_content = "Sabendo disso, faz sentido que ela não consiga te dar uma resposta quando você pergunta sobre coisas fora dos videogames, certo?",
  ui_story_5081_50810402_33_dialog_content = "Entendo...",
  ui_story_5081_50810402_34_dialog_content = "(Mas ainda assim, eu realmente não quero desistir de uma pista tão boa...)",
  ui_story_5081_50810402_35_dialog_content = "(Não consigo deixar de sentir que Gronru está de alguma forma conectado a este lugar!)",
  ui_story_5081_50810402_36_dialog_content = "Chefe? Chefe!",
  ui_story_5081_50810402_37_dialog_content = "Hã? O que agora, Jomu? Não me diga que você vai tentar me enganar de novo...",
  ui_story_5081_50810402_38_dialog_content = "Enganar você? Suas palavras cortam fundo, chefe! Acontece que eu me importo com seus interesses mais do que qualquer outra pessoa!",
  ui_story_5081_50810402_39_dialog_content = "E eu tive uma ideia apenas para você.",
  ui_story_5081_50810402_40_dialog_content = "E isso seria?",
  ui_story_5081_50810402_41_dialog_content = "Por que você não tenta limpar um B-Estágio?",
  ui_story_5081_50810402_42_dialog_content = "Um o que agora?",
  ui_story_5081_50810402_43_dialog_content = "Como a dona da loja não pode possivelmente atender a todos os desafiantes, ela montou uma série de estágios únicos em algumas das máquinas de jogos do fliperama.",
  ui_story_5081_50810402_44_dialog_content = "Se você conseguir eliminá-los...",
  ui_story_5081_50810402_45_dialog_content = "Ela pode até permitir que você copie a versão original deste jogo!",
  ui_story_5081_50810402_46_dialog_content = "Depois disso, podemos fazer um monte de cópias e vendê-las como versões oficiais!",
  ui_story_5081_50810402_47_dialog_content = "Também podemos esconder parte do conteúdo atrás de um paywall e ganhar ainda mais por cópia, heehee...",
  ui_story_5081_50810402_48_dialog_content = "Vamos fazer uma fortuna em pouco tempo!",
  ui_story_5081_50810402_49_dialog_content = "... E nos tornaremos as pessoas mais odiadas na comunidade de jogos! Eu pensei que você disse que ofendê-los era uma má ideia?",
  ui_story_5081_50810402_50_dialog_content = "É por isso que faremos tudo em seu nome, chefe! Ninguém jamais suspeitaria do lendário Celestita, afinal...",
  ui_story_5081_50810402_51_dialog_content = "Tá bom, já chega desses seus planos malucos. Já conheci tantos jogadores aqui hoje...",
  ui_story_5081_50810402_52_dialog_content = "Todos eles são muito legais e realmente amam videogames. Eu me recuso a enganá-los!",
  ui_story_5081_50810402_53_dialog_content = "Vamos chefe! Não seja assim!",
  ui_story_5081_50810402_54_dialog_content = "Ei, é aquele...",
  ui_story_5081_50810402_55_dialog_content = "Hã? O que está acontecendo ali?",
  ui_story_5081_50810402_56_dialog_content = "Parece um novo desafiante para mim. Eu vou dar as boas-vindas a eles!",
  ui_story_5081_50810402_57_dialog_content = "Claro, apenas tente não se esgueirar até eles com seu \"bem-vindo\" assustador de novo...",
  ui_story_5081_50810402_58_dialog_content = "Esse pode ser o motivo de você não estar fazendo tantas vendas!",
  ui_story_5081_50810402_59_dialog_content = "Outro novato que não sabe o seu lugar, hein? Vamos PlayerName, vamos lá.",
  ui_story_5081_50810402_60_dialog_content = "... Ir onde?",
  ui_story_5081_50810402_61_dialog_content = "Vá ver o que é todo esse alvoroço! Agora que penso nisso, você ainda não viu as habilidades de Batia em ação, viu?",
  ui_story_5081_50810402_62_dialog_content = "Eu acho que não...",
  ui_story_5081_50810402_63_dialog_content = "(Esta é provavelmente uma boa oportunidade para conhecer melhor a Batia também.)",
  ui_story_5081_50810402_64_dialog_content = "Farei o possível para assistir e aprender!",
  ui_story_5081_50810501_1_dialog_content = "Com licença, mas o dono do Hidden Fangs está?",
  ui_story_5081_50810501_2_dialog_content = "Ah? Este é o último desafiante?",
  ui_story_5081_50810501_3_dialog_content = "Eu já a vi antes! Ela é uma mercenária contratada de Umbraton e uma autoproclamada conhecedora de antiguidades!",
  ui_story_5081_50810501_4_dialog_content = "Alguém importante a contratou para vir aqui?",
  ui_story_5081_50810501_5_dialog_content = "De maneira nenhuma. Eu vim aqui por minha própria vontade.",
  ui_story_5081_50810501_6_dialog_content = "Fui informado que poderia comprar uma cópia de edição limitada de um jogo desafiando o dono do fliperama, uma pessoa de nome \"B.\"",
  ui_story_5081_50810501_7_dialog_content = "Ei, Allura! Que surpresa te ver aqui!",
  ui_story_5081_50810501_8_dialog_content = "PlayerName? ... Que surpresa inesperada.",
  ui_story_5081_50810501_9_dialog_content = "Você já garantiu uma cópia do jogo?",
  ui_story_5081_50810501_10_dialog_content = "Bom...",
  ui_story_5081_50810501_11_dialog_content = "Parece que não. Uma pena, já que comprar de você provavelmente me pouparia tempo. Ainda assim...",
  ui_story_5081_50810501_12_dialog_content = "Estou interessado em ver o quão habilidosa essa pessoa \"B\" realmente é.",
  ui_story_5081_50810501_13_dialog_content = "Outro desafiante... Seja bem-vindo.",
  ui_story_5081_50810501_14_dialog_content = "Oh? Então essa garotinha é a \"B\"?",
  ui_story_5081_50810501_15_dialog_content = "Nada mal, você demorou apenas quarenta e seis segundos para aparecer diante de mim... Aceita o meu desafio?",
  ui_story_5081_50810501_16_dialog_content = "Gostaria de perguntar algo primeiro... Por que você quer comprar este jogo?",
  ui_story_5081_50810501_17_dialog_content = "Para adicioná-lo à minha preciosa coleção, claro.",
  ui_story_5081_50810501_18_dialog_content = "Um jogo de fantasia totalmente restaurado é a fusão perfeita de tecnologia e entretenimento, além de ser uma antiguidade rara e inestimável.",
  ui_story_5081_50810501_19_dialog_content = "Os dados armazenados em seu cartucho são tão valiosos quanto as palavras escritas nos antigos tomos que colecionei.",
  ui_story_5081_50810501_20_dialog_content = "Se eu não conseguir adquirir este jogo de fantasia, o valor da minha coleção inteira cairá um ponto e meio por cento.",
  ui_story_5081_50810501_21_dialog_content = "Um coletor de dados, hein...",
  ui_story_5081_50810501_22_dialog_content = "Certo. Eu aceito seu desafio.",
  ui_story_5081_50810501_23_dialog_content = "O que? Sério?",
  ui_story_5081_50810501_24_dialog_content = "Mas não parece que Allura veio para jogar videogames também...",
  ui_story_5081_50810501_25_dialog_content = "A coleta de dados também é uma parte muito importante de ser um jogador, PlayerName.",
  ui_story_5081_50810501_26_dialog_content = "Além do design e da arte de um cartucho, os dados do videogame antigo armazenados dentro dele também são extremamente valiosos.",
  ui_story_5081_50810501_27_dialog_content = "O ato de colecionar em si também é um aspecto importante dos jogos...",
  ui_story_5081_50810501_28_dialog_content = "Este fliperama não é apenas um lar para jogadores - é também um lar para ávidos colecionadores!",
  ui_story_5081_50810501_29_dialog_content = "Você pode escolher qualquer jogo que goste, desde que possa ser jogado aqui.",
  ui_story_5081_50810501_30_dialog_content = "É exatamente o tipo de confiança que eu esperaria de um jogador lendário.",
  ui_story_5081_50810501_31_dialog_content = "Esta é a minha escolha, Imperador da Luz, Versão 98.",
  ui_story_5081_50810501_32_dialog_content = "... Que inesperado.",
  ui_story_5081_50810501_33_dialog_content = "Talvez eu estivesse errado em presumir, mas dada a sua aparência... Eu tinha certeza que você escolheria um jogo de tiro antes de qualquer outra coisa.",
  ui_story_5081_50810501_34_dialog_content = "Você não estava errado em supor, mas eu vim preparado para jogar este jogo e não tenho intenção de mudar minha decisão.",
  ui_story_5081_50810501_35_dialog_content = "O que eu admiro neste jogo é que ele é tanto clássico quanto acessível.",
  ui_story_5081_50810501_36_dialog_content = "... Do que diabos eles estão falando?",
  ui_story_5081_50810501_37_dialog_content = "O desafiante quer jogar um jogo de luta clássico, mas \"B\" acha que ela deveria escolher um jogo de tiro em vez disso.",
  ui_story_5081_50810501_38_dialog_content = "Então o que significa \"Versão 98\"? Não me diga... Poderia significar o Ano 1998 do Calendário Matutino?",
  ui_story_5081_50810501_39_dialog_content = "Exatamente. 1998 foi um bom ano para o entretenimento em Umbraton, e muitos jogos fantásticos foram lançados durante esse período...",
  ui_story_5081_50810501_40_dialog_content = "Ah! Eles estão prestes a começar!",
  ui_story_5081_50810501_41_dialog_content = "Não parece que você precisa se aquecer ou mesmo verificar sua lista de movimentos...",
  ui_story_5081_50810501_42_dialog_content = "Nesse caso... vamos começar.",
  ui_story_5081_50810501_43_dialog_content = "Uau! A primeira desafiante do dia já tomou seu lugar—",
  ui_story_5081_50810501_44_dialog_content = "E \"B\", a campeã indiscutível, entrou em sua própria conta!",
  ui_story_5081_50810501_45_dialog_content = "Lá está! Seu lendário nome de jogador!",
  ui_story_5081_50810501_46_dialog_content = "É ela, sem dúvida! Finalmente vamos vê-la em ação!",
  ui_story_5081_50810501_47_dialog_content = "C-Comentando ao vivo? Está tentando voltar para o seu antigo trabalho ou algo assim, Odi?",
  ui_story_5081_50810501_48_dialog_content = "Nenhuma batalha épica está completa sem alguns petiscos escolhidos! Lanches e bebidas de Umbraton à venda bem aqui!",
  ui_story_5081_50810501_49_dialog_content = "Esse cara, por outro lado, nunca parou de trabalhar... Espere, esses lanches não são do Deserto de Rediesel?",
  ui_story_5081_50810501_50_dialog_content = "Quieto, chefe! Quer dizer... Naturalmente, fiz alguns ajustes para se adequar aos gostos locais.",
  ui_story_5081_50810501_51_dialog_content = "De qualquer forma, se continuar perdendo tempo aqui, você vai perder o fim da primeira rodada!",
  ui_story_5081_50810501_52_dialog_content = "O-O que?",
  ui_story_5081_50810501_53_dialog_content = "<color=#e8d9bb>K.O.! Perfeito!</color>",
  ui_story_5081_50810501_54_dialog_content = "Surpreendente!",
  ui_story_5081_50810501_55_dialog_content = "\"B\" tomou a iniciativa desde o início da rodada! Com um pulo e um impulso, ela jogou seu oponente e não aliviou até o fim!",
  ui_story_5081_50810501_56_dialog_content = "Sem espaço para contra-atacar, o desafiante não teve escolha a não ser admitir a derrota!",
  ui_story_5081_50810501_57_dialog_content = "Indo com tudo na primeira rodada? Eu estava planejando contra-atacar após um segundo e meio...",
  ui_story_5081_50810501_58_dialog_content = "Mas ela conseguiu vencer em menos de um segundo.",
  ui_story_5081_50810501_59_dialog_content = "Mesmo assim, acho que entendo um pouco melhor seu estilo de jogo agora. Vamos continuar.",
  ui_story_5081_50810501_60_dialog_content = "Humph, você realmente acha que descobriu tudo?",
  ui_story_5081_50810501_61_dialog_content = "Vou te dar dez chances de me vencer. Se conseguir, vou deixar você comprar uma cópia do jogo.",
  ui_story_5081_50810501_62_dialog_content = "Então você está me subestimando severamente. Vamos lá!",
  ui_story_5081_50810501_63_dialog_content = "(Quando Batia se imerge em um jogo, é como se ela se tornasse uma pessoa completamente diferente.)",
  ui_story_5081_50810501_64_dialog_content = "(Confiante, séria, irrestrita, mas o mais importante... parece que ela está se divertindo.)",
  ui_story_5081_50810501_65_dialog_content = "(Esta poderia ser a verdadeira ela?)",
  ui_story_5081_50810501_66_dialog_content = "(Devo continuar assistindo, tanto o jogo quanto este jogador lendário...)",
  ui_story_5081_50810502_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810502_2_dialog_content = "Acabou! Após dez tentativas inteiras, o desafiante não conseguiu marcar sequer uma única vitória!",
  ui_story_5081_50810502_3_dialog_content = "Apesar disso, ela manteve a pressão e conseguiu encurralar \"B\" algumas vezes...",
  ui_story_5081_50810502_4_dialog_content = "Não há como negar! A desafiante de hoje merece reconhecimento, se não simplesmente por seu incrível espírito de luta!",
  ui_story_5081_50810502_5_dialog_content = "<size=30>Você está se animando um pouco demais, Odi...</size>",
  ui_story_5081_50810502_6_dialog_content = "...",
  ui_story_5081_50810502_7_dialog_content = "Inacreditável... Eu tinha a sensação de que perderia, mas não esperava perder tão espetacularmente.",
  ui_story_5081_50810502_8_dialog_content = "Como esperado do lendário \"B\". Admito minha derrota.",
  ui_story_5081_50810502_9_dialog_content = "Você é bem-vindo para me desafiar em outro jogo, se quiser...",
  ui_story_5081_50810502_10_dialog_content = "Sem necessidade. Estou completamente ciente da lacuna de habilidades entre nós agora. Seria inútil continuar.",
  ui_story_5081_50810502_11_dialog_content = "Eu entendo... mas suas habilidades ainda são dignas de respeito.",
  ui_story_5081_50810502_12_dialog_content = "Posso dizer que você fez muita prática de última hora, mas fez um ótimo trabalho ao pressionar suas vantagens e cobrir suas fraquezas.",
  ui_story_5081_50810502_13_dialog_content = "Seu conhecimento sobre os conjuntos de movimentos, proporções de dano, efeitos de habilidades e até mesmo os quadros de seus personagens é extremamente alto.",
  ui_story_5081_50810502_14_dialog_content = "Com mais tempo e treinamento, talvez...",
  ui_story_5081_50810502_15_dialog_content = "Você poderia me superar em uma única partida... desde que eu não esteja usando meus melhores personagens, é claro.",
  ui_story_5081_50810502_16_dialog_content = "\"B\" realmente reconheceu seu desafiante?",
  ui_story_5081_50810502_17_dialog_content = "Mesmo que ela estivesse se limitando, não consigo acreditar que \"B\" admitiu que alguém poderia realmente vencê-la!",
  ui_story_5081_50810502_18_dialog_content = "Oh? Não sei se tenho esse tipo de potencial... mas sua análise é totalmente correta.",
  ui_story_5081_50810502_19_dialog_content = "Para adicionar aquele jogo de fantasia à minha coleção, fiz algumas práticas de última hora neste jogo clássico.",
  ui_story_5081_50810502_20_dialog_content = "A razão pela qual eu não escolhi outro jogo é porque não tenho tanta experiência neles. No entanto...",
  ui_story_5081_50810502_21_dialog_content = "Uh... V-Você ainda quer me desafiar em alguma coisa?",
  ui_story_5081_50810502_22_dialog_content = "Não. Este é o meu cartão de visita.",
  ui_story_5081_50810502_23_dialog_content = "Eu, uh, não sei o que eu deveria fazer com isso.",
  ui_story_5081_50810502_24_dialog_content = "Apenas segure-o, se puder.",
  ui_story_5081_50810502_25_dialog_content = "Afinal, eu definitivamente quero experimentar a <color=#FFB400>alegria de jogar</color> agora.",
  ui_story_5081_50810502_26_dialog_content = "Especialmente quando se trata de jogos extremamente detalhados como este... Ah, eu não posso me permitir perder tão mal como hoje nunca mais!",
  ui_story_5081_50810502_27_dialog_content = "Você... se divertiu jogando agora há pouco?",
  ui_story_5081_50810502_28_dialog_content = "Sim, eu fiz. No início, eu só queria adicionar alguns jogos à minha coleção de antiguidades.",
  ui_story_5081_50810502_29_dialog_content = "Mas agora, finalmente percebo o quanto é mais prazeroso realmente jogá-los... e este jogo é muito mais complexo do que eu imaginava!",
  ui_story_5081_50810502_30_dialog_content = "Se existem mais jogos como este por aí, eu agradeceria muito se você os apresentasse para mim!",
  ui_story_5081_50810502_31_dialog_content = "Entendi... Na verdade, acho que podemos ter alguns cartuchos extras por aqui... Você também é bem-vindo para experimentá-los...",
  ui_story_5081_50810502_32_dialog_content = "E... se eu descobrir algum jogo semelhante, eu te aviso imediatamente.",
  ui_story_5081_50810502_33_dialog_content = "A-Além disso, você passou. Agora você é digno de comprar uma cópia deste jogo de fantasia!",
  ui_story_5081_50810502_34_dialog_content = "Huh? Mas eu pensei que tinha perdido?",
  ui_story_5081_50810502_35_dialog_content = "Ganhar ou perder não determina o valor de um jogador... O que mais importa é que eles gostem de jogar jogos!",
  ui_story_5081_50810502_36_dialog_content = "Entendo...",
  ui_story_5081_50810502_37_dialog_content = "Parece que é hora de voltar ao trabalho. Posso ajudá-la a pagar por isso aqui, senhorita.",
  ui_story_5081_50810502_38_dialog_content = "Parabéns! Finalmente, alguém ganhou o direito de comprar o jogo!",
  ui_story_5081_50810502_39_dialog_content = "Estou tão ciumento! Mas depois de vê-los frente a frente, sei que não tenho chance...",
  ui_story_5081_50810502_40_dialog_content = "Todos vocês são muito gentis.",
  ui_story_5081_50810502_41_dialog_content = "Este fliperama realmente é um lugar maravilhoso.",
  ui_story_5081_50810502_42_dialog_content = "Tudo bem! Entre ondas de aplausos, o recém-chegado emerge das Hidden Fangs, sorrindo e vitorioso!",
  ui_story_5081_50810502_43_dialog_content = "E enquanto ainda há muitos desafiantes no fliperama, eles não parecem tão confiantes agora!",
  ui_story_5081_50810502_44_dialog_content = "Você não precisava adicionar essa última parte, Odi! Além disso... Eu-Eu estou começando a pensar que não sou habilidoso o suficiente para—",
  ui_story_5081_50810502_45_dialog_content = "Você ainda não percebeu, PlayerName? Como ainda pode pensar que este desafio se baseia apenas em habilidade?",
  ui_story_5081_50810502_46_dialog_content = "Pense, seu bobo! Qual foi a razão pela qual \"B\" decidiu se juntar a você mais cedo?",
  ui_story_5081_50810502_47_dialog_content = "A razão, huh...",
  ui_story_5081_50810502_48_dialog_content = "É assim que eu deveria fazer as curvas? Eu entendi totalmente agora!",
  ui_story_5081_50810502_49_dialog_content = "Eu colecto Lumina sempre que derrapo numa curva, então eu deveria dispará-lo nos Eclipsitas? Acho que é melhor eu tentar!",
  ui_story_5081_50810502_50_dialog_content = "Naquela época... Eu estava totalmente perdido no jogo.",
  ui_story_5081_50810502_51_dialog_content = "Talvez ela tenha pensado que eu realmente gostava de jogos quando me viu assim, então decidiu se juntar a mim.",
  ui_story_5081_50810502_52_dialog_content = "Não precisa do \"talvez\"! Você realmente acha que chamou a atenção dela apenas com suas habilidades?",
  ui_story_5081_50810502_53_dialog_content = "Ei, não precisa ser tão direto!",
  ui_story_5081_50810502_54_dialog_content = "Contanto que você esteja disposto a respeitar, entender e aproveitar os jogos aqui, não terá problemas para entender ela.",
  ui_story_5081_50810502_55_dialog_content = "Você não encontrará uma pessoa mais amigável e entusiasmada do que \"B\" se você fizer isso!",
  ui_story_5081_50810502_56_dialog_content = "Há um porém... Ela consome uma tonelada de mana sempre que se anima, e também tem um tempo de recarga bastante longo!",
  ui_story_5081_50810502_57_dialog_content = "Eu entendo. Encontrar Gronru pode ser uma situação semelhante também.",
  ui_story_5081_50810502_58_dialog_content = "Eu só preciso tentar entender eles... e experimentar os videogames que eles amam tanto por mim mesmo.",
  ui_story_5081_50810502_59_dialog_content = "Uma vez que eu fizer isso, finalmente poderei ver as coisas da perspectiva deles e me aproximar de ambos.",
  ui_story_5081_50810502_60_dialog_content = "Talvez Gronru esteja apenas esperando por alguém que a entenda também.",
  ui_story_5081_50810502_61_dialog_content = "Estávamos esperando você dizer isso, chefe! E eu já tomei a liberdade de nos inscrever!",
  ui_story_5081_50810502_62_dialog_content = "Agora vamos desafiar \"B\" e fazer nossa fortuna!",
  ui_story_5081_50810502_63_dialog_content = "Desculpe-me, mas é aqui que eu posso desafiar a pessoa conhecida como \"B\"?",
  ui_story_5081_50810502_64_dialog_content = "Ah! Outro desafiante! Vamos dar uma olhada!",
  ui_story_5081_50810502_65_dialog_content = "Espere por mim, chefe!",
  ui_story_5081_50810601_1_dialog_content = "Que desafiante inesperado!",
  ui_story_5081_50810601_2_dialog_content = "Julgando pelas roupas dela, acho que ela é de Lumópolis!",
  ui_story_5081_50810601_3_dialog_content = "Alguém vai me responder? Estou aqui para desafiar o \"B\"!",
  ui_story_5081_50810601_4_dialog_content = "Quem está no comando aqui?",
  ui_story_5081_50810601_5_dialog_content = "Beretta?",
  ui_story_5081_50810601_6_dialog_content = "PlayerName? Você está trabalhando aqui por acaso?",
  ui_story_5081_50810601_7_dialog_content = "Se sim, você poderia me ajudar a me inscrever para o desafio?",
  ui_story_5081_50810601_8_dialog_content = "Não, acho que você está procurando pelo dono da loja... Ah, aqui ela vem!",
  ui_story_5081_50810601_9_dialog_content = "...",
  ui_story_5081_50810601_10_dialog_content = "Excelente!",
  ui_story_5081_50810601_11_dialog_content = "Perdoe-me por não ter notado você antes. Meu nome é Beretta e sou um médico de campo de Lumopolis.",
  ui_story_5081_50810601_12_dialog_content = "Como posso me dirigir a você? E como posso me inscrever para desafiar o lendário \"B\"?",
  ui_story_5081_50810601_13_dialog_content = "Você pode me chamar de Batia. Qual jogo você gostaria de jogar para o desafio?",
  ui_story_5081_50810601_14_dialog_content = "Qualquer jogo serve, mas eu preferiria jogar o seu jogo mais difícil e extenuante!",
  ui_story_5081_50810601_15_dialog_content = "Para ser honesto, esta é a primeira vez que visito um estabelecimento como este. Com tantos desafiantes e dificuldades à vista...",
  ui_story_5081_50810601_16_dialog_content = "Mesmo que eu nunca tenha jogado jogos seriamente antes, este é o lugar perfeito para testar minha determinação!",
  ui_story_5081_50810601_17_dialog_content = "... Isso é apenas um fliperama, não um campo de treinamento... Você só encontrará jogadores reunidos aqui.",
  ui_story_5081_50810601_18_dialog_content = "Se você quer testar sua determinação... E-eu sugiro ir para outro lugar.",
  ui_story_5081_50810601_19_dialog_content = "Os jogos são uma ótima maneira de testar a força de vontade! Ouvi dizer que muitos dos melhores soldados de Illumina treinam dessa maneira!",
  ui_story_5081_50810601_20_dialog_content = "Infelizmente, Lumopolis carece desses tipos de métodos de treinamento. Quando ouvi dizer que Umbraton tinha um lugar assim, eu tinha que vir e ver por mim mesmo!",
  ui_story_5081_50810601_21_dialog_content = "Agora, posso desafiar esse tal de \"B\" para uma luta de treinamento, por favor?",
  ui_story_5081_50810601_22_dialog_content = "E-Eu sou \"B.\"",
  ui_story_5081_50810601_23_dialog_content = "Mas eu me recuso a aceitar um desafio de alguém que não conhece as regras de um jogo...",
  ui_story_5081_50810601_24_dialog_content = "Se você realmente quer me desafiar... p-por favor, escolha um jogo e aprenda a jogá-lo primeiro.",
  ui_story_5081_50810601_25_dialog_content = "Muito bem, farei exatamente isso! Obrigado!",
  ui_story_5081_50810601_26_dialog_content = "Ela está realmente estudando como tocar!",
  ui_story_5081_50810601_27_dialog_content = "... Isso realmente está bem? Acho que ela está ainda mais focada em seu objetivo do que eu!",
  ui_story_5081_50810601_28_dialog_content = "Acho que \"B\" simplesmente não sabe como lidar com alguém como ela.",
  ui_story_5081_50810601_29_dialog_content = "Vencer seus oponentes o mais rápido possível é como ela geralmente faz as coisas.",
  ui_story_5081_50810601_30_dialog_content = "Algo me diz que isso não vai funcionar muito bem em alguém como Beretta...",
  ui_story_5081_50810601_31_dialog_content = "Ahh! Como isso pode ser?",
  ui_story_5081_50810601_32_dialog_content = "Eu estive aqui primeiro, não estive?",
  ui_story_5081_50810601_33_dialog_content = "Esse maníaco por treinamento não sabe a primeira coisa sobre videogames, sabe? Isso vai levar uma eternidade!",
  ui_story_5081_50810601_34_dialog_content = "Talvez devêssemos investigar métodos mais duvidosos, chefe...",
  ui_story_5081_50810601_35_dialog_content = "Não se preocupe, eu aprendo muito rápido. Eles também têm jogos de luta, que devem ser perfeitos para mim!",
  ui_story_5081_50810601_36_dialog_content = "Parece que Beretta vai escolher o mesmo jogo que Allura. Acho que é isso que ela quis dizer com \"clássico e acessível\", huh?",
  ui_story_5081_50810601_37_dialog_content = "O controle está todo destruído. Este jogo deve ser realmente muito popular.",
  ui_story_5081_50810601_38_dialog_content = "Com licença... mas alguém está mesmo ouvindo?",
  ui_story_5081_50810601_39_dialog_content = "Vocês dois... podem me desafiar.",
  ui_story_5081_50810601_40_dialog_content = "Hmm? O que quer dizer com isso?",
  ui_story_5081_50810601_41_dialog_content = "Vocês dois podem se unir contra mim. Eu ainda vou ganhar... então não importa.",
  ui_story_5081_50810601_42_dialog_content = "Admiro sua confiança, mas devo recusar.",
  ui_story_5081_50810601_43_dialog_content = "Perder em uma partida de dois contra um seria vergonhoso, mas vencer contra você não seria melhor.",
  ui_story_5081_50810601_44_dialog_content = "Embora este homem jovem pareça ser um completo fraco, os números ainda estariam a nosso favor.",
  ui_story_5081_50810601_45_dialog_content = "Recuso-me a aceitar isso—a menos que você se una a alguém você mesmo!",
  ui_story_5081_50810601_46_dialog_content = "Você maníaco por treinamento... Logo veremos quem é o verdadeiro fracote!",
  ui_story_5081_50810601_47_dialog_content = "Um aliado? ... Eu não preciso de um. Não há razão para eu incomodar alguém, já que...",
  ui_story_5081_50810601_48_dialog_content = "Se você não se importa—",
  ui_story_5081_50810601_49_dialog_content = "Seria bom se eu me juntasse a você?",
  ui_story_5081_50810601_50_dialog_content = "Hã?",
  ui_story_5081_50810601_51_dialog_content = "Haha, não sei se estou retribuindo o favor ou se é algo mais...",
  ui_story_5081_50810601_52_dialog_content = "Mas nós formamos uma boa equipe antes, não acha?",
  ui_story_5081_50810601_53_dialog_content = "Se não fosse por você, eu nunca teria passado por um estágio tão difícil. Então agora é a minha vez de ser seu Jogador 2!",
  ui_story_5081_50810601_54_dialog_content = "Você...",
  ui_story_5081_50810601_55_dialog_content = "Ver todos esses desafiantes sérios também está me deixando empolgado.",
  ui_story_5081_50810601_56_dialog_content = "Aposto que poderia aproveitar ao máximo este jogo se você me deixasse jogar na sua equipe!",
  ui_story_5081_50810601_57_dialog_content = "I-Se é assim que você realmente se sente...",
  ui_story_5081_50810601_58_dialog_content = "Então vamos jogar juntos!",
  ui_story_5081_50810601_59_dialog_content = "...",
  ui_story_5081_50810601_60_dialog_content = "Obrigado por isso, chefe! Você sabe o que fazer agora, certo?",
  ui_story_5081_50810601_61_dialog_content = "O quê? Do que você está falando?",
  ui_story_5081_50810601_62_dialog_content = "Com o seu sabotamento, essa partida de dois contra dois se transformará em uma luta de três contra um!",
  ui_story_5081_50810601_63_dialog_content = "Mesmo com esse maníaco por treinamento em nossa equipe, ainda teremos uma chance de vencê-la! Hahahaha!",
  ui_story_5081_50810601_64_dialog_content = "Com certeza vou te dar a sua parte depois!",
  ui_story_5081_50810601_65_dialog_content = "... Você acha que eu vou <color=#FFB400>sabotar</color> a partida?",
  ui_story_5081_50810601_66_dialog_content = "Chega! É hora de você sentir o poder do Último Celestita!",
  ui_story_5081_50810602_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_2_dialog_content = "Chefe, não! Isso não é o que combinamos!",
  ui_story_5081_50810602_3_dialog_content = "Pare de brincar, fracote! Você vai nos fazer perder a partida!",
  ui_story_5081_50810602_4_dialog_content = "Isso mesmo! E para constar, eu não concordei com nada! Agora vamos lá, estou pronto para continuar te apoiando, Batia!",
  ui_story_5081_50810602_5_dialog_content = "Então, vou deixar você lidar com essa luta.",
  ui_story_5081_50810602_6_dialog_content = "Hã?",
  ui_story_5081_50810602_7_dialog_content = "Foco, o jogo começou!",
  ui_story_5081_50810602_8_dialog_content = "Ok! Espere, Jomu, eu ainda não estou pronto! Você não tem modos?",
  ui_story_5081_50810602_9_dialog_content = "Desculpe, chefe, mas estou apenas jogando o jogo! Uma vez que a partida começa, vale tudo!",
  ui_story_5081_50810602_10_dialog_content = "A concentração é uma parte importante do treinamento, PlayerName! Eu também estou dando o meu máximo!",
  ui_story_5081_50810602_11_dialog_content = "I-Isso é um pouco—",
  ui_story_5081_50810602_12_dialog_content = "Não se preocupe, estou aqui.",
  ui_story_5081_50810602_13_dialog_content = "Apenas jogue o melhor que puder. Nós não vamos perder.",
  ui_story_5081_50810602_14_dialog_content = "Você está certo. Afinal, não posso perder com o lendário \"B\" ao meu lado!",
  ui_story_5081_50810602_15_dialog_content = "Jomu não é muito bom, e Beretta é completamente novo no jogo. Eu só preciso lidar com eles com uma mão calma e focada...",
  ui_story_5081_50810602_16_dialog_content = "Oh? Parece que este desafio de duplas entrou em uma fase completamente nova!",
  ui_story_5081_50810602_17_dialog_content = "\"B\" trocou de papéis com o Último Celestita e agora está jogando como suporte! Ela deve ter muita confiança nele!",
  ui_story_5081_50810602_18_dialog_content = "E deste lado, Treinamento Freak e Fraco estão lutando para colocar seu trabalho em equipe em ordem!",
  ui_story_5081_50810602_19_dialog_content = "Ei, Odi! Estamos na mesma equipe, lembra? Que tipo de nome é esse?",
  ui_story_5081_50810602_20_dialog_content = "Enquanto Training Freak avança diretamente contra seus oponentes, Weakling continua com sua provocação irritante! Isso poderia ser algum tipo de finta?",
  ui_story_5081_50810602_21_dialog_content = "É a nossa chance!",
  ui_story_5081_50810602_22_dialog_content = "<color=#e8d9bb>Vamo, vamo—tapa!</color>",
  ui_story_5081_50810602_23_dialog_content = "Ai! O Último Celestita está sendo brutalmente espancado! Essa barra de HP não está com uma boa aparência, pessoal! Por quanto tempo mais ele pode resistir?",
  ui_story_5081_50810602_24_dialog_content = "Urgh... T-Talvez devêssemos voltar atrás?",
  ui_story_5081_50810602_25_dialog_content = "Não entre em pânico. Eu já tenho o colega de equipe dela completamente sob controle.",
  ui_story_5081_50810602_26_dialog_content = "Quanto a ela, apenas fique de olho em seus movimentos... tanto dentro quanto fora do jogo.",
  ui_story_5081_50810602_27_dialog_content = "O caminho para a vitória deve ser perfeitamente claro.",
  ui_story_5081_50810602_28_dialog_content = "R-Realmente? Vamos ver...",
  ui_story_5081_50810602_29_dialog_content = "Toma isso! E isso! Não vou aliviar, não importa o quê!",
  ui_story_5081_50810602_30_dialog_content = "<color=#e8d9bb>Toque, toque, toque, toque, bang—</color>",
  ui_story_5081_50810602_31_dialog_content = "Lá está minha chance!",
  ui_story_5081_50810602_32_dialog_content = "Sob o ataque brutal do Treinador Fanático, O Último Celestita finalmente mostra suas presas e contra-ataca! Mas ele conseguirá manter a pressão?",
  ui_story_5081_50810602_33_dialog_content = "Ele está fazendo isso! Parece que o Maníaco por Treinamento cometeu um erro...",
  ui_story_5081_50810602_34_dialog_content = "O ataque continua vindo! Poderia ser este o fim?",
  ui_story_5081_50810602_35_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_36_dialog_content = "Ele conseguiu! O Último Celestita vence!",
  ui_story_5081_50810602_37_dialog_content = "Observando das linhas laterais e executando interferências, \"B\" levou sua colega de equipe à vitória apenas com orientação!",
  ui_story_5081_50810602_38_dialog_content = "...",
  ui_story_5081_50810602_39_dialog_content = "B-Melhor de três?",
  ui_story_5081_50810602_40_dialog_content = "Perdi desta vez... Não há mais nada a dizer.",
  ui_story_5081_50810602_41_dialog_content = "Apesar das minhas habilidades em combate, fui completamente e totalmente derrotado. Parece que esse tipo de treinamento deve ser abordado com muito mais seriedade.",
  ui_story_5081_50810602_42_dialog_content = "Perdoe-me. Fui arrogante por desafiá-lo.",
  ui_story_5081_50810602_43_dialog_content = "Há uma enorme diferença entre jogos de luta e combate real. As técnicas envolvidas também são completamente diferentes.",
  ui_story_5081_50810602_44_dialog_content = "Misturar os dois... nunca acaba bem.",
  ui_story_5081_50810602_45_dialog_content = "É assim mesmo? Interessante. May Eu peço que você explique este conceito como uma professora faria aos seus alunos?",
  ui_story_5081_50810602_46_dialog_content = "P-Professor? N-Não, eu nunca poderia... Eu não sou apto para ser professor de ninguém.",
  ui_story_5081_50810602_47_dialog_content = "Ah, que pena...",
  ui_story_5081_50810602_48_dialog_content = "Está bem, eu posso explicar para você no lugar da Batia.",
  ui_story_5081_50810602_49_dialog_content = "...Hã?",
  ui_story_5081_50810602_50_dialog_content = "PlayerName? Com certeza! Suas habilidades agora também foram bastante surpreendentes.",
  ui_story_5081_50810602_51_dialog_content = "Só consegui ver seus movimentos graças ao conselho de Batia, e acho...",
  ui_story_5081_50810602_52_dialog_content = "Você estava tratando o jogo como uma luta real, não estava?",
  ui_story_5081_50810602_53_dialog_content = "Claro que eu estava! Seja velocidade de reação, rastreamento de movimento ou posicionamento adequado...",
  ui_story_5081_50810602_54_dialog_content = "Todos esses aspectos são tão importantes nos videogames quanto são no combate ao vivo!",
  ui_story_5081_50810602_55_dialog_content = "Você tem razão, mas eles não são completamente iguais.",
  ui_story_5081_50810602_56_dialog_content = "Como assim?",
  ui_story_5081_50810602_57_dialog_content = "Em jogos de luta, entradas muito pequenas e precisas podem produzir resultados extremamente poderosos.",
  ui_story_5081_50810602_58_dialog_content = "Mas você estava apertando os botões e puxando o joystick com tanta força agora, como se estivesse tentando canalizar sua força real para o jogo.",
  ui_story_5081_50810602_59_dialog_content = "Existem todos os tipos de personagens em videogames, e eles nem sempre podem realizar as ações que você quer que eles façam. É por isso que...",
  ui_story_5081_50810602_60_dialog_content = "Não apenas você estava desperdiçando sua força, mas também estava afetando negativamente suas entradas, o que me deu a abertura que eu precisava para contra-atacar.",
  ui_story_5081_50810602_61_dialog_content = "... Então tudo que você precisou para me derrotar foi entender esse conceito simples?",
  ui_story_5081_50810602_62_dialog_content = "Sim... Mas novamente, foi apenas graças ao conselho de Batia.",
  ui_story_5081_50810602_63_dialog_content = "Eu... não fiz nada. É apenas bom senso, só isso.",
  ui_story_5081_50810602_64_dialog_content = "Sim, eu sei.",
  ui_story_5081_50810602_65_dialog_content = "É por isso que os soldados Illumina <color=#FFB400>se ajustam</color> para adequar-se ao <color=#FFB400>poder de fogo</color> de suas armas... Tudo faz sentido agora!",
  ui_story_5081_50810602_66_dialog_content = "Os jogos definitivamente podem ser usados para treinamento... Ou melhor, o treinamento pode ser visto como um tipo de jogo!",
  ui_story_5081_50810602_67_dialog_content = "Esta experiência foi surpreendente e esclarecedora!",
  ui_story_5081_50810602_68_dialog_content = "Obrigado, Batia! Seria certo se eu voltasse para te desafiar no futuro?",
  ui_story_5081_50810602_69_dialog_content = "?",
  ui_story_5081_50810602_70_dialog_content = "E-Isso depende... D-Você tinha...",
  ui_story_5081_50810602_71_dialog_content = "Hum?",
  ui_story_5081_50810602_72_dialog_content = "Acho que ela quer perguntar se você se divertiu agora, e se gostou de jogar aquele jogo.",
  ui_story_5081_50810602_73_dialog_content = "Claro! Foi uma experiência tão emocionante! Eu não fazia ideia de que videogames poderiam ser tão divertidos!",
  ui_story_5081_50810602_74_dialog_content = "E algo me diz que ganharei muito mais experiência se continuar jogando!",
  ui_story_5081_50810602_75_dialog_content = "Neste empreendimento, eu nunca vou vacilar!",
  ui_story_5081_50810602_76_dialog_content = "Então... Por favor, aceite isso.",
  ui_story_5081_50810602_77_dialog_content = "Ela passou! I-Isto não pode ser! Ela não faz ideia de quanto vale esse jogo...",
  ui_story_5081_50810602_78_dialog_content = "Você está me recomendando este jogo? Muito bem então! Vou praticar dia e noite assim que conseguir minha cópia!",
  ui_story_5081_50810602_79_dialog_content = "Estou ansioso para o nosso próximo duelo!",
  ui_story_5081_50810602_80_dialog_content = "Uh... T-T-Tudo bem!",
  ui_story_5081_50810602_81_dialog_content = "E uma vez que eu domine os segredos do treinamento de videogame da Illumina...",
  ui_story_5081_50810602_82_dialog_content = "Eu posso ter uma chance de finalmente redimir minha derrota contra Yingel!",
  ui_story_5081_50810602_83_dialog_content = "Yingel?",
  ui_story_5081_50810602_84_dialog_content = "Um oficial de inteligência na Federação Illumina, sim.",
  ui_story_5081_50810602_85_dialog_content = "Após minha derrota para ela durante o Exercício Militar Conjunto, frequentemente penso em como reivindicar a vitória sobre ela da melhor maneira.",
  ui_story_5081_50810602_86_dialog_content = "Até encontrei com ela no caminho para cá!",
  ui_story_5081_50810602_87_dialog_content = "Mas ela estava tão ocupada que não conseguiu me notar...",
  ui_story_5081_50810602_88_dialog_content = "Ela é...",
  ui_story_5081_50810602_89_dialog_content = "!",
  ui_story_5081_50810602_90_dialog_content = "Hã? Não é aquele Oficial de Inteligência Yingel?",
  ui_story_5081_50810602_91_dialog_content = "...",
  ui_story_5081_50810602_92_dialog_content = "Acho que não sou o único que foi ignorado.",
  ui_story_5081_50810602_93_dialog_content = "O que foi?",
  ui_story_5081_50810602_94_dialog_content = "Ah, nada.",
  ui_story_5081_50810602_95_dialog_content = "(O que uma oficial de inteligência de alto nível da Illumina está fazendo em Umbraton de qualquer maneira? Ela poderia estar procurando por Gronru também?)",
  ui_story_5081_50810602_96_dialog_content = "Bem, se você vê-la, avise-a sobre o meu desafio iminente!",
  ui_story_5081_50810602_97_dialog_content = "F-Farei.",
  ui_story_5081_50810602_98_dialog_content = "Jogo de fantasia - minha maior fonte de dinheiro até agora! Eu consegui... finalmente sou digno disso! Uau!",
  ui_story_5081_50810602_99_dialog_content = "Você ainda está falando sobre isso, Jomu? ... Huh? O que você está fazendo no chão?",
  ui_story_5081_50810602_100_dialog_content = "Eu consegui... Eu passei... Blegh...",
  ui_story_5081_50810602_101_dialog_content = "Parece que ele ficou um pouco enjoado de jogar por muito tempo... Eu sabia que ele não era adequado para este tipo de jogo!",
  ui_story_5081_50810602_102_dialog_content = "Se eu soubesse que ele estava disposto a arriscar a vida por dinheiro, nunca o teria trazido.",
  ui_story_5081_50810602_103_dialog_content = "Mesmo que ele nunca tenha parado de falar sobre ganhar dinheiro, quando eu o vi jogar mais cedo...",
  ui_story_5081_50810602_104_dialog_content = "Jomu parecia que ele estava se divertindo muito, não é?",
  ui_story_5081_50810602_105_dialog_content = "... Eu estava tão perto de enganar o \"B\" agora... Que pena...",
  ui_story_5081_50810602_106_dialog_content = "(Mesmo um comerciante ávido por dinheiro como Jomu pode ser sugado para jogar videogames. Acho que esse é o poder do seu apelo.)",
  ui_story_5081_50810602_107_dialog_content = "Minha cabeça está girando... Água... Preciso de água...",
  ui_story_5081_50810602_108_dialog_content = "Aguarde, vou buscar algumas bebidas para você e Odi. Depois de todo esse comentário, tenho certeza de que ela também está com sede.",
  ui_story_5081_50810602_109_dialog_content = "Pense nisso como um presente de agradecimento por me trazer aqui hoje.",
  ui_story_5081_50810602_110_dialog_content = "Eu volto já!",
  ui_story_5081_50810701_1_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_2_dialog_content = "Sou eu, ou essas máquinas realmente parecem que vieram da Illumina?",
  ui_story_5081_50810701_3_dialog_content = "Eu me pergunto o que Jomu e Odi gostariam de beber?",
  ui_story_5081_50810701_4_dialog_content = "Talvez algo \"clássico e acessível\"?",
  ui_story_5081_50810701_5_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_6_dialog_content = "...",
  ui_story_5081_50810701_7_dialog_content = "Eu sabia que alguém estava me observando.",
  ui_story_5081_50810701_8_dialog_content = "Quem está aí?",
  ui_story_5081_50810701_9_dialog_content = "Ahh! Eu... Eu me desculpe!",
  ui_story_5081_50810701_10_dialog_content = "Huh? É você, Batia.",
  ui_story_5081_50810701_11_dialog_content = "Desculpe por gritar agora há pouco, eu pensei que alguém estava tentando roubar minhas fichas ou algo assim.",
  ui_story_5081_50810701_12_dialog_content = "E-É mesmo... A-Ah...",
  ui_story_5081_50810701_13_dialog_content = "Uau! Isso é... sorvete? Mas por que você não está comendo? Parece que está prestes a derreter!",
  ui_story_5081_50810701_14_dialog_content = "E-É pra você...",
  ui_story_5081_50810701_15_dialog_content = "Espere... Você comprou isso só pra mim?",
  ui_story_5081_50810701_16_dialog_content = "Uhum.",
  ui_story_5081_50810701_17_dialog_content = "Então é melhor eu comer rápido! Graças a Deus, ainda não derreteu completamente...",
  ui_story_5081_50810701_18_dialog_content = "Não tenho certeza se ainda pode ser chamado de \"sorvete\" embora.",
  ui_story_5081_50810701_19_dialog_content = "Mas tudo bem! Sempre podemos comprar mais! Além disso, ainda está perfeitamente comestível. Uau, isso está frio!",
  ui_story_5081_50810701_20_dialog_content = "Sério? Estou tão feliz que você gostou.",
  ui_story_5081_50810701_21_dialog_content = "Além disso... eu quero te agradecer.",
  ui_story_5081_50810701_22_dialog_content = "Por se juntar a mim... e-e por me ajudar a lidar com aquele desafiante excessivamente entusiasmado.",
  ui_story_5081_50810701_23_dialog_content = "Eu deveria ser o único agradecendo a você! Eu nunca teria tido uma chance sem a sua ajuda.",
  ui_story_5081_50810701_24_dialog_content = "E já que você foi gentil o suficiente para me trazer sorvete, por que eu não te ofereço uma bebida? Suco ou café?",
  ui_story_5081_50810701_25_dialog_content = "Um... O-O suco de tomate, por favor...",
  ui_story_5081_50810701_26_dialog_content = "Tá saindo!",
  ui_story_5081_50810701_27_dialog_content = "<color=#e8d9bb>Clunk—</color>",
  ui_story_5081_50810701_28_dialog_content = "Aqui está! Então você gosta desse tipo de bebida, hein?",
  ui_story_5081_50810701_29_dialog_content = "Uh-uh... Eu não saio muito durante o dia, então dependo de coisas assim para nutrição... Funciona muito bem também.",
  ui_story_5081_50810701_30_dialog_content = "Uh, desculpe por perguntar... mas isso tem a ver com ser meio morcego?",
  ui_story_5081_50810701_31_dialog_content = "Faz... é por isso que sair é um problema para mim.",
  ui_story_5081_50810701_32_dialog_content = "Interagir com os outros... também não é muito fácil para mim.",
  ui_story_5081_50810701_33_dialog_content = "Sou um Auroriano como qualquer outro... mas não completamente.",
  ui_story_5081_50810701_34_dialog_content = "Há muitas coisas que outras pessoas podem fazer... que eu nunca poderia.",
  ui_story_5081_50810701_35_dialog_content = "É por isso que você fica em casa e joga até ser o melhor neles?",
  ui_story_5081_50810701_36_dialog_content = "É-E é embaraçoso, não é?",
  ui_story_5081_50810701_37_dialog_content = "Claro que não! Na verdade, é uma conquista inacreditável!",
  ui_story_5081_50810701_38_dialog_content = "Tornar-se o melhor em um único jogo é uma conquista impressionante para qualquer jogador.",
  ui_story_5081_50810701_39_dialog_content = "Mas o seu nome está no topo de todas as tabelas de classificação aqui - ou até mesmo em todo o Astra!",
  ui_story_5081_50810701_40_dialog_content = "\"B\" já é uma heroína e um símbolo por direito próprio—talvez até uma lenda! Quando eu vim para esta loja...",
  ui_story_5081_50810701_41_dialog_content = "Eu fiz isso com a intenção de também ampliar meus próprios horizontes!",
  ui_story_5081_50810701_42_dialog_content = "...",
  ui_story_5081_50810701_43_dialog_content = "M-Mas você não veio aqui com a intenção de jogar jogos.",
  ui_story_5081_50810701_44_dialog_content = "Haha, é verdade! Quando apareci pela primeira vez, meu objetivo era claro - encontrar meu amigo perdido Gronru.",
  ui_story_5081_50810701_45_dialog_content = "Veja, foi ela quem me apresentou a muitos jogos.",
  ui_story_5081_50810701_46_dialog_content = "Na maioria das vezes, eu apenas os aceitava porque ela os dava para mim.",
  ui_story_5081_50810701_47_dialog_content = "E eu só jogaria eles porque vieram de um amigo.",
  ui_story_5081_50810701_48_dialog_content = "É por isso que nunca imaginei que gostaria de um fliperama tanto quanto gosto agora.",
  ui_story_5081_50810701_49_dialog_content = "Quando penso em todas as partidas que jogamos hoje...",
  ui_story_5081_50810701_50_dialog_content = "Percebo o quanto me diverti aqui.",
  ui_story_5081_50810701_51_dialog_content = "Hmm... Eu entendo.",
  ui_story_5081_50810701_52_dialog_content = "Você realmente é capaz de aproveitar os videogames.",
  ui_story_5081_50810701_53_dialog_content = "Não sei se é por causa da minha história, dos meus objetivos, ou talvez algumas das responsabilidades que estou carregando...",
  ui_story_5081_50810701_54_dialog_content = "Mas... é um pouco difícil para mim aceitar que gosto deste tipo de coisa.",
  ui_story_5081_50810701_55_dialog_content = "Então, poder jogar videogames assim, sem qualquer medo de julgamento, me ajuda a enfrentar esse conflito interno de frente...",
  ui_story_5081_50810701_56_dialog_content = "Se eu pudesse aproveitar os jogos puramente como você e Gronru, aposto que poderíamos nos entender ainda mais.",
  ui_story_5081_50810701_57_dialog_content = "<size=30>Gronru... Estou com tanto ciúme que ela tem um amigo como você...</size>",
  ui_story_5081_50810701_58_dialog_content = "Então você a conhece?",
  ui_story_5081_50810701_59_dialog_content = "M-Mais ou menos... Afinal, ela é uma jogadora veterana e fez muitas contribuições especiais para a comunidade.",
  ui_story_5081_50810701_60_dialog_content = "M-Mas isso é tudo que eu sei sobre ela... Por favor, não me faça mais perguntas!",
  ui_story_5081_50810701_61_dialog_content = "Uau... Esses dois são lindos!",
  ui_story_5081_50810701_62_dialog_content = "Oh! Uh, você ouviu isso? Parece que podemos ter alguns novos desafiantes no fliperama!",
  ui_story_5081_50810701_63_dialog_content = "W-Nós provavelmente deveríamos ir ver!",
  ui_story_5081_50810701_64_dialog_content = "(Ela está pedindo para conhecer os desafiantes pessoalmente? Isso é uma visão rara...)",
  ui_story_5081_50810701_65_dialog_content = "(Parece que ela está desviando do assunto. Ela poderia estar falando sobre Gronru?)",
  ui_story_5081_50810701_66_dialog_content = "(Embora pareça suspeito, acho que jogar jogos é minha melhor chance de descobrir mais.)",
  ui_story_5081_50810701_67_dialog_content = "Claro, vamos para lá!",
  ui_story_5081_50810701_68_dialog_content = "<color=#e8d9bb>Nesse ponto, dois desafiantes com estilos muito únicos já haviam chamado a atenção de todo o fliperama.</color>",
  ui_story_5081_50810701_69_dialog_content = "<color=#e8d9bb>Um deles está sentado no sofá de maneira descolada.</color>",
  ui_story_5081_50810701_70_dialog_content = "Esta loja foi projetada para parecer tão retrô de propósito?",
  ui_story_5081_50810701_71_dialog_content = "As luzes e decorações são todas estilosas, e foram colocadas tão perfeitamente por todo o fliperama.",
  ui_story_5081_50810701_72_dialog_content = "Mal posso esperar para dar tudo de mim neste desafio!",
  ui_story_5081_50810701_73_dialog_content = "<color=#e8d9bb>O outro está pulando pela loja animadamente como um coelho.</color>",
  ui_story_5081_50810701_74_dialog_content = "Uau, é uma máquina de garra? Os prêmios dentro são tããão fofos!",
  ui_story_5081_50810701_75_dialog_content = "E este deve ser o lugar onde você troca pontos por prêmios! Ah, eu quero tudo o que eles têm...",
  ui_story_5081_50810701_76_dialog_content = "Diga, posso levar para casa todos os prêmios se eu continuar ganhando?",
  ui_story_5081_50810701_77_dialog_content = "Hunf!",
  ui_story_5081_50810701_78_dialog_content = "Claro que você pode. O truque é vencer tantas vezes primeiro.",
  ui_story_5081_50810701_79_dialog_content = "Mas isso não será necessário. Como proprietário do fliperama, eu tenho a palavra final por aqui.",
  ui_story_5081_50810701_80_dialog_content = "Se você conseguir me vencer em um jogo, pode levar o que quiser, e quanto quiser.",
  ui_story_5081_50810701_81_dialog_content = "Oh? Agora estamos falando...",
  ui_story_5081_50810701_82_dialog_content = "Ouvi falar sobre a lendária jogadora \"B\" e seu fliperama, mas nunca esperei que ela fosse tão audaciosa. Eu gosto disso!",
  ui_story_5081_50810701_83_dialog_content = "Uau, isso é super generoso da sua parte! Nesse caso... Vou fazer o meu melhor para te derrotar!",
  ui_story_5081_50810701_84_dialog_content = "Uau! Parece que temos alguns novos desafiantes! Vamos aplaudir a Bruxa Selvagem e a gracinha do Bolo!",
  ui_story_5081_50810701_85_dialog_content = "Os dois jogadores farão seus desafios ao mesmo tempo! <size=30>Mas a minha pergunta é, quem exatamente são eles? Um arrogante ambicioso e um colecionador de mercadorias?</size>",
  ui_story_5081_50810701_86_dialog_content = "Vamos nos animar para outra partida emocionante abaixo—",
  ui_story_5081_50810702_1_dialog_content = "Parece que o fogo do videogame não queima tão quente quanto as chamas reais...",
  ui_story_5081_50810702_2_dialog_content = "Eu também dei o meu melhor! Parece que vou ter ter que comprar todas essas coisas fofas para mim...",
  ui_story_5081_50810702_3_dialog_content = "Diga, Sr. Crocodilo, posso experimentar esse distintivo por um segundo?",
  ui_story_5081_50810702_4_dialog_content = "Peço desculpas, senhorita, mas você precisa trocar fichas por isso.",
  ui_story_5081_50810702_5_dialog_content = "Ah, ok! Vou buscar alguns agora mesmo!",
  ui_story_5081_50810702_6_dialog_content = "... E ela simplesmente fugiu?",
  ui_story_5081_50810702_7_dialog_content = "Diga, você não estaria interessado em se juntar a mim, estaria?",
  ui_story_5081_50810702_8_dialog_content = "Com o lendário jogador \"B\" ao meu lado, poderíamos começar uma nova era de jogos no mundo!",
  ui_story_5081_50810702_9_dialog_content = "Quando esse dia chegar, seu fliperama pode ficar superlotado com todos os novos clientes que você terá!",
  ui_story_5081_50810702_10_dialog_content = "Eu... Uh... Embora crescer a comunidade de jogos não seja necessariamente uma coisa ruim...",
  ui_story_5081_50810702_11_dialog_content = "Eu nunca fiz nada tão extremo, e... e eu realmente não quero fazer também! Desculpe...",
  ui_story_5081_50810702_12_dialog_content = "Forte, mas humilde, e apegado ao que você sabe, hein?",
  ui_story_5081_50810702_13_dialog_content = "Está bem. O que mais importa é que você conseguiu chamar minha atenção.",
  ui_story_5081_50810702_14_dialog_content = "Procure-me sempre que quiser se juntar a mim.",
  ui_story_5081_50810702_15_dialog_content = "D-Tem um desses também?",
  ui_story_5081_50810702_16_dialog_content = "Um do que?",
  ui_story_5081_50810702_17_dialog_content = "Um cartão com o seu nome nele. Eu consegui um mais cedo.",
  ui_story_5081_50810702_18_dialog_content = "Ela quer dizer um cartão de visita.",
  ui_story_5081_50810702_19_dialog_content = "Haha, claro que eu tenho um! Aqui está, espero ouvir de você em breve.",
  ui_story_5081_50810702_20_dialog_content = "Ufa...",
  ui_story_5081_50810702_21_dialog_content = "Eu diria que correu bem tranquilo, considerando tudo...",
  ui_story_5081_50810702_22_dialog_content = "Por que você não perguntou se eles estavam se divertindo desta vez?",
  ui_story_5081_50810702_23_dialog_content = "Hum...",
  ui_story_5081_50810702_24_dialog_content = "D-Eu fiz a pergunta errada de novo?",
  ui_story_5081_50810702_25_dialog_content = "M-Mesmo para alguém como eu, é fácil ver que eles se divertiram jogando aquele jogo...",
  ui_story_5081_50810702_26_dialog_content = "Mas quando os observei no jogo agora há pouco...",
  ui_story_5081_50810702_27_dialog_content = "Eles não pareciam tão animados ou tão imersos quanto você, não é?",
  ui_story_5081_50810702_28_dialog_content = "Você ficou tão chateado comigo porque eu não estava concentrado no jogo... Espero que eles não tenham te chateado também!",
  ui_story_5081_50810702_29_dialog_content = "Na verdade, não. Esses dois são mais do tipo social quando se trata de jogos.",
  ui_story_5081_50810702_30_dialog_content = "Você se lembra do que aquele conhecedor de antiguidades disse mais cedo?",
  ui_story_5081_50810702_31_dialog_content = "Algo sobre videogames serem a fusão de tecnologia e entretenimento, certo?",
  ui_story_5081_50810702_32_dialog_content = "Sim. Os videogames são muito mais do que algo para ser jogado.",
  ui_story_5081_50810702_33_dialog_content = "Um bom jogo é como uma obra de arte—cada aspecto único dele tem o potencial de atrair jogadores.",
  ui_story_5081_50810702_34_dialog_content = "Algumas pessoas jogam pela história e se concentram nos detalhes mais finos do mundo do jogo.",
  ui_story_5081_50810702_35_dialog_content = "Outros estão mais interessados na arte e design de um jogo e até convidam outras pessoas para jogar de role-play com eles.",
  ui_story_5081_50810702_36_dialog_content = "Às vezes, jogos temáticos como esse geram enormes ondas de interesse. É assim que muitas pessoas se tornam jogadoras em primeiro lugar.",
  ui_story_5081_50810702_37_dialog_content = "Há mais nos jogos do que apenas vencer níveis...",
  ui_story_5081_50810702_38_dialog_content = "É por isso que pessoas que não estão focadas em vencer também são dignas de aproveitar os jogos.",
  ui_story_5081_50810702_39_dialog_content = "Odi mencionou algo semelhante mais cedo hoje. Ela disse que a parte mais importante de um videogame é o jogador.",
  ui_story_5081_50810702_40_dialog_content = "Concordo. É difícil para os jogadores encontrar alegria nos videogames quando se afastam da comunidade de jogos.",
  ui_story_5081_50810702_41_dialog_content = "É por isso que eu deixei Gronru me convencer a assumir este fliperama...",
  ui_story_5081_50810702_42_dialog_content = "Gronru de novo, huh?",
  ui_story_5081_50810702_43_dialog_content = "D-Disse isso? Desculpe, eu não queria mencioná-la novamente! Apenas esqueça isso!",
  ui_story_5081_50810702_44_dialog_content = "Sim, eu sei como funciona. Não vou me intrometer mais, eu prometo.",
  ui_story_5081_50810702_45_dialog_content = "Apesar de como você tende a minimizar as coisas, acho que isso é algo que só você pode alcançar...",
  ui_story_5081_50810702_46_dialog_content = "O que é isso?",
  ui_story_5081_50810702_47_dialog_content = "Gerenciando este fliperama e dando aos jogadores um lugar para relaxar e se divertir.",
  ui_story_5081_50810702_48_dialog_content = "Quem mais além do lendário \"B\" poderia ter feito isso tão bem?",
  ui_story_5081_50810702_49_dialog_content = "M-Mas eu não sou bom em socializar com as pessoas de jeito nenhum! Eu não acho que estou apto a proporcionar aos jogadores qualquer tipo de experiência positiva...",
  ui_story_5081_50810702_50_dialog_content = "Estou apenas fornecendo um local, só isso.",
  ui_story_5081_50810702_51_dialog_content = "É isso que você acha?",
  ui_story_5081_50810702_52_dialog_content = "Porque para mim, pareceu que você interagiu muito bem com os desafiantes de hoje.",
  ui_story_5081_50810702_53_dialog_content = "Há uma razão para as pessoas te respeitarem e se reunirem neste lugar, sabe?",
  ui_story_5081_50810702_54_dialog_content = "Não sou tão especial... e mesmo que você me elogie, ainda não vou te contar—",
  ui_story_5081_50810702_55_dialog_content = "Diga-me o quê?",
  ui_story_5081_50810702_56_dialog_content = "Chefe! Temos outro novo visitante!",
  ui_story_5081_50810702_57_dialog_content = "É um desafiante? Já tô indo aí...",
  ui_story_5081_50810702_58_dialog_content = "Não exatamente...",
  ui_story_5081_50810702_59_dialog_content = "Ele está usando um uniforme da Illumina, e fala como se estivesse seguindo um roteiro. Não acho que ele seja algum tipo de jogador. Além disso...",
  ui_story_5081_50810702_60_dialog_content = "Você não se meteu em problemas recentemente, não é PlayerName?",
  ui_story_5081_50810702_61_dialog_content = "Porque aquele cara pediu por você pelo nome!",
  ui_story_5081_50810801_1_dialog_content = "Alguém em um uniforme de Illumina está me procurando? Não me diga...",
  ui_story_5081_50810801_2_dialog_content = "Ai...",
  ui_story_5081_50810801_3_dialog_content = "Você finalmente está aqui, PlayerName. Posso ter uma palavra com você, por favor?",
  ui_story_5081_50810801_4_dialog_content = "Claro... Não se preocupe, todos estão ocupados demais jogando para nos notar.",
  ui_story_5081_50810801_5_dialog_content = "Bom te ver novamente, Oficial de Inteligência Anatoli.",
  ui_story_5081_50810801_6_dialog_content = "Da mesma forma, PlayerName. Irei direto ao ponto.",
  ui_story_5081_50810801_7_dialog_content = "Primeiro, permita-me agradecer pelos seus esforços em auxiliar a Illumina durante este momento crítico.",
  ui_story_5081_50810801_8_dialog_content = "Se eu posso perguntar, como está indo sua investigação?",
  ui_story_5081_50810801_9_dialog_content = "Para dizer de uma maneira, eu venci cerca de cinco dos oito ginásios...",
  ui_story_5081_50810801_10_dialog_content = "Entendi. Você quer dizer que sua missão está sessenta e dois ponto cinco por cento completa?",
  ui_story_5081_50810801_11_dialog_content = "Bem, eu também tenho que derrotar os Quatro Elite...",
  ui_story_5081_50810801_12_dialog_content = "Posso pedir para você explicar as coisas em termos leigos?",
  ui_story_5081_50810801_13_dialog_content = "Haha... É meio difícil quantificar o progresso quando você está procurando por alguém.",
  ui_story_5081_50810801_14_dialog_content = "Mas eu tenho feito o meu melhor para realizar essa missão para Migard e o Comitê! Confie em mim, eu vou conseguir!",
  ui_story_5081_50810801_15_dialog_content = "É mesmo? Novamente, agradeço por suas contribuições à Illumina.",
  ui_story_5081_50810801_16_dialog_content = "De acordo com minhas informações, este lugar realmente tem alguns jogos muito atraentes reservados.",
  ui_story_5081_50810801_17_dialog_content = "Aliado a essa atmosfera confortável, é o lugar perfeito para esquecer as preocupações e se perder em mundos virtuais.",
  ui_story_5081_50810801_18_dialog_content = "Quando eu estava esperando por você, eu estava preocupado que você também tivesse se perdido nesses mundos... mas parece que eu estava pensando demais nas coisas.",
  ui_story_5081_50810801_19_dialog_content = "Eu nunca perderia de vista uma missão tão importante! Você realmente não deveria brincar assim, Anatoli! Hahaha...",
  ui_story_5081_50810801_20_dialog_content = "Então você veio aqui só para obter um relatório de status para Migard?",
  ui_story_5081_50810801_21_dialog_content = "Para ser franco, não. Na verdade, pode-se dizer que temos um pouco de conflito entre nós.",
  ui_story_5081_50810801_22_dialog_content = "Conflito?",
  ui_story_5081_50810801_23_dialog_content = "Não é nada com que se preocupar. Quando se trata da missão, nossos objetivos ainda são os mesmos.",
  ui_story_5081_50810801_24_dialog_content = "Os jogadores aqui estão muito mais interessados em tecnologia antiga do que a maioria das pessoas. Acredito que eu poderia coletar algumas informações muito interessantes deles.",
  ui_story_5081_50810801_25_dialog_content = "... Se eu pudesse ficar um pouco mais.",
  ui_story_5081_50810801_26_dialog_content = "Se é assim que você se sente, então por que não encontramos algo para você jogar?",
  ui_story_5081_50810801_27_dialog_content = "Bem, há um jogo que despertou meu interesse.",
  ui_story_5081_50810801_28_dialog_content = "O chamado Crise Eclipsite.",
  ui_story_5081_50810801_29_dialog_content = "Os Eclipsitas neste jogo são supostamente bastante realistas, assim como as armas que estão disponíveis para os jogadores.",
  ui_story_5081_50810801_30_dialog_content = "Às vezes me pergunto se foi desenvolvido a partir de um programa de treinamento falho da Illumina.",
  ui_story_5081_50810801_31_dialog_content = "Por que você não tenta então? Afinal, ainda tenho muitas fichas.",
  ui_story_5081_50810801_32_dialog_content = "Acho que vou. Sua generosidade é muito apreciada.",
  ui_story_5081_50810801_33_dialog_content = "<color=#e8d9bb>Toque, toque, toque, toque—</color>",
  ui_story_5081_50810801_34_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5081_50810801_35_dialog_content = "Graah...",
  ui_story_5081_50810801_36_dialog_content = "Os controles são surpreendentemente fluidos e responsivos! Muito desafiador para os jogadores!",
  ui_story_5081_50810801_37_dialog_content = "<color=#e8d9bb>Toque, toque, toque, toque—</color>",
  ui_story_5081_50810801_38_dialog_content = "O combate também é tão realista! Infelizmente, tokens não podem ser usados para reviver nossos camaradas caídos na vida real...",
  ui_story_5081_50810801_39_dialog_content = "...",
  ui_story_5081_50810801_40_dialog_content = "Huh? Você ainda não terminou o nível, Anatoli.",
  ui_story_5081_50810801_41_dialog_content = "Eu não vim aqui para jogar jogos. Eu só queria experimentá-los brevemente por mim mesmo.",
  ui_story_5081_50810801_42_dialog_content = "E agora que eu tenho, não posso deixar de me sentir um pouco arrependido.",
  ui_story_5081_50810801_43_dialog_content = "Remorso?",
  ui_story_5081_50810801_44_dialog_content = "Este jogo tem o potencial de servir como um programa de treinamento adequado e nos ajudar muito nas batalhas futuras...",
  ui_story_5081_50810801_45_dialog_content = "Mas parece que os jogadores aqui só valorizam isso como uma fonte de entretenimento.",
  ui_story_5081_50810801_46_dialog_content = "Faz-me pensar, se tantas pessoas encontram tanta alegria em destruir Eclipsitas nos jogos...",
  ui_story_5081_50810801_47_dialog_content = "Não seria melhor gastar seu tempo e energia eliminando Eclipsitas reais no campo de batalha?",
  ui_story_5081_50810801_48_dialog_content = "Este é realmente o valor dos videogames de Astra? Talvez eu não entenda completamente, mas parece um desperdício de—",
  ui_story_5081_50810801_49_dialog_content = "<color=#e8d9bb>Toque, toque, toque, toque—</color>",
  ui_story_5081_50810801_50_dialog_content = "Huh? É—",
  ui_story_5081_50810801_51_dialog_content = "Abandonar um jogo quando ainda não está terminado... Se alguém está sendo desperdiçador, é você.",
  ui_story_5081_50810801_52_dialog_content = "Não vou permitir esse tipo de comportamento no meu fliperama.",
  ui_story_5081_50810801_53_dialog_content = "Seu fliperama, você diz? Você deve ser o dono.",
  ui_story_5081_50810801_54_dialog_content = "Perdoe-me se violei as regras do seu estabelecimento. Garanto que vou terminar de jogar a partir de agora.",
  ui_story_5081_50810801_55_dialog_content = "Você é um soldado da Illumina, não é?",
  ui_story_5081_50810801_56_dialog_content = "De fato, eu sou.",
  ui_story_5081_50810801_57_dialog_content = "Então, reúna toda a sua habilidade e experiência de treinamento - tente superar minha pontuação!",
  ui_story_5081_50810801_58_dialog_content = "Não tenho desejo de competir, mas se é isso que você deseja...",
  ui_story_5081_50810801_59_dialog_content = "<color=#e8d9bb>Toque, toque, toque—toque, toque, toque, toque</color>",
  ui_story_5081_50810801_60_dialog_content = "<color=#e8d9bb>Bum! Bum!</color>",
  ui_story_5081_50810801_61_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5081_50810801_62_dialog_content = "I-Incrível! Eles estão jogando como se estivessem possuídos por monstros!",
  ui_story_5081_50810801_63_dialog_content = "Mas Anatoli... De alguma forma, a pontuação dele é muito menor que a dela!",
  ui_story_5081_50810801_64_dialog_content = "Eu não acho... que já a vi jogar tão sério antes...",
  ui_story_5081_50810801_65_dialog_content = "Na sua opinião... eu não sou digno disso?",
  ui_story_5081_50810801_66_dialog_content = "... Perdão, mas você está falando comigo?",
  ui_story_5081_50810801_67_dialog_content = "Sim. Como alguém que não pode lutar contra os Eclipsitas na vida real... Você acha que eu tenho o direito de lutar contra eles em um videogame?",
  ui_story_5081_50810801_68_dialog_content = "Não seria possível que algumas pessoas simplesmente não nasceram para lutar contra os Eclipsitas... ou mesmo para deixar a segurança de suas casas?",
  ui_story_5081_50810801_69_dialog_content = "Mas mesmo assim, talvez eles ainda queiram resistir aos monstros que invadiram nosso mundo...",
  ui_story_5081_50810801_70_dialog_content = "Mesmo que seja apenas dando a todos um lugar para se reunirem e se divertirem.",
  ui_story_5081_50810801_71_dialog_content = "Uma pessoa assim... ainda tem algo a oferecer ao mundo, não acha?",
  ui_story_5081_50810801_72_dialog_content = "Eu...",
  ui_story_5081_50810801_73_dialog_content = "Não perca o foco ou você perderá.",
  ui_story_5081_50810801_74_dialog_content = "Perdoe-me.",
  ui_story_5081_50810801_75_dialog_content = "Vou concentrar toda a minha força para terminar este jogo...",
  ui_story_5081_50810802_1_dialog_content = "<color=#e8d9bb>Missão Concluída!</color>",
  ui_story_5081_50810802_2_dialog_content = "Acabou agora? Mal posso acreditar que tanto tempo já passou.",
  ui_story_5081_50810802_3_dialog_content = "Ou que eu perdi por uma margem tão grande...",
  ui_story_5081_50810802_4_dialog_content = "Devo admitir, sua habilidade de tiro é tão aguçada quanto sua proficiência em videogames.",
  ui_story_5081_50810802_5_dialog_content = "Acredito que suas habilidades são superadas apenas por Aurorians que passaram pelo treinamento especial de combate do Oficial Yingel...",
  ui_story_5081_50810802_6_dialog_content = "Você se divertiu?",
  ui_story_5081_50810802_7_dialog_content = "Hum?",
  ui_story_5081_50810802_8_dialog_content = "Por que, sim! Se eu tivesse que avaliar a qualidade deste jogo, eu daria a ele a classificação mais alta possível.",
  ui_story_5081_50810802_9_dialog_content = "Mas você poderia por favor me dizer por que ainda está jogando isso?",
  ui_story_5081_50810802_10_dialog_content = "Ah! Não se incomode comigo, estou apenas limpando o resto das missões secundárias... Me incomoda se eu não terminar um jogo inteiro.",
  ui_story_5081_50810802_11_dialog_content = "E também... E-eu me sinto muito mais corajoso ao falar com as pessoas se estou olhando para uma tela!",
  ui_story_5081_50810802_12_dialog_content = "Nem todos têm a oportunidade de lutar contra Eclipsitas na linha de frente.",
  ui_story_5081_50810802_13_dialog_content = "Algumas pessoas trabalham nos campos, enquanto outras constroem defesas...",
  ui_story_5081_50810802_14_dialog_content = "Alguns voam por todo Astra entregando mensagens importantes, e alguns permanecem em seus laboratórios resolvendo problemas técnicos...",
  ui_story_5081_50810802_15_dialog_content = "Mas acho que todos merecem uma chance de relaxar e descomprimir, bem como uma chance de se desafiar!",
  ui_story_5081_50810802_16_dialog_content = "Algo que os ajude a entender o perigo dos Eclipsitas, enquanto também renova o desejo de trabalhar em direção a um objetivo comum...",
  ui_story_5081_50810802_17_dialog_content = "Você não acha que é uma boa maneira de conectar os Aurorianos que não conseguem lutar contra os Eclipsitas com aqueles que conseguem?",
  ui_story_5081_50810802_18_dialog_content = "O quê, exatamente?",
  ui_story_5081_50810802_19_dialog_content = "Ela está falando sobre o jogo que você acabou de jogar, Anatoli.",
  ui_story_5081_50810802_20_dialog_content = "Eu vi suas expressões enquanto você estava jogando também...",
  ui_story_5081_50810802_21_dialog_content = "Sério, diligente, orgulhoso de suas conquistas e incomodado com suas falhas.",
  ui_story_5081_50810802_22_dialog_content = "Essas emoções não são diferentes das que você experimenta fora dos jogos, por isso você deve dar uma resposta honesta à Batia.",
  ui_story_5081_50810802_23_dialog_content = "Você realmente acha que as coisas só valem a pena se puderem ser usadas na luta contra os Eclipsitas?",
  ui_story_5081_50810802_24_dialog_content = "...",
  ui_story_5081_50810802_25_dialog_content = "Por favor, me perdoe por não perceber meu erro mais cedo...",
  ui_story_5081_50810802_26_dialog_content = "Algumas das coisas que acabei de dizer... foram destinadas a pessoas que nem mesmo estão aqui agora.",
  ui_story_5081_50810802_27_dialog_content = "Talvez eu estivesse tentando desabafar meu estresse e frustração com eles.",
  ui_story_5081_50810802_28_dialog_content = "Por favor, permita-me usar o conhecimento que adquiri enquanto jogava este jogo para corrigir minha resposta.",
  ui_story_5081_50810802_29_dialog_content = "Claro, vá em frente.",
  ui_story_5081_50810802_30_dialog_content = "Os videogames não são inúteis - muito pelo contrário, na verdade.",
  ui_story_5081_50810802_31_dialog_content = "A atmosfera deste fliperama é um reflexo direto da missão original de Illumina.",
  ui_story_5081_50810802_32_dialog_content = "Nossas lutas e sacrifícios intermináveis, não são eles para o propósito de criar um mundo pacífico, livre da ameaça dos Eclipsitas?",
  ui_story_5081_50810802_33_dialog_content = "Um mundo onde aqueles que não conseguem se defender dos Eclipsitas também podem ter vidas longas e felizes...",
  ui_story_5081_50810802_34_dialog_content = "Os inúmeros sacrifícios que fizemos até este ponto são o que realmente importa.",
  ui_story_5081_50810802_35_dialog_content = "Lutar e sacrificar simplesmente por fazê-lo é perder de vista nossos objetivos e desejos.",
  ui_story_5081_50810802_36_dialog_content = "Ah... Me desculpe por dar uma resposta tão longa.",
  ui_story_5081_50810802_37_dialog_content = "Mas meu coração e mente estão muito confortados agora... Obrigado, PlayerName e Senhorita Batia.",
  ui_story_5081_50810802_38_dialog_content = "...",
  ui_story_5081_50810802_39_dialog_content = "Eu não disse nada, sabe. Talvez isso fosse algo que o jogo deveria mostrar a você?",
  ui_story_5081_50810802_40_dialog_content = "De fato, eu nunca considerei os pensamentos e sentimentos daqueles que não podem lutar contra Eclipsitas antes de jogar este jogo.",
  ui_story_5081_50810802_41_dialog_content = "Mas agora sinto que ganhei uma compreensão um pouco melhor.",
  ui_story_5081_50810802_42_dialog_content = "Devo manter uma abordagem mais aberta ao coletar informações de agora em diante...",
  ui_story_5081_50810802_43_dialog_content = "Não se esqueça de relaxar e se divertir de vez em quando! Você é sempre bem-vindo no fliperama!",
  ui_story_5081_50810802_44_dialog_content = "Obrigado. Eu só gostaria que o Oficial Yingel também visse as coisas desta maneira.",
  ui_story_5081_50810802_45_dialog_content = "<size=30>Ela tem se esforçado tanto ultimamente, talvez mais do que o necessário.</size>",
  ui_story_5081_50810802_46_dialog_content = "... Mas não se preocupe. Garantirei que este assunto chegue a uma conclusão satisfatória.",
  ui_story_5081_50810802_47_dialog_content = "Uh, que assunto?",
  ui_story_5081_50810802_48_dialog_content = "Entrarei em contato com você assim que for resolvido, fique tranquilo.",
  ui_story_5081_50810802_49_dialog_content = "Até então, por favor, aguarde pacientemente pelas minhas boas notícias...",
  ui_story_5081_50810802_50_dialog_content = "... Ele se foi?",
  ui_story_5081_50810802_51_dialog_content = "Sim... E parece que ele escondeu algo importante de nós.",
  ui_story_5081_50810802_X51_dialog_content = "(Após se despedir de Jomu com Odi e ajudar Batia com algumas tarefas, o dia estava quase acabando.)",
  ui_story_5081_50810802_X52_dialog_content = "(Os clientes estavam saindo para a noite. Quando Batia e eu éramos os únicos restantes no fliperama, decidimos fechar a loja e sair para uma caminhada.)",
  ui_story_5081_50810802_X53_dialog_content = "Obrigada...",
  ui_story_5081_50810802_X54_dialog_content = "Por que você está me agradecendo desta vez?",
  ui_story_5081_50810802_52_dialog_content = "Para muitas coisas! Primeiro, obrigado por me ajudar a falar com aquele soldado de Illumina... Mas eu tenho que perguntar...",
  ui_story_5081_50810802_53_dialog_content = "O que eu disse a ele agora... Fui longe demais?",
  ui_story_5081_50810802_54_dialog_content = "Afinal... Eu sou apenas um inútil recluso que só sabe jogar jogos...",
  ui_story_5081_50810802_55_dialog_content = "É por isso que valorizo jogos como este, então eu...",
  ui_story_5081_50810802_56_dialog_content = "Você não foi longe demais, então pare de duvidar tanto de si mesmo!",
  ui_story_5081_50810802_57_dialog_content = "Não acredito que haja um único Aurorian em Astra que seja pior do que eu lutando contra Eclipsitas.",
  ui_story_5081_50810802_58_dialog_content = "Mas isso significa que minha existência não tem valor?",
  ui_story_5081_50810802_59_dialog_content = "N-Não... Não foi isso que eu quis dizer! É só que...",
  ui_story_5081_50810802_60_dialog_content = "Esse oficial de inteligência fez muitos bons pontos também... Eu não deveria ter questionado ele dessa maneira.",
  ui_story_5081_50810802_61_dialog_content = "Mas sabe... Eu estou realmente meio animado para ver o futuro sobre o qual ele falou...",
  ui_story_5081_50810802_62_dialog_content = "Um mundo livre da ameaça dos Eclipsitas... É difícil imaginar algo tão maravilhoso.",
  ui_story_5081_50810802_63_dialog_content = "Se esse dia chegar, talvez o Exercício Militar Conjunto se transforme na maior convenção de jogos de Astra!",
  ui_story_5081_50810802_64_dialog_content = "Aposto que você ficaria tão legal em pé na plataforma do vencedor e segurando os troféus do primeiro lugar para cada jogo único—",
  ui_story_5081_50810802_65_dialog_content = "Pare com isso! Eu nunca poderia subir lá para aceitar um troféu... Isso é coisa do Gronru, não minha!",
  ui_story_5081_50810802_66_dialog_content = "Mas até que o mundo finalmente se livre dos Eclipsitas...",
  ui_story_5081_50810802_67_dialog_content = "Eu posso querer jogar um jogo onde posso enfrentá-los com uma equipe de poderosos Aurorians...",
  ui_story_5081_50810802_68_dialog_content = "E, finalmente, derrote todos eles!",
  ui_story_5081_50810802_69_dialog_content = "Mesmo que um único videogame nunca pudesse capturar todas as lutas de Astra...",
  ui_story_5081_50810802_70_dialog_content = "Ainda quero vivenciar e entender essas histórias por mim mesmo!",
  ui_story_5081_50810802_71_dialog_content = "Você vai.",
  ui_story_5081_50810802_72_dialog_content = "Hã?",
  ui_story_5081_50810802_73_dialog_content = "Eu sei que você vai conseguir! E se não puder fazer isso sozinho, apenas peça ao Gronru para fazer mais jogos para você!",
  ui_story_5081_50810802_74_dialog_content = "Se ela incluir todos nós e nossas histórias, aposto que seria um dos melhores jogos de todos os tempos!",
  ui_story_5081_50810802_75_dialog_content = "Pedir para ela fazer mais jogos? Mas Gronru está passando por um momento tão difícil agora...",
  ui_story_5081_50810802_76_dialog_content = "B-Chefe! Venha rápido!",
  ui_story_5081_50810802_77_dialog_content = "Problema! Problema! Piu!",
  ui_story_5081_50810802_78_dialog_content = "Inacreditável... Isto é inacreditável!",
  ui_story_5081_50810802_79_dialog_content = "O que houve?",
  ui_story_5081_50810802_80_dialog_content = "O chefe final de todos os desafiantes acabou de aparecer!",
  ui_story_5081_50810802_81_dialog_content = "E com esses tentáculos, ela definitivamente parece a parte... Se você não for cuidadoso...",
  ui_story_5081_50810802_82_dialog_content = "A lenda do \"B\" será completamente arruinada! Chilro!",
  ui_story_5081_50810901_1_dialog_content = "I-Incrível...",
  ui_story_5081_50810901_2_dialog_content = "Ela está jogando cinco jogos ao mesmo tempo... Não, seis!",
  ui_story_5081_50810901_3_dialog_content = "E ela está absolutamente esmagando-os!",
  ui_story_5081_50810901_4_dialog_content = "Esse estilo de jogo é nada parecido com o que eu já vi antes! É como se ela fosse criada com um único propósito...",
  ui_story_5081_50810901_5_dialog_content = "<size=45>Uma arma definitiva construída apenas para destruir lendas!</size>",
  ui_story_5081_50810901_6_dialog_content = "Não, não...",
  ui_story_5081_50810901_7_dialog_content = "Ela não é uma arma suprema ou algo assim. Ela é apenas um tipo especial de Auroriana...",
  ui_story_5081_50810901_8_dialog_content = "...",
  ui_story_5081_50810901_9_dialog_content = "No. 33, o que te traz aqui? Você veio para jogar alguns jogos?",
  ui_story_5081_50810901_10_dialog_content = "... Celestita?",
  ui_story_5081_50810901_11_dialog_content = "Um momento, por favor. Explicarei minha presença assim que completar a tarefa em mãos.",
  ui_story_5081_50810901_12_dialog_content = "<color=#e8d9bb>Os tentáculos de No. 33 lentamente param, e os dados exibidos em seus olhos eventualmente desaparecem.</color>",
  ui_story_5081_50810901_13_dialog_content = "<color=#e8d9bb>As máquinas de arcade ao seu redor piscam com mensagens de vitória, e suas pontuações aparecem em todas as suas tabelas de classificação.</color>",
  ui_story_5081_50810901_14_dialog_content = "<color=#e8d9bb>No entanto, ainda há uma diferença clara entre as pontuações dela e as dos que estão no topo.</color>",
  ui_story_5081_50810901_15_dialog_content = "Agora que os jogos acabaram, permita-me explicar minhas razões para vir aqui.",
  ui_story_5081_50810901_16_dialog_content = "Meu nome é No. 33, um guardião das antigas ruínas do Norte.",
  ui_story_5081_50810901_17_dialog_content = "Chegou ao meu conhecimento que um cartucho de dados da antiga civilização foi descoberto e restaurado neste lugar. Como tal, solicitei permissão ao Tribunal do Norte para viajar até aqui.",
  ui_story_5081_50810901_18_dialog_content = "Meu objetivo original era comprá-lo e analisar seu conteúdo.",
  ui_story_5081_50810901_19_dialog_content = "Ao chegar neste fliperama, no entanto, rapidamente percebi que todos esses jogos foram criados restaurando dados antigos...",
  ui_story_5081_50810901_20_dialog_content = "E que seus arquivos ainda eram dignos de análise.",
  ui_story_5081_50810901_21_dialog_content = "Por esse motivo, comecei imediatamente a conduzir pesquisas sobre eles. Estou preparado para oferecer pagamento pelos dados que coletei e quaisquer custos que possa ter incorrido.",
  ui_story_5081_50810901_22_dialog_content = "Th-Isso não será necessário. Esses jogos são feitos para serem jogados, e você já gastou fichas para jogá-los.",
  ui_story_5081_50810901_23_dialog_content = "Mas usar tentáculos para jogar vários jogos... Eu nunca vi nada parecido antes...",
  ui_story_5081_50810901_24_dialog_content = "Eles são fáceis de usar?",
  ui_story_5081_50810901_25_dialog_content = "Você se refere aos meus tentáculos? Eles fazem parte do sistema de guardião e me permitem gerenciar várias estruturas dentro das ruínas.",
  ui_story_5081_50810901_26_dialog_content = "Eles não são particularmente úteis para a vida cotidiana dos Aurorians, mas são de fato úteis ao executar ordens.",
  ui_story_5081_50810901_27_dialog_content = "E agora, percebo que eles também são bastante adequados para jogar videogames. Comparado com outros jogadores no fliperama...",
  ui_story_5081_50810901_28_dialog_content = "A capacidade de resposta, precisão e sensibilidade dos meus tentáculos me oferecem vantagens claras, mas o conhecimento íntimo dos dados do jogo também é bastante essencial.",
  ui_story_5081_50810901_29_dialog_content = "Essa é a razão pela qual você não conseguiu garantir a pontuação mais alta agora, No. 33?",
  ui_story_5081_50810901_30_dialog_content = "Ou é apenas porque esta foi a sua primeira vez jogando? Talvez você consiga liderar os rankings uma vez que pegue o jeito desses jogos!",
  ui_story_5081_50810901_31_dialog_content = "Devo adquirir mais experiência antes de chegar a qualquer conclusão definitiva.",
  ui_story_5081_50810901_32_dialog_content = "Quanto mais complexo o jogo, mais difícil se torna, mas também contém ainda mais caminhos ótimos para a conclusão.",
  ui_story_5081_50810901_33_dialog_content = "Quanto às pontuações nestas tabelas de classificação, não tenho como analisá-las neste momento.",
  ui_story_5081_50810901_34_dialog_content = "Só posso olhar para eles com respeito.",
  ui_story_5081_50810901_35_dialog_content = "Isso é perfeito! Então... Isso significa que você ainda precisa coletar mais dados do jogo, certo?",
  ui_story_5081_50810901_36_dialog_content = "Por que não jogar conosco e ganhar ainda mais experiência?",
  ui_story_5081_50810901_37_dialog_content = "Claro. Minhas novas ordens são observar os Aurorianos modernos em suas vidas cotidianas...",
  ui_story_5081_50810901_38_dialog_content = "Assim como garantir a segurança de seu futuro usando qualquer dado útil da civilização antiga.",
  ui_story_5081_50810901_39_dialog_content = "Aliar-me aos jogadores presentes seria uma maneira eficiente de cumprir minhas ordens.",
  ui_story_5081_50810901_40_dialog_content = "Posso começar a qualquer momento.",
  ui_story_5081_50810901_41_dialog_content = "Vamos, galera! Vamos nos divertir!",
  ui_story_5081_50810902_1_dialog_content = "<color=#e8d9bb>Com o planejamento de Batia, todos começam a jogar jogos contra No. 33.</color>",
  ui_story_5081_50810902_2_dialog_content = "<color=#e8d9bb>Com exceção de Odi, que consegue ganhar uma ou duas partidas, No. 33 derrota todos de forma impressionante.</color>",
  ui_story_5081_50810902_3_dialog_content = "<color=#e8d9bb>Batia, no entanto, mantém seu título como a lendária e invicta \"B.\"</color>",
  ui_story_5081_50810902_4_dialog_content = "Obrigado a todos. Os dados e observações que coletei hoje serão muito valiosos para minha pesquisa.",
  ui_story_5081_50810902_5_dialog_content = "Desculpe-me, mas posso pegar emprestado alguns jogos que exigem uma análise demorada para serem concluídos?",
  ui_story_5081_50810902_6_dialog_content = "Acredito que os dados ocultos nesses jogos serão de grande benefício para o futuro de todos os Aurorianos.",
  ui_story_5081_50810902_7_dialog_content = "Analisarei eles ao máximo e disponibilizarei minhas descobertas para todos.",
  ui_story_5081_50810902_8_dialog_content = "Claro! Venha comigo, e eu te levarei para ver minha coleção! Pegue o que você achar que vai ajudar!",
  ui_story_5081_50810902_9_dialog_content = "Escolherei com sabedoria. Obrigado pela sua generosidade.",
  ui_story_5081_50810902_10_dialog_content = "Acho que nunca te vi tão animada, Batia...",
  ui_story_5081_50810902_11_dialog_content = "Oh, r-realmente? É tão óbvio?",
  ui_story_5081_50810902_12_dialog_content = "Sim, mas eu me sinto exatamente da mesma forma que você agora.",
  ui_story_5081_50810902_13_dialog_content = "No final do dia, os videogames são uma ótima maneira de reunir as pessoas e animá-las, huh?",
  ui_story_5081_50810902_14_dialog_content = "Quem sabe? Uma vez que No. 33 analise os dados desses jogos, talvez suas descobertas ajudem a indústria de jogos a se desenvolver ainda mais.",
  ui_story_5081_50810902_15_dialog_content = "Ela até disse que o futuro de todos os Aurorianos poderia se beneficiar de seus jogos... Isso é bastante empolgante, não é?",
  ui_story_5081_50810902_16_dialog_content = "Você realmente gosta de videogames, PlayerName!",
  ui_story_5081_50810902_17_dialog_content = "Avançar jogos e torná-los mais acessíveis ao mundo... Essa é a melhor coisa que eu poderia pedir.",
  ui_story_5081_50810902_18_dialog_content = "Mal posso esperar para ver o que ela encontra...",
  ui_story_5081_50810902_19_dialog_content = "Fiz minha seleção. Quando os resultados da minha pesquisa estiverem claros, irei notificá-la o mais rápido possível, senhorita.",
  ui_story_5081_50810902_20_dialog_content = "B-Boa sorte!",
  ui_story_5081_50810902_21_dialog_content = "Preciso ir agora. Adeus.",
  ui_story_5081_50810902_22_dialog_content = "N-Na verdade... Posso te perguntar algo antes de você ir?",
  ui_story_5081_50810902_23_dialog_content = "Por todos os meios.",
  ui_story_5081_50810902_24_dialog_content = "Tem a ver... com as pessoas que fizeram esses jogos - a civilização perdida de eras passadas...",
  ui_story_5081_50810902_25_dialog_content = "Você pode me dizer que tipo de mundo eles viviam?",
  ui_story_5081_50810902_26_dialog_content = "Havia... muitos jogos no mundo deles? Jogos que foram desenvolvidos com mais significados além de apenas entretenimento?",
  ui_story_5081_50810902_27_dialog_content = "...",
  ui_story_5081_50810902_28_dialog_content = "Era um mundo muito avançado, mas também muito aterrorizante.",
  ui_story_5081_50810902_29_dialog_content = "\"Significados,\" você pergunta?",
  ui_story_5081_50810902_30_dialog_content = "Desculpe, mas analisar esses dados não me fornecerá a resposta que você procura.",
  ui_story_5081_50810902_31_dialog_content = "Neste mundo, o significado de algo não é uma constante imutável.",
  ui_story_5081_50810902_32_dialog_content = "Para aqueles que estão com frio e fome, tudo que está fora de comida e roupa é sem sentido.",
  ui_story_5081_50810902_33_dialog_content = "Para aqueles com almas vazias, posses materiais abundantes também são sem sentido.",
  ui_story_5081_50810902_34_dialog_content = "Mas neste lugar, os videogames são uma fonte de diversão, foco e união. Isso os torna significativos.",
  ui_story_5081_50810902_35_dialog_content = "No que diz respeito às minhas ordens, a tecnologia que beneficia os habitantes locais também é significativa.",
  ui_story_5081_50810902_36_dialog_content = "Os videogames não são exceção.",
  ui_story_5081_50810902_37_dialog_content = "Então... Você acha que eles são significativos?",
  ui_story_5081_50810902_38_dialog_content = "Sim. <color=#FFB400>Na minha opinião</color>, eles são significativos.",
  ui_story_5081_50810902_39_dialog_content = "E eu acredito... você também deve ver o significado especial deles <color=#FFB400>na sua opinião</color>.",
  ui_story_5081_50810902_40_dialog_content = "Ah...",
  ui_story_5081_50810902_41_dialog_content = "Sim, também acho!",
  ui_story_5081_50810902_42_dialog_content = "Os jogadores são os que dão significado aos jogos, não os próprios jogos.",
  ui_story_5081_50810902_43_dialog_content = "A coisa mais importante são as pessoas que conseguem encontrar significado nos videogames!",
  ui_story_5081_50810902_44_dialog_content = "Seja aqueles que colecionam jogos, acompanham as últimas tendências, ou compram mercadorias de jogos...",
  ui_story_5081_50810902_45_dialog_content = "Você até conseguiu convencer Anatoli sobre a importância dos videogames!",
  ui_story_5081_50810902_46_dialog_content = "Os videogames não distinguem entre rico e pobre ou bom e mal. Qualquer um pode encontrar significado ao jogá-los!",
  ui_story_5081_50810902_47_dialog_content = "PlayerName...",
  ui_story_5081_50810902_48_dialog_content = "Se você algum dia encontrar alguém que descreve as vidas ou paixões de outras pessoas como <color=#FFB400>sem sentido</color>...",
  ui_story_5081_50810902_49_dialog_content = "Não deixe nada do que eles dizem te afetar! Pessoas assim não se importam com o significado ou valor de nada!",
  ui_story_5081_50810902_50_dialog_content = "Realmente admiro seu amor por videogames, Batia. Só gostaria que você não duvidasse tanto de si mesmo.",
  ui_story_5081_50810902_51_dialog_content = "Por favor, continue compartilhando seu amor por jogos com outras pessoas. Faça do seu arcade um refúgio seguro para jogadores de todo o mundo!",
  ui_story_5081_50810902_52_dialog_content = "Ah... Ahhhh! Tá bom, eu já entendi! Não precisa exagerar, PlayerName!",
  ui_story_5081_50810902_53_dialog_content = "Haha, desculpe! Eu estava apenas um pouco preocupado com você, então não pude evitar de falar o que pensava...",
  ui_story_5081_50810902_54_dialog_content = "Obrigado. Acho que todos que gostam de videogames são assim.",
  ui_story_5081_50810902_55_dialog_content = "Gronru uma vez me disse algo assim também...",
  ui_story_5081_50810902_56_dialog_content = "Entendi... Você está realmente bem próximo dela, não está?",
  ui_story_5081_50810902_57_dialog_content = "Sim... Hum, PlayerName? Depois que eu fechar o fliperama do dia, eu tenho algumas coisas para te dizer...",
  ui_story_5081_50811001_1_dialog_content = "Hora de fechar! Todos fora! Piu!",
  ui_story_5081_50811001_2_dialog_content = "Eu sei disso, agora cale a boca!",
  ui_story_5081_50811001_3_dialog_content = "Tsk! Estou começando a me sentir um pouco inquieto. Uma bola de sombras acabou de passar pela porta?",
  ui_story_5081_50811001_4_dialog_content = "Ou foi uma bola de chamas?",
  ui_story_5081_50811001_5_dialog_content = "<color=#e8d9bb>À medida que o sol se põe no horizonte, os jogadores retornam lentamente para suas casas em ignorância feliz.</color>",
  ui_story_5081_50811001_6_dialog_content = "<color=#e8d9bb>Enquanto isso, uma silhueta ameaçadora se infiltra silenciosamente neste lugar de alegria e diversão.</color>",
  ui_story_5081_50811001_7_dialog_content = "<color=#e8d9bb>Você consegue sentir o calor perturbador e ilusório da presença dela?</color>",
  ui_story_5081_50811001_8_dialog_content = "A atmosfera aqui de repente ficou mais escura... Hã? Quem deixou este jogo de terror ligado aqui fora?",
  ui_story_5081_50811001_9_dialog_content = "Ah, desculpe, provavelmente fui eu...",
  ui_story_5081_50811001_10_dialog_content = "Estava procurando um jogo para jogar no meu poleiro esta noite, então eu devo ter deixado alguns ligados.",
  ui_story_5081_50811001_11_dialog_content = "Você não tem medo deste jogo, tem PlayerName?",
  ui_story_5081_50811001_12_dialog_content = "Não realmente, eu só me assustei um pouco quando as linhas começaram a tocar de repente.",
  ui_story_5081_50811001_13_dialog_content = "Uh, o que você quis dizer com seu \"poleiro\"?",
  ui_story_5081_50811001_14_dialog_content = "Interessado? Você está livre para conferir se quiser.",
  ui_story_5081_50811001_15_dialog_content = "Estar cercado por toneladas de jogos e luzes piscantes à noite me faz sentir tão seguro e aquecido...",
  ui_story_5081_50811001_16_dialog_content = "Também tenho lanches e bebidas suficientes para durar um mês inteiro!",
  ui_story_5081_50811001_17_dialog_content = "Heeheehee...",
  ui_story_5081_50811001_18_dialog_content = "<color=#e8d9bb>Sob o manto da noite, você cai no desespero do nada.</color>",
  ui_story_5081_50811001_19_dialog_content = "<color=#e8d9bb>O uivo das almas torturadas além do túmulo ecoa por todos os cantos da escuridão.</color>",
  ui_story_5081_50811001_20_dialog_content = "Ah...",
  ui_story_5081_50811001_21_dialog_content = "Você ouviu isso? Os efeitos sonoros deste jogo são realmente realistas...",
  ui_story_5081_50811001_22_dialog_content = "Th-Isso não veio do meu jogo!",
  ui_story_5081_50811001_23_dialog_content = "E-Então o que foi?",
  ui_story_5081_50811001_24_dialog_content = "Não me diga que foi...",
  ui_story_5081_50811001_25_dialog_content = "Ah...",
  ui_story_5081_50811001_26_dialog_content = "Acho que vem de lá!",
  ui_story_5081_50811001_27_dialog_content = "M-Mas é aí que está o meu poleiro!",
  ui_story_5081_50811001_28_dialog_content = "Ei, espere!",
  ui_story_5081_50811001_29_dialog_content = "Ahhhhhh?",
  ui_story_5081_50811001_30_dialog_content = "Ahhhhhh!",
  ui_story_5081_50811001_31_dialog_content = "Um-Um fantasma! Há um fantasma assombrando meu poleiro!",
  ui_story_5081_50811001_32_dialog_content = "Ahhhh! PlayerName! Odi! Sork! Bekk! Alguém me ajude!",
  ui_story_5081_50811001_33_dialog_content = "Eu nunca mais quero jogar outro jogo assustador!",
  ui_story_5081_50811001_34_dialog_content = "Não se preocupe, estou chegando!",
  ui_story_5081_50811001_35_dialog_content = "Hã? Uriel... É você?",
  ui_story_5081_50811001_36_dialog_content = "Crunch! Munch, munch... Glup, glup, glup...",
  ui_story_5081_50811001_37_dialog_content = "Ah. Os lanches não são nada especiais, mas essas bebidas são muito boas...",
  ui_story_5081_50811001_38_dialog_content = "Ei! Não derrame nada nas minhas máquinas de jogo! Ahhh...",
  ui_story_5081_50811001_39_dialog_content = "Por favor, eu não sou tão desajeitado assim. Eu só estou... ajudando você a limpá-los, só isso.",
  ui_story_5081_50811001_40_dialog_content = "Tais criaturas vis e imundas... com vidas tão sem sentido.",
  ui_story_5081_50811001_41_dialog_content = "Suma, suma, suma, suma—",
  ui_story_5081_50811001_42_dialog_content = "Desapareça junto comigo, outra existência sem sentido...",
  ui_story_5081_50811001_43_dialog_content = "E-Ela está tentando se livrar de mim na vida real? O desafio é apenas para videogames!",
  ui_story_5081_50811001_44_dialog_content = "... Tenho quase certeza que não é isso que ela quer dizer...",
  ui_story_5081_50811001_45_dialog_content = "Acontece que ela é Uriel... uma dos Quatro Anjos de Lumópolis!",
  ui_story_5081_50811001_46_dialog_content = "Uma pessoa famosa de Lumópolis? O-O que ela está fazendo aqui?",
  ui_story_5081_50811001_47_dialog_content = "Ahhhh! Ela está espalhando migalhas por todo o meu teclado!",
  ui_story_5081_50811001_48_dialog_content = "Devo destruir este mundo... Devo queimá-lo por completo...",
  ui_story_5081_50811001_49_dialog_content = "Você tem alguma ideia de quanto tempo estive preso ao lado dessas existências amaldiçoadas?",
  ui_story_5081_50811001_50_dialog_content = "Do anoitecer ao amanhecer e de volta ao anoitecer, o calor nunca para de aumentar, e eu nunca paro de arrastar essas almas miseráveis para o inferno...",
  ui_story_5081_50811001_51_dialog_content = "Foi tão doloroso no começo, mas agora... Não sinto nada, então deixe tudo queimar...",
  ui_story_5081_50811001_52_dialog_content = "Venha comigo e desça ao limbo do esquecimento...",
  ui_story_5081_50811001_53_dialog_content = "Está começando a ficar realmente quente aqui!",
  ui_story_5081_50811001_54_dialog_content = "Uriel, você precisa se acalmar!",
  ui_story_5081_50811001_55_dialog_content = "Minha máquina de jogo... Ela vai queimá-la até virar cinzas! Meu arquivo salvo... não meu arquivo salvo!",
  ui_story_5081_50811001_56_dialog_content = "Não há tempo... Vamos ter que esfriá-la e tirar tudo daqui!",
  ui_story_5081_50811001_57_dialog_content = "Odi! Sork! Bekk! Dê-nos uma mão!",
  ui_story_5081_50811002_1_dialog_content = "É tudo isso? Ufa, acho que conseguimos salvar a maior parte...",
  ui_story_5081_50811002_2_dialog_content = "Precisamos retirar mais alguma coisa da sala?",
  ui_story_5081_50811002_3_dialog_content = "Não, acho que estamos bem... Obrigado, todos...",
  ui_story_5081_50811002_4_dialog_content = "Quanto àquela máquina de jogo... apenas deixe-a ficar com isso. Não importa se ela queimá-la...",
  ui_story_5081_50811002_5_dialog_content = "Embora Uriel pareça realmente deprimida na maior parte do tempo, eu me pergunto o que aconteceu com ela?",
  ui_story_5081_50811002_6_dialog_content = "Talvez eu deva pedir ao Carleen para resolver isso. Afinal, Uriel ainda tem um pouco de medo de seu capitão.",
  ui_story_5081_50811002_7_dialog_content = "Carleen pode até ser capaz de esfriá-la completamente...",
  ui_story_5081_50811002_8_dialog_content = "... Que estranho.",
  ui_story_5081_50811002_9_dialog_content = "O que é estranho?",
  ui_story_5081_50811002_10_dialog_content = "Ela é uma das Quatro Anjos, o que significa... ela provavelmente eliminou mais Eclipsitas do que qualquer outro Aurorian, certo?",
  ui_story_5081_50811002_11_dialog_content = "Sim, eu suponho...",
  ui_story_5081_50811002_12_dialog_content = "E ainda assim, aqui está ela, passando o tempo em um fliperama e tentando ao máximo vencer os Eclipsitas em um videogame...",
  ui_story_5081_50811002_13_dialog_content = "Não deveria uma famosa guerreira de Lumopolis ter coisas mais nobres para fazer com seu tempo?",
  ui_story_5081_50811002_14_dialog_content = "Ela definitivamente faz... Espere, deixe-me reformular isso.",
  ui_story_5081_50811002_15_dialog_content = "Quando você derrota Eclipsitas em um videogame, geralmente recebe algum tipo de recompensa, ou ele diz que você venceu o nível. Isso nem sempre acontece na vida real.",
  ui_story_5081_50811002_16_dialog_content = "Para um Angel deprimido, talvez seja isso que ela quer?",
  ui_story_5081_50811002_17_dialog_content = "Entendi... Acho que todos têm seus próprios motivos para querer jogar, né?",
  ui_story_5081_50811002_18_dialog_content = "Tenho certeza que há uma razão mais profunda por trás do comportamento de Uriel, mas isso não é desculpa para te colocar nessa situação.",
  ui_story_5081_50811002_19_dialog_content = "Vou apenas avisar Carleen—",
  ui_story_5081_50811002_20_dialog_content = "Desculpe, todos!",
  ui_story_5081_50811002_21_dialog_content = "Não consigo pedir desculpas o suficiente por todo o problema que causamos a você!",
  ui_story_5081_50811002_22_dialog_content = "Huh? Você também está aqui, PlayerName? Ótimo! Isso facilita muito as coisas!",
  ui_story_5081_50811002_23_dialog_content = "O que no mundo...",
  ui_story_5081_50811002_24_dialog_content = "Houve muito mais Eclipsitas na área do que o habitual.",
  ui_story_5081_50811002_25_dialog_content = "Uriel foi enviado para exterminá-los e lutou contra eles sem parar por dias a fio...",
  ui_story_5081_50811002_26_dialog_content = "Ela é uma trabalhadora tão esforçada! Quando finalmente saiu, tudo o que ela tinha a dizer foi...",
  ui_story_5081_50811002_27_dialog_content = "\"Doce destruição... Preciso ir a algum lugar onde eu possa realmente limpar os Eclipsitas...\" E então ela simplesmente desapareceu!",
  ui_story_5081_50811002_28_dialog_content = "Tive que perguntar por toda Lumopolis e Umbraton antes de descobrir sobre este lugar...",
  ui_story_5081_50811002_29_dialog_content = "Um lugar onde ela poderia realmente limpar os Eclipsitas... Ela estava falando sobre os jogos neste fliperama! Ah, estou tão ciumento!",
  ui_story_5081_50811002_30_dialog_content = "Ciúmes?",
  ui_story_5081_50811002_31_dialog_content = "Lumópolis também tem estado realmente ocupada ultimamente?",
  ui_story_5081_50811002_32_dialog_content = "Sim! Não há dias de folga quando seu trabalho é garantir a segurança de todos, afinal...",
  ui_story_5081_50811002_33_dialog_content = "Mas parece que Uriel causou alguns problemas para vocês, hein?",
  ui_story_5081_50811002_34_dialog_content = "Alguém se machucou? Se sim, Lumópolis assumirá a responsabilidade por todos os danos!",
  ui_story_5081_50811002_35_dialog_content = "Então não há necessidade de fazer nenhum relatório desagradável sobre o que aconteceu aqui... Certo?",
  ui_story_5081_50811002_36_dialog_content = "Deixe a restauração da loja comigo!",
  ui_story_5081_50811002_37_dialog_content = "Hah—",
  ui_story_5081_50811002_38_dialog_content = "Lá vamos nós-",
  ui_story_5081_50811002_39_dialog_content = "Ah—",
  ui_story_5081_50811002_40_dialog_content = "E agora é a hora... de lidar com a parte mais irritante!",
  ui_story_5081_50811002_41_dialog_content = "Hã? Ah, é só você, Raphael...",
  ui_story_5081_50811002_42_dialog_content = "Eu me recuso a voltar com alguém que gosta de fazer hora extra, então apenas—",
  ui_story_5081_50811002_43_dialog_content = "Do que você está falando, Uriel? Estou aqui para ajudar a todos, não porque estou no relógio!",
  ui_story_5081_50811002_44_dialog_content = "Para impedir que você perturbe o público, não tenho escolha a não ser arrastá-lo de volta para Lumópolis! Divertido, certo?",
  ui_story_5081_50811002_45_dialog_content = "Mas eu não terminei aqui... Eu ainda preciso incendiar todo o Astra...",
  ui_story_5081_50811002_46_dialog_content = "Até logo, PlayerName! Ah, e obrigado por ser tão compreensiva, senhorita!",
  ui_story_5081_50811002_47_dialog_content = "Sei que causamos muitos problemas para você, mas deixe-me dizer que você tem um fliperama realmente maravilhoso.",
  ui_story_5081_50811002_48_dialog_content = "Mesmo um Auroriano como Uriel, que acha que tudo é sem sentido, adora absolutamente este lugar!",
  ui_story_5081_50811002_49_dialog_content = "Com certeza voltarei para jogar algum dia também! Tchau-tchau!",
  ui_story_5081_50811101_1_dialog_content = "... Eles finalmente se foram? Apresse-se e tranque a porta, Sork!",
  ui_story_5081_50811101_2_dialog_content = "Não acredito que duas pessoas famosas apareceram uma após a outra. Quem é o próximo, o próprio Senhor da Cidade?",
  ui_story_5081_50811101_3_dialog_content = "... Provavelmente não.",
  ui_story_5081_50811101_4_dialog_content = "Então talvez Queen Bethlehem? Isso parece um pouco mais realista, certo?",
  ui_story_5081_50811101_5_dialog_content = "... Eu não acho que esse é o ponto.",
  ui_story_5081_50811101_6_dialog_content = "Não me importa quem apareça, contanto que não seja o Sinsa. Se ele descobrir que fui enganado para trabalhar aqui de graça...",
  ui_story_5081_50811101_7_dialog_content = "Vou ser motivo de chacota da Rediesel Wrench por anos a fio!",
  ui_story_5081_50811101_8_dialog_content = "Décadas, até! Piu!",
  ui_story_5081_50811101_9_dialog_content = "Dê um tempo, pessoal! Vocês estão assustando a Batia!",
  ui_story_5081_50811101_10_dialog_content = "Ai...",
  ui_story_5081_50811101_11_dialog_content = "Eles me agradeceram antes de partir.",
  ui_story_5081_50811101_12_dialog_content = "Hã?",
  ui_story_5081_50811101_13_dialog_content = "Uriel... Ela veio ao meu fliperama por vontade própria?",
  ui_story_5081_50811101_14_dialog_content = "Parece que sim! Eu não fazia ideia de que ela ia a fliperamas para desestressar...",
  ui_story_5081_50811101_15_dialog_content = "Isso significa que sua loja está fazendo uma contribuição significativa na luta contra Eclipsitas, Batia!",
  ui_story_5081_50811101_16_dialog_content = "Eu não iria tão longe. Quanto a Uriel...",
  ui_story_5081_50811101_17_dialog_content = "Se pudermos nos encontrar em circunstâncias normais, eu poderia recomendar alguns jogos apenas para ela.",
  ui_story_5081_50811101_18_dialog_content = "Mas hoje... Eu...",
  ui_story_5081_50811101_19_dialog_content = "E quanto a hoje?",
  ui_story_5081_50811101_20_dialog_content = "Não acho que já vi tantos clientes loucos em um único dia!",
  ui_story_5081_50811101_21_dialog_content = "Eu sabia que essa pré-venda iria atrair muita atenção de todo o Astra...",
  ui_story_5081_50811101_22_dialog_content = "Mas eu nunca esperava ver tantos clientes estranhos e poderosos! Algo não está certo nisso!",
  ui_story_5081_50811101_23_dialog_content = "Então você finalmente percebeu isso - mas agora é tarde demais!",
  ui_story_5081_50811101_24_dialog_content = "?",
  ui_story_5081_50811101_25_dialog_content = "Permiti que os rumores em torno da lendária \"B\" e seu fliperama se proliferassem rapidamente através da minha rede de inteligência...",
  ui_story_5081_50811101_26_dialog_content = "E agora, é hora de eu colher os frutos do meu trabalho.",
  ui_story_5081_50811101_27_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5081_50811101_28_dialog_content = "Vocês estão todos cercados, então ninguém se mova.",
  ui_story_5081_50811101_29_dialog_content = "?",
  ui_story_5081_50811101_30_dialog_content = "A verdade muitas vezes está escondida sob camadas de escuridão, mas através da minha investigação, tudo será trazido à luz.",
  ui_story_5081_50811101_31_dialog_content = "Após uma longa investigação, finalmente descobri a verdade por trás desta loja e seu verdadeiro dono.",
  ui_story_5081_50811101_32_dialog_content = "Eu já solicitei a cooperação tanto do Senhor Sombrio quanto do xerife de Lumópolis—",
  ui_story_5081_50811101_33_dialog_content = "Pela suspeita de posse de informações classificadas, declaro aqui que a Hidden Fangs deve fechar suas portas até nova investigação!",
  ui_story_5081_50811101_34_dialog_content = "Qu-Quem você pensa que é? O que te dá o direito de fazer isso?",
  ui_story_5081_50811101_35_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5081_50811101_36_dialog_content = "Aqui está o mandado oficial, assinado por cada um dos órgãos governamentais envolvidos na investigação. Preciso dizer mais?",
  ui_story_5081_50811101_37_dialog_content = "O-Objeção! Eu nunca fiz nada disso... Eu juro...",
  ui_story_5081_50811101_38_dialog_content = "Sua objeção não faz diferença. Afinal, <color=#FFB400>palavras</color> não significam nada neste lugar, não é mesmo?",
  ui_story_5081_50811101_39_dialog_content = "Apenas um desafio servirá!",
  ui_story_5081_50811101_40_dialog_content = "Agora só espere um segundo!",
  ui_story_5081_50811101_41_dialog_content = "Eu sei que você tem um mandado oficialmente assinado, e eu sei que você deve ter trabalhado muito duro nessas linhas agora...",
  ui_story_5081_50811101_42_dialog_content = "Mas o que diabos você está fazendo, Oficial de Inteligência Yin—",
  ui_story_5081_50811101_43_dialog_content = "Esse não é o meu nome! Eu sou o desafiante conhecido como \"Y\"!",
  ui_story_5081_50811101_44_dialog_content = "E consegui entrar neste fliperama pouco antes de fechar as portas!",
  ui_story_5081_50811101_45_dialog_content = "O invicto \"B\" é o mestre deste lugar, sim? Você não recusaria meu desafio, recusaria?",
  ui_story_5081_50811101_46_dialog_content = "...",
  ui_story_5081_50811101_47_dialog_content = "Não se preocupe, Batia, eu vou falar com ela. Isso é parte da minha missão, afinal de contas...",
  ui_story_5081_50811101_48_dialog_content = "Na verdade, ouvi dizer que a Federação Illumina está preparada para mobilizar toda a sua rede de inteligência continental para caçá-la.",
  ui_story_5081_50811101_49_dialog_content = "Para ser franco, não. Na verdade, pode-se dizer que temos um pouco de conflito entre nós.",
  ui_story_5081_50811101_50_dialog_content = "<size=30>Ela tem se esforçado tanto ultimamente, talvez mais do que o necessário.</size>",
  ui_story_5081_50811101_51_dialog_content = "... Mas não se preocupe. Garantirei que este assunto chegue a uma conclusão satisfatória.",
  ui_story_5081_50811101_52_dialog_content = "Então eles estavam falando sobre você todo esse tempo, Yingel!",
  ui_story_5081_50811101_53_dialog_content = "Não é de se admirar que Beretta disse que te viu lá fora mais cedo hoje... E o que há com esses óculos de sol?",
  ui_story_5081_50811101_54_dialog_content = "Aquele olhar que senti quando apareci pela primeira vez não era da Batia... Era você!",
  ui_story_5081_50811101_55_dialog_content = "Então... O que eles vão fazer com Gronru quando a encontrarem? Eles não vão puni-la, vão?",
  ui_story_5081_50811101_56_dialog_content = "Quem sabe? Afinal, essa não é minha área de especialização.",
  ui_story_5081_50811101_57_dialog_content = "(... A Federação Illumina enviou Yingel, o melhor de seus melhores soldados, para caçar Gronru!)",
  ui_story_5081_50811101_X57_dialog_content = "(Não está preocupado com isso? Eles realmente não vão te arrastar de volta à força, vão?!)",
  ui_story_5081_50811101_58_dialog_content = "Qual é o problema, \"B\"? Se isso te incomoda tanto, então apenas aceite meu desafio!",
  ui_story_5081_50811101_59_dialog_content = "Eu aceito!",
  ui_story_5081_50811101_60_dialog_content = "Como proprietário deste fliperama, tenho que defendê-lo!",
  ui_story_5081_50811101_61_dialog_content = "Espere... Não me diga que vocês dois vão—",
  ui_story_5081_50811101_62_dialog_content = "É hora do duelo!",
  ui_story_5081_50811102_1_dialog_content = "Isso é realmente tudo que você tem? Eu esperava mais do lendário \"B.\"",
  ui_story_5081_50811102_2_dialog_content = "Sua vida é como uma vela ao vento...",
  ui_story_5081_50811102_3_dialog_content = "É isso que você acha?",
  ui_story_5081_50811102_4_dialog_content = "Estive preparando este movimento de matar em um turno só para você! Está pronto para isso?",
  ui_story_5081_50811102_5_dialog_content = "O quê...",
  ui_story_5081_50811102_6_dialog_content = "<color=#e8d9bb>Uau, uau, uau—boom!</color>",
  ui_story_5081_50811102_7_dialog_content = "<size=45>Não... Nãoooo!</size>",
  ui_story_5081_50811102_8_dialog_content = "O HP de Yingel foi direto para zero...",
  ui_story_5081_50811102_9_dialog_content = "Sério... Eu nem consegui comentar a partida!",
  ui_story_5081_50811102_10_dialog_content = "Esses dois continuavam explicando seus movimentos a cada turno, como algum jogo de cartas chato!",
  ui_story_5081_50811102_11_dialog_content = "Hehe, esse mandado provavelmente não vale nada agora!",
  ui_story_5081_50811102_12_dialog_content = "Espere, não faça parecer que vivemos em um mundo onde ganhar um jogo resolve tudo!",
  ui_story_5081_50811102_13_dialog_content = "Como isso pode ser? Minha estratégia era perfeita! Eu tenho te observado neste lugar por tanto tempo...",
  ui_story_5081_50811102_14_dialog_content = "Seu estilo de jogo, seus hábitos e até mesmo suas batalhas contra todos esses desafiantes...",
  ui_story_5081_50811102_15_dialog_content = "Não... Ainda não acabou! Eu me recuso a aceitar a derrota!",
  ui_story_5081_50811102_16_dialog_content = "Melhor de três! Esta competição está apenas começando!",
  ui_story_5081_50811102_17_dialog_content = "Caramba... Yingel está realmente começando a soar como um vilão de desenho animado agora.",
  ui_story_5081_50811102_18_dialog_content = "Tudo bem por mim! Para proteger meu fliperama, vou te derrotar quantas vezes for necessário...",
  ui_story_5081_50811102_19_dialog_content = "Isso é o que PlayerName e os outros me ensinaram sobre ser o proprietário deste lugar!",
  ui_story_5081_50811102_20_dialog_content = "É hora do duelo!",
  ui_story_5081_50811102_21_dialog_content = "Pare com isso já-",
  ui_story_5081_50811102_22_dialog_content = "Perdoe a interrupção.",
  ui_story_5081_50811102_23_dialog_content = "Perdoe-me... por chegar tão tarde.",
  ui_story_5081_50811102_24_dialog_content = "O Oficial Yingel já está aqui, eu vejo. Por favor, me perdoe por não tê-la impedido mais cedo também.",
  ui_story_5081_50811102_25_dialog_content = "Tudo bem, você chegou bem na hora! Não é tarde demais para fazê-la desistir!",
  ui_story_5081_50811102_26_dialog_content = "Entendi.",
  ui_story_5081_50811102_27_dialog_content = "Oficial Yingel, há mais nesta missão do que originalmente pensávamos.",
  ui_story_5081_50811102_28_dialog_content = "A Oficial de Tecnologia Gronru é um membro importante do nosso departamento de pesquisa... mas ela também é uma pessoa muito temperamental.",
  ui_story_5081_50811102_29_dialog_content = "Já falei com o Oficial Migard e o Comitê.",
  ui_story_5081_50811102_30_dialog_content = "Em vez de tentar forçá-la a voltar, é melhor continuarmos com nossos próprios deveres.",
  ui_story_5081_50811102_31_dialog_content = "Por enquanto, por favor, deixe a investigação sobre o paradeiro do oficial Gronru para PlayerName. Quanto a nós—",
  ui_story_5081_50811102_32_dialog_content = "Já está pedindo reforços, hein?",
  ui_story_5081_50811102_33_dialog_content = "Apenas uma pequena interrupção, nada mais. Vamos continuar.",
  ui_story_5081_50811102_34_dialog_content = "Meu apelo à razão caiu completamente em ouvidos surdos!",
  ui_story_5081_50811102_35_dialog_content = "Parece que terei que atualizar minhas informações sobre o Oficial Yingel mais uma vez...",
  ui_story_5081_50811102_36_dialog_content = "Não, Anatoli, você definitivamente fez o seu melhor. É só que ela não é a Oficial de Inteligência Yingel agora - ela é a desafiante conhecida como \"Y\".",
  ui_story_5081_50811102_37_dialog_content = "Eu sei o que você realmente quer, \"Y\"! É por isso que proponho que trabalhemos juntos e completemos nossa missão!",
  ui_story_5081_50811102_38_dialog_content = "!",
  ui_story_5081_50811102_39_dialog_content = "Anatoli já me contou. Você tem se esforçado muito no trabalho, não tem?",
  ui_story_5081_50811102_40_dialog_content = "Quando os líderes da Federação Illumina te designaram para procurar por Gronru, foi porque eles queriam te dar uma tarefa menos estressante.",
  ui_story_5081_50811102_41_dialog_content = "Mas no final, eles decidiram colocar o trabalho em minhas mãos. Se você me perguntar, eles estão apenas complicando as coisas ainda mais!",
  ui_story_5081_50811102_42_dialog_content = "É por isso que eu prefiro evitar qualquer conflito desnecessário e trabalhar junto com você para terminar a missão!",
  ui_story_5081_50811102_43_dialog_content = "...",
  ui_story_5081_50811102_44_dialog_content = "Sei que você não quer se associar a ninguém, mas aposto que não quer que a Illumina fique sem um de seus melhores cientistas por mais tempo, certo?",
  ui_story_5081_50811102_45_dialog_content = "... E o que te faz tão certo de que encontraremos o Oficial Técnico se trabalharmos juntos?",
  ui_story_5081_50811102_46_dialog_content = "Toda a minha inteligência apontava para ela estar exatamente neste local.",
  ui_story_5081_50811102_47_dialog_content = "Ainda assim, não vi nenhum sinal dela, mesmo depois de todo esse tempo... Então pensei que, ao derrotar \"B\", eu poderia forçá-la a revelar o paradeiro de Gronru.",
  ui_story_5081_50811102_48_dialog_content = "Você é capaz de vencê-la, PlayerName? Se não, só posso contar comigo mesmo...",
  ui_story_5081_50811102_49_dialog_content = "Batia? O que você acha de Yingel como jogador?",
  ui_story_5081_50811102_50_dialog_content = "Você quer dizer ela? Eu a acho bastante interessante, sinceramente. Ela parece gostar muito de jogos também...",
  ui_story_5081_50811102_51_dialog_content = "E ela sabe como produzir algumas estratégias de alto nível, mesmo que se empolgue com elas... Acho que ela é uma ótima jogadora.",
  ui_story_5081_50811102_52_dialog_content = "C-Carregado? Essa é a sua opinião sobre mim?",
  ui_story_5081_50811102_53_dialog_content = "Não, isso não está certo... Você está falando sobre o desafiante conhecido como \"Y\", mas...",
  ui_story_5081_50811102_54_dialog_content = "Seu oponente agora é o Oficial de Inteligência Yingel. Por favor, não me coloque no mesmo nível que o último desafiante.",
  ui_story_5081_50811102_55_dialog_content = "Agora que Batia reconheceu as habilidades de Yingel, acho que é seguro para mim perguntar agora.",
  ui_story_5081_50811102_56_dialog_content = "Gronru está realmente se escondendo em algum lugar aqui, não está?",
  ui_story_5081_50811102_57_dialog_content = "Ah... Sinto muito, Gronru...",
  ui_story_5081_50811102_58_dialog_content = "Sim... Isso é a verdade.",
  ui_story_5081_50811102_59_dialog_content = "Contanto que sejam apenas vocês dois...",
  ui_story_5081_50811102_60_dialog_content = "Tenho certeza de que ela não se importará de se encontrar com você. Por aqui, por favor.",
  ui_story_5081_50811201_1_dialog_content = "Está um pouco escuro... Por favor, não fique muito para trás.",
  ui_story_5081_50811201_2_dialog_content = "Nunca esperava que houvesse um túnel embaixo deste lugar.",
  ui_story_5081_50811201_3_dialog_content = "Meus relatórios de inteligência não mencionaram nada sobre uma passagem secreta...",
  ui_story_5081_50811201_4_dialog_content = "Gronru teve muito trabalho para esconder este lugar. Faz todo sentido que você não soubesse sobre isso...",
  ui_story_5081_50811201_5_dialog_content = "Aqui estamos... Bem-vindo ao estúdio subterrâneo de Gronru.",
  ui_story_5081_50811201_6_dialog_content = "É o espaço privado dela onde ela pode analisar e restaurar jogos recentemente escavados de civilizações antigas.",
  ui_story_5081_50811201_7_dialog_content = "Um estúdio de videogame? Isso significa—",
  ui_story_5081_50811201_8_dialog_content = "Você estava certo em supor que Gronru estava aqui o tempo todo, PlayerName... mas por razões diferentes.",
  ui_story_5081_50811201_9_dialog_content = "Ela não veio aqui para comprar uma cópia do jogo de fantasia em pré-venda, porque ela é quem o restaurou em primeiro lugar.",
  ui_story_5081_50811201_10_dialog_content = "Em outras palavras...",
  ui_story_5081_50811201_11_dialog_content = "Ela é a verdadeira proprietária do Hidden Fangs, uma jogadora veterana que me apoia na administração deste fliperama.",
  ui_story_5081_50811201_12_dialog_content = "Então meus relatórios de inteligência estavam certos - esta realmente é a base secreta dela.",
  ui_story_5081_50811201_13_dialog_content = "Negligenciando seus deveres cruciais como oficial de Illumina para consertar videogames antigos...",
  ui_story_5081_50811201_14_dialog_content = "Não consigo pensar em algo mais egoísta a fazer! Illumina está no meio de—",
  ui_story_5081_50811201_15_dialog_content = "Meio de quê?",
  ui_story_5081_50811201_16_dialog_content = "Dê um descanso, Yingel. Se PlayerName não tivesse ganhado o favor de Batia, teria levado mais um ano para você encontrar este lugar!",
  ui_story_5081_50811201_17_dialog_content = "Ganhou meu favor? Ele nem chega perto de conseguir isso...",
  ui_story_5081_50811201_18_dialog_content = "Espere um minuto! Eu não sou um NPC ou algo assim... Por favor, não brinque assim, Gronru!",
  ui_story_5081_50811201_19_dialog_content = "É só que... Eles pareciam ter algo muito importante para te contar, então eu os trouxe aqui.",
  ui_story_5081_50811201_20_dialog_content = "Afinal de contas, eles são seus amigos e colegas de trabalho...",
  ui_story_5081_50811201_21_dialog_content = "Isso não significa nada! Eu não disse para você não deixar ninguém entrar aqui até as minhas férias acabarem?",
  ui_story_5081_50811201_22_dialog_content = "... M-Mas você disse \"com exceção de jogadores especialmente interessantes\"...",
  ui_story_5081_50811201_23_dialog_content = "\"Jogadores especialmente interessantes\"? Você não está falando sobre PlayerName e Yingel, certo?",
  ui_story_5081_50811201_24_dialog_content = "Você realmente acha que esses dois têm alguma chance contra o cérebro secreto por trás dos Hidden Fangs?",
  ui_story_5081_50811201_25_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5081_50811201_26_dialog_content = "Estamos sendo subestimados, PlayerName.",
  ui_story_5081_50811201_27_dialog_content = "Sim... Mas não viemos aqui para desafiar nenhum \"mestre secreto\" em primeiro lugar!",
  ui_story_5081_50811201_28_dialog_content = "Isso não importa mais. Não há como evitar essa batalha agora.",
  ui_story_5081_50811201_29_dialog_content = "Oficial de Tecnologia Gronru, você tem ideia de quanto caos sua ausência causou de volta em Illumina?",
  ui_story_5081_50811201_30_dialog_content = "Urgh, que dor...",
  ui_story_5081_50811201_31_dialog_content = "Não me diga que a mais recente arma anti-Eclipsite começou a funcionar mal novamente! Se for esse o caso, então use algo diferente!",
  ui_story_5081_50811201_32_dialog_content = "Minhas armas antigas podem fazer o trabalho muito bem!",
  ui_story_5081_50811201_33_dialog_content = "Ou o Comitê ainda não limpou depois de si mesmo?",
  ui_story_5081_50811201_34_dialog_content = "Sempre prolongando reuniões com seus discursos melodramáticos e cheios de autoimportância... Será que todos jogam o cérebro pela janela quando chegam ao topo ou algo assim?",
  ui_story_5081_50811201_35_dialog_content = "Ou talvez alguns cientistas discutam sobre quais projetos seguir e quais descartar novamente?",
  ui_story_5081_50811201_36_dialog_content = "Qualquer projeto que não passa na inspeção é descartado sem pensar duas vezes, mesmo que tudo o que eles precisem seja um pouco mais de apoio! Isso me irrita muito!",
  ui_story_5081_50811201_37_dialog_content = "O estado mental dela...",
  ui_story_5081_50811201_38_dialog_content = "É ainda pior do que o de Uriel, não é?",
  ui_story_5081_50811201_39_dialog_content = "Mesmo que você não possa assumir a responsabilidade por todas essas coisas, isso não é desculpa para abandonar seu posto sem aprovação—",
  ui_story_5081_50811201_40_dialog_content = "Quem diz que eu não consegui aprovação? Eu fiz meu pedido de férias! E eu mesmo o aprovei!",
  ui_story_5081_50811201_41_dialog_content = "Eu até coloquei avisos do meu tempo livre por todo o meu escritório! Não me diga que você não os viu!",
  ui_story_5081_50811201_42_dialog_content = "Urghhhh, chega! Não vou deixar nenhum de vocês estragar meu jogo de Longzhou Tilemaster—",
  ui_story_5081_50811201_43_dialog_content = "Se você quer que eu volte para o escritório, terá que arrastar meu corpo frio e morto até lá!",
  ui_story_5081_50811201_44_dialog_content = "Mestre de Azulejos de Longzhou? Acho que já ouvi falar desse jogo. É meio parecido com mahjong...",
  ui_story_5081_50811201_45_dialog_content = "Huh? Mas eu pensei que você estava terminando seu trabalho no jogo de fantasia, Gronru? Por que você apertou o botão de pausa nisso?",
  ui_story_5081_50811201_46_dialog_content = "Hmm... N-Não importa! Ninguém tem permissão para me perturbar agora, entendeu? Ninguém!",
  ui_story_5081_50811201_47_dialog_content = "Vamos começar o Jogo de Gronru!",
  ui_story_5081_50811201_48_dialog_content = "... Eu sabia que acabaria assim.",
  ui_story_5081_50811201_49_dialog_content = "Pegue, Peng-Peng!",
  ui_story_5081_50811201_50_dialog_content = "\"Peng-Peng\"? ... Ah, você quer dizer esse pequenino.",
  ui_story_5081_50811201_51_dialog_content = "Ainda não terminei! Deleite seus olhos com isso: Todos Verdes, Quatro Bênçãos e Nove Lanternas de Lótus!",
  ui_story_5081_50811201_52_dialog_content = "Ei... Espere só um segundo! Como eu vou conseguir acompanhar isso?",
  ui_story_5081_50811201_53_dialog_content = "Entrei no jogo! Mantenha-se firme, PlayerName!",
  ui_story_5081_50811201_54_dialog_content = "Também estou em posição!",
  ui_story_5081_50811201_55_dialog_content = "Sinceramente... Que tipo de pessoa nomeia Eclipsitas após um movimento no mahjong?",
  ui_story_5081_50811201_56_dialog_content = "Quem mais senão o grande Gronru, mestre de todas as formas de mahjong!",
  ui_story_5081_50811201_57_dialog_content = "Todos que ousarem me desafiar serão esmagados sob o peso colossal dos meus ladrilhos!",
  ui_story_5081_50811201_58_dialog_content = "Você veio me desafiar, sim? Então venham, todos os três! Eu vou mostrar a todos vocês—",
  ui_story_5081_50811201_59_dialog_content = "Que eu, Gronkenstein Ruu, sou o verdadeiro e invicto jogador conhecido como \"B\"!",
  ui_story_5081_50811201_60_dialog_content = "O \"B\" representa \"chefe\", como no chefe final!",
  ui_story_5081_50811300_1_dialog_content = "<color=#e8d9bb>E assim o invencível Gronru é finalmente derrotado.</color>",
  ui_story_5081_50811300_2_dialog_content = "Ufa... Essa foi por pouco. Gronru quase nos venceu.",
  ui_story_5081_50811300_3_dialog_content = "Ter um jogador poderoso como Batia em nossa equipe é extremamente tranquilizador.",
  ui_story_5081_50811300_4_dialog_content = "Acredite em mim, todos deram o seu melhor agora. Sem vocês... Eu nunca poderia ter vencido Gronru...",
  ui_story_5081_50811300_5_dialog_content = "Me vencer? Em seus sonhos! Gronkenstein Ruu nunca pode ser derrotado!",
  ui_story_5081_50811300_6_dialog_content = "Essa era apenas minha primeira forma! Ainda tenho duas formas restantes, cada uma duas vezes mais forte que a última!",
  ui_story_5081_50811300_7_dialog_content = "Aaaaaahhhh—",
  ui_story_5081_50811300_8_dialog_content = "Espere, Gronru... Você está usando códigos de trapaça agora, não está?",
  ui_story_5081_50811300_9_dialog_content = "Isso não é justo de jeito nenhum!",
  ui_story_5081_50811300_10_dialog_content = "\"Justo\"? Essa palavra não existe em lugar nenhum em Astra!",
  ui_story_5081_50811300_11_dialog_content = "Trapaças são apenas outra parte do Jogo de Gronru! Se você não gosta, então saia!",
  ui_story_5081_50811300_12_dialog_content = "Haaaaaahhhh—",
  ui_story_5081_50811300_13_dialog_content = "Espere... Ela está realmente apenas usando trapaças?",
  ui_story_5081_50811300_14_dialog_content = "Por que a sala inteira está tremendo como se fosse se autodestruir?",
  ui_story_5081_50811300_15_dialog_content = "Ela está sobrecarregando a máquina de jogo ao usar muitos cheats?",
  ui_story_5081_50811300_16_dialog_content = "Cada equipamento nesta sala está interconectado...",
  ui_story_5081_50811300_17_dialog_content = "G-Gronru! Se isso continuar, o fliperama inteiro vai explodir!",
  ui_story_5081_50811300_18_dialog_content = "Então que exploda... Eu prefiro que isso aconteça do que perder para você e ter que voltar ao trabalho!",
  ui_story_5081_50811300_19_dialog_content = "Por que eu deveria lidar com todas as consequências quando nada disso foi minha culpa?",
  ui_story_5081_50811300_20_dialog_content = "Que se danem suas regras injustas! Eles estão apenas criando mais trabalho para mim para encobrir seus próprios erros!",
  ui_story_5081_50811300_21_dialog_content = "Esses tolos arrogantes nunca poderiam entender! A única razão pela qual trabalhamos é para aproveitar adequadamente os jogos em nosso tempo livre!",
  ui_story_5081_50811300_22_dialog_content = "Um Astra onde eu não posso jogar à vontade... está destinado a desaparecer, junto com minha terceira forma—",
  ui_story_5081_50811300_23_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5081_50811300_24_dialog_content = "?",
  ui_story_5081_50811300_25_dialog_content = "A tremedeira parou?",
  ui_story_5081_50811300_26_dialog_content = "Sim. Precisávamos tirá-la disso, então eu desliguei a energia das máquinas dela.",
  ui_story_5081_50811300_27_dialog_content = "Você não me culpa, não é Gronru? Além disso, você sempre ativa o auto-salvamento em seus jogos...",
  ui_story_5081_50811300_28_dialog_content = "Eu não me importo mais com meus dados salvos! Eu não vou voltar, mesmo que eu esteja morto!",
  ui_story_5081_50811300_29_dialog_content = "Você é tão patético sem seus truques, Gronru.",
  ui_story_5081_50811300_30_dialog_content = "Isso é rico vindo de você, Yingel! Você não acabou de ser carregado por Batia? Mesmo sem trapaças, você nunca teria chance contra mim em um confronto direto!",
  ui_story_5081_50811300_31_dialog_content = "Talvez sim, mas eu ainda ganhei... Todos nós ganhamos!",
  ui_story_5081_50811300_32_dialog_content = "Nojento... Amaldiçoado seja você!",
  ui_story_5081_50811300_33_dialog_content = "Parem, vocês dois! Eu não os trouxe para desafiá-lo, Gronru! É só...",
  ui_story_5081_50811300_34_dialog_content = "Percebi que você não estava indo tão bem ultimamente... mas eu não sabia como te ajudar...",
  ui_story_5081_50811300_35_dialog_content = "Afinal... Não tenho ideia do que os seus líderes pensam.",
  ui_story_5081_50811300_36_dialog_content = "Mas eu acho que está tudo bem se você não gostar deles, Gronru!",
  ui_story_5081_50811300_37_dialog_content = "É por isso... Eu queria trazer algumas pessoas que você pode gostar!",
  ui_story_5081_50811300_38_dialog_content = "Eu?",
  ui_story_5081_50811300_39_dialog_content = "Sua?",
  ui_story_5081_50811300_40_dialog_content = "D-Não olhe para mim!",
  ui_story_5081_50811300_41_dialog_content = "Isso mesmo! Depois de jogar com eles e contra eles, posso dizer que eles têm uma verdadeira paixão por videogames!",
  ui_story_5081_50811300_42_dialog_content = "E diferente de mim... eles não se escondem em seus quartos todos os dias. Eles são seus colegas, assim como seus amigos.",
  ui_story_5081_50811300_43_dialog_content = "É por isso que acho que eles são melhores em entender seus problemas do que eu.",
  ui_story_5081_50811300_44_dialog_content = "Batia...",
  ui_story_5081_50811300_45_dialog_content = "Então, você poderia por favor considerar isso como eu organizando uma convenção de jogos improvisada no Hidden Fangs?",
  ui_story_5081_50811300_46_dialog_content = "Espero que isso lhe dê a chance de compartilhar seus problemas conosco... para que possamos encontrar um caminho a seguir juntos!",
  ui_story_5081_50811300_47_dialog_content = "*cheira*",
  ui_story_5081_50811300_48_dialog_content = "Aaaaaaaaaah—",
  ui_story_5081_50811300_49_dialog_content = "Não suporto essas reuniões obnoxias ou as montanhas de relatórios que sempre tenho que escrever!",
  ui_story_5081_50811300_50_dialog_content = "Nunca há tempo suficiente para jogar jogos, muito menos restaurá-los... É por isso que decidi me esconder aqui!",
  ui_story_5081_50811300_51_dialog_content = "Eu pretendia terminar meu trabalho naquele jogo de fantasia o mais rápido possível, mas eu estava de tão mau humor que não consegui fazer nenhum progresso...",
  ui_story_5081_50811300_52_dialog_content = "Então pensei: \"Talvez um jogo de Longzhou Tilemaster me ajude a relaxar um pouco...\"",
  ui_story_5081_50811300_53_dialog_content = "Mas uma vez que comecei a jogar, não consegui largar o controle!",
  ui_story_5081_50811300_54_dialog_content = "Disse a mim mesmo que pararia depois de chegar ao oitavo rank, mas continuei até o nono e depois o décimo...",
  ui_story_5081_50811300_55_dialog_content = "Eu estava tendo um péssimo azar o tempo todo, então demorou uma eternidade para fazer qualquer progresso... E agora o lançamento do jogo de fantasia está logo ali...",
  ui_story_5081_50811300_56_dialog_content = "De jeito nenhum vou conseguir chegar a tempo agora!",
  ui_story_5081_50811300_57_dialog_content = "Meu trabalho ainda não está pronto! O jogo ainda não está pronto! Eu não terminei uma única coisa!",
  ui_story_5081_50811300_58_dialog_content = "*soluçando* Por que a vida tem que ser tão difícil? Eu não quero mais jogar—",
  ui_story_5081_50811300_59_dialog_content = "PlayerName! Você tem que me ajudar a me deletar do mundo!",
  ui_story_5081_50811300_60_dialog_content = "E-Ei! Não diga coisas assustadoras assim!",
  ui_story_5081_50811300_61_dialog_content = "Este mundo precisa de você, Gronru! Além disso, a vida nunca foi um jogo para um único jogador...",
  ui_story_5081_50811300_62_dialog_content = "Por que não nos deixa brincar com você?",
  ui_story_5081_50811300_63_dialog_content = "Se enfrentarmos juntos esse palco chamado vida, tenho certeza de que podemos superá-lo com distinção! Seria muito mais divertido do que enfrentá-lo sozinho, pelo menos!",
  ui_story_5081_50811300_64_dialog_content = "Quanto à tortura redundante, desnecessária e estressante em Illumina...",
  ui_story_5081_50811300_65_dialog_content = "... Quero dizer, quanto ao seu trabalho, tenho certeza de que Anatoli e eu podemos ajudá-lo a otimizar alguns desses processos.",
  ui_story_5081_50811300_66_dialog_content = "E quando se trata de restaurar videogames, Odi definitivamente sabe do que está falando!",
  ui_story_5081_50811300_67_dialog_content = "Talvez o No. 33 também possa ajudar!",
  ui_story_5081_50811300_68_dialog_content = "Quanto a mim... Não sou bom em nada além de videogames, mas você sempre pode me pedir para ser seu testador!",
  ui_story_5081_50811300_69_dialog_content = "Você não é apenas bom em videogames, Batia.",
  ui_story_5081_50811300_70_dialog_content = "Todos nós somos jogadores aqui, mas você tem algo especial que ninguém mais tem...",
  ui_story_5081_50811300_71_dialog_content = "Essas são as Presas Ocultas, o destino final para jogadores do mundo todo! Sem mencionar sua reputação como o lendário jogador \"B\"!",
  ui_story_5081_50811300_72_dialog_content = "Apenas pense em todos os desafiantes que você derrotou para proteger seu fliperama hoje!",
  ui_story_5081_50811300_73_dialog_content = "Eu...",
  ui_story_5081_50811300_74_dialog_content = "Batia... Ah, Batiaaaa—",
  ui_story_5081_50811300_75_dialog_content = "V-Vai ficar tudo bem, Gronru! Não chore...",
  ui_story_5081_50811300_76_dialog_content = "Você está toda crescida agora! Você passou de uma garotinha quieta para uma gerente de fliperama confiável!",
  ui_story_5081_50811300_77_dialog_content = "Parece que os discursos de PlayerName são tão eficazes como sempre...",
  ui_story_5081_50811300_78_dialog_content = "C-Como eu disse, eu não sou um NPC!",
  ui_story_5081_50811300_79_dialog_content = "Mas você realmente é incrível! Você lidou com tantos problemas sozinho!",
  ui_story_5081_50811300_80_dialog_content = "Você até lidou com alguém tão irritante quanto Yingel!",
  ui_story_5081_50811300_81_dialog_content = "?",
  ui_story_5081_50811300_82_dialog_content = "Acho que terei que desafiá-lo novamente apenas para mostrar o quão <color=#FFB400>irritante</color> eu posso ser, Oficial de Tecnologia Gronru.",
  ui_story_5081_50811300_83_dialog_content = "Ah, então você quer continuar jogando?",
  ui_story_5081_50811300_84_dialog_content = "De modo algum. Estou apenas lançando um desafio.",
  ui_story_5081_50811300_85_dialog_content = "Heheheh, parece que os videogames realmente podem fazer qualquer coisa acontecer... Eu me sinto muito melhor depois de tudo que aconteceu hoje!",
  ui_story_5081_50811300_86_dialog_content = "Vocês ainda querem me desafiar? Estou pronto para isso, mas só preciso de um tempo primeiro.",
  ui_story_5081_50811300_87_dialog_content = "Quero terminar meu trabalho naquele jogo de fantasia agora mesmo! Depois disso, todos vocês podem ser meus valiosos testadores para o meu trabalho mais recente!",
  ui_story_5081_50811300_88_dialog_content = "Esta é a sua única chance de desafiar o verdadeiro chefe final!",
  ui_story_5081_50811300_89_dialog_content = "Porque depois que eu voltar para a Illumina, essa conquista não estará disponível na versão oficial!",
  ui_story_5081_50811300_90_dialog_content = "Veremos se você tem o que é preciso para desbloqueá-lo em primeiro lugar!",
  ui_story_5081_50811300_91_dialog_content = "Então está decidido? Você finalmente vai voltar para Illumina?",
  ui_story_5081_50811300_92_dialog_content = "... Hunf!",
  ui_story_5081_50811300_93_dialog_content = "Huh? Onde você está indo, Yingel?",
  ui_story_5081_50811300_94_dialog_content = "Você realmente precisa perguntar? Vou fazer um treinamento de última hora antes que ela termine de restaurar o jogo.",
  ui_story_5081_50811300_95_dialog_content = "Não vou parar até derrotá-la tão mal que ela decida desistir dos jogos e voltar a trabalhar de vez.",
  ui_story_5081_50811300_96_dialog_content = "Ah... B-Boa sorte com isso...",
  ui_story_5081_50811300_97_dialog_content = "E você, Batia?",
  ui_story_5081_50811300_98_dialog_content = "Se você concordar, eu gostaria de escolher alguns desses jogos para jogar com você, PlayerName.",
  ui_story_5081_50811300_99_dialog_content = "Ah, entendi! Estes são do seu poleiro, certo?",
  ui_story_5081_50811300_100_dialog_content = "Vamos ver... Álbum Noite Branca 2, hein? Por que não tocamos este?",
  ui_story_5081_50811300_101_dialog_content = "Hã... Certo.",
  ui_story_5081_50811300_102_dialog_content = "Algo me diz que você vai ser muito bom neste jogo. Vamos ver quais escolhas você faz...",
  ui_story_5081_50811300_103_dialog_content = "Claro! Vamos ligá-lo!",
  ui_story_5081_50811300_104_dialog_content = "É realmente a hora de relaxar assim? Vamos desafiar o Gronru novamente em breve, lembra?",
  ui_story_5081_50811300_105_dialog_content = "Estamos apenas jogando videogames, Yingel! Além disso, quem disse que este jogo vai ser fácil? Venha ver por si mesmo!",
  ui_story_5081_50811300_106_dialog_content = "<color=#e8d9bb>E assim, enquanto Gronru dá os toques finais em seu novo jogo, o resto de nós também se senta ao redor dela e joga jogos...</color>",
  ui_story_5081_50811300_107_dialog_content = "<color=#e8d9bb>Juntos, temos uma noite de simples e puro prazer na companhia um do outro.</color>",
  ui_story_5081_50811300_108_dialog_content = "A espera finalmente acabou, pessoal! May Eu apresento a vocês - o jogo de fantasia que vai fazer todo o Astra enlouquecer!",
  ui_story_5081_50811300_109_dialog_content = "Como seus três primeiros jogadores, espero que todos estejam prontos!",
  ui_story_5081_50811300_110_dialog_content = "Meu rifle de precisão está cansado de esperar.",
  ui_story_5081_50811300_111_dialog_content = "Heh, então parece que eu posso definir para a dificuldade mais difícil possível!",
  ui_story_5081_50811300_112_dialog_content = "E vocês dois?",
  ui_story_5081_50811300_113_dialog_content = "Tô pronto!",
  ui_story_5081_50811300_114_dialog_content = "Também vou dar o meu melhor!",
  ui_story_5081_50811300_115_dialog_content = "Bom, então que a contagem regressiva comece! Três! Dois! Um!",
  ui_story_5081_50811300_116_dialog_content = "Vai começar!"
}
return config
